window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["24298931"]={"book":{"id":24298931,"title":"专注力","author":"于尔根•沃尔夫(Jurgen Wolff)","translator":"朱曼","publisher":"机械工业出版社","pubdate":"2013-5","isbn":"9787111420415","tags":["专注力","个人管理","思维","自我管理","时间管理","学习方法","心理学","心理"],"memCount":30},"np":1,"pb":[37],"idx":[{"i":15018,"t":"武林高手的闭关秘籍-MAD","l":"TF1-1","c":"1405-吴先昇教练-庄宇亮","g":1,"p":1},{"i":14016,"t":"学习创造“心流”状态","l":"TF2-2","c":"dididi","g":1,"p":1},{"i":10527,"t":"内化知识的费曼学习法","l":"TF1-1","c":"bookcloud","g":1,"p":1},{"i":9392,"t":"成功具象化","l":"TF2-1","c":"lilyliu","g":1,"p":1},{"i":9384,"t":"“第二自我”策略","l":"TF2-1","c":"芊蓉","g":1,"p":1},{"i":9106,"t":"设定目标的过程应该怎样进展","l":"TF1-1","c":"金艳","g":1,"p":1},{"i":7973,"t":"学习如何认可他人","l":"TF2-1","c":"沁水茶园","g":1,"p":1},{"i":7498,"t":"创造流程，提升目标的专注力","l":"TF1-2","c":"沁水茶园","g":1,"p":1},{"i":7009,"t":"谁说你必须从头开始","l":"TF1-1","c":"Fairyid4","g":1,"p":1},{"i":6662,"t":"如何认可他人","l":"TF1-2","c":"涂晓闻","g":1,"p":1},{"i":6274,"t":"战胜拖延","l":"TF1-1","c":"玲珍","g":1,"p":1},{"i":5914,"t":"向野拆书升级挑战","l":"TF1-2","c":"向野","g":1,"p":1},{"i":5804,"t":"如何保持专注","l":"TF1-1","c":"向野","g":1,"p":1},{"i":5481,"t":"专注力的方法","l":"TF3-1","c":"月宫","g":1,"p":1},{"i":5412,"t":"提高专注力","l":"TF3-1","c":"月宫","g":1,"p":1},{"i":4431,"t":"发现消极行为模式","l":"TF3-3","c":"雨点小","g":1,"p":1},{"i":4113,"t":"一分钟战胜专注障碍","l":"TF1-1","c":"蘭梅","g":1,"p":1},{"i":3910,"t":"消极行为模式","l":"TF3-3","c":"雨点小","g":1,"p":1},{"i":3841,"t":"专注于积极事件为什么重要","l":"TF1-1","c":"家桢","g":1,"p":1},{"i":2843,"t":"如何关注于自己的专注力","l":"TF2-2","c":"李小点","g":1,"p":1},{"i":2740,"t":"如何把新知识内化进自己的知识库","l":"TF2-1","c":"李佳","g":1,"p":1},{"i":1845,"t":"8020法则达成高效人生","l":"TF2-2","c":"房宸","g":1,"p":1},{"i":1425,"t":"达成目标的最有效方法","l":"TF2-1","c":"陈宏玉","g":1,"p":1},{"i":1393,"t":"学会如何认可他人","l":"TF3-1","c":"李青芳（丫头）","g":1,"p":1},{"i":924,"t":"专注力之目标设定","l":"TF1-1","c":"风之弈语","g":0,"p":1},{"i":923,"t":"化简为繁的惊人力量","l":"TF2-2","c":"风之弈语","g":1,"p":1},{"i":922,"t":"  零容忍准则","l":"TF2-1","c":"风之弈语","g":1,"p":1},{"i":906,"t":"穆穆穆穆到正无穷的1-2过级","l":"TF1-2","c":"穆穆穆穆到正无穷","g":0,"p":1},{"i":893,"t":"穆穆穆穆到正无穷的1-1过级","l":"TF1-1","c":"穆穆穆穆到正无穷","g":0,"p":1},{"i":883,"t":"风之弈语的1-2过级","l":"TF1-2","c":"风之弈语","g":1,"p":1},{"i":882,"t":"风之弈语的1-1过级","l":"TF1-1","c":"风之弈语","g":1,"p":1},{"i":739,"t":"如何使用“零容忍策略”","l":"TF1-1","c":"风之弈语","g":1,"p":1},{"i":714,"t":"如何保持积极的心态","l":"TF1-1","c":"风之弈语","g":1,"p":1},{"i":708,"t":"拆书家过级训练及书籍分享","l":"TF1-1","c":"风之弈语","g":1,"p":1},{"i":301,"t":"学会使用二八法则找到工作中最为重要的20%","l":"TF2-3","c":"枫树","g":1,"p":1},{"i":115,"t":"用MAD创造MAX生产力","l":"TF3-3","c":"思考琦","g":1,"p":1},{"i":109,"t":"如何理智消费信息","l":"TF3-3","c":"思考琦","g":1,"p":1}],"ms":[{"id":15018,"topic":"武林高手的闭关秘籍-MAD","learn_goal":"","remark":"这本书的作者是【英】于尔根·沃尔夫，通过使用MAD来大幅提升一个人的工作效率，让原本艰难的工作任务，缩短工期，加快进度，相当于武林高手如何闭关的秘籍！","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"1405-吴先昇教练-庄宇亮","city":"杭州市"},"club":{"name":"杭州雷峰塔筹备分舵","city":"杭州"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是庄宇亮，欢迎大家来到我TF1-1的拆书现场，我用三个标签来介绍我自己\u003c/p>\u003cp>【职业】公务员，擅长各类公文写作，踏实肯干靠谱，曾被评为年底单位先进个人以及连续多年优秀党员\u003c/p>\u003cp>【兴趣】善于快速阅读和持续输出写作，目前正在出版一本励志小说\u003c/p>\u003cp>【价值观】终身成长者，不局限于自己思维模式，不断探索人生可能性\u003c/p>\u003cp> 总而言之，我是攻守兼备的人，既过的了安稳的日子，也有能力有信心挑战未来！\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>拆书：拆书是一种高效的成人学习方法论，能帮助成年人解决时间精力少，没时间看书的痛点，学习方法为RIA便签学习法，R是阅读原文片段，I是用自己的话阐述原文知识点，A1为联系自身经验和A2为列出具体可行清晰的行动计划，通过三张便签的学习，能让我们把书中技能知识，拆为己用，让知识落地。学习形式又分为个人学习和组织学习，组织学习更多倾向于引导和促进一群人把知识拆为己用，用一本书30多块钱的价格，拆出几万元的培训效果！\u003c/p>\u003cp>拆书帮：拆书帮就是这样一群基于拆书学习爱好者的社群，创始人是赵周老师，而且还是非营利性组织，设为总舵和各地拆书帮分舵，目前组织正在向海外延伸，它的使命愿景是通过陪伴赋能、拆为己用、反求诸己，持续精进，共同成长，来帮助拆书家升级学习力，影响身边的人，从而让世界变得更好一点\u003c/p>","ratings_count":1,"texts":[{"id":19024,"quote":"\u003cp>片段来源：《专注力》 P164页 \u003c/p>\u003cp>【R:阅读原文片段】 \u003cstrong>用MAD创造动力\u003c/strong>\u003c/p>\u003cp>大多数项目都有进度减慢、延迟或其他不顺利的事发生的时候，这不仅会减弱参与者的动力，也会削弱士气。这是使用高度专注技巧的好时机，我将这一技巧称为MAD：大规模行动日（massive action day首字母的缩写）。这一天你抛开其他所有事，集中全部注意力，在8个、10个或12个小时内完成平时可能要花一星期才能完成的事。当然你并不会想要一直保持这个速度；这和长跑运动员要超过对手时所进行的冲刺道理相同。它能够给项目注入新的能量，能够重振你和其他人的热情和信心。以下是如何进行MAD的方法：\u003c/p>\u003cp>■提前一天准备好所有必需物品和文件。在大规模行动日，你不想为寻找文件、钉书钉或任何其他东西而浪费一点时间。\u003c/p>\u003cp>■在大规模行动日开始时为这一天设定明确的目标。制定一份以小时为单位的行动计划。完成每项任务后在计划表上相应做出记号，保持享受任务完成所带来的成就感。\u003c/p>\u003cp>■每90分钟休息一次。研究表明，90分钟是注意力集中的循环周期，所以每过一个半小时休息10分钟将会比连续工作更具成效。\u003c/p>\u003cp>■在休息时做些体力活动：绕建筑物快走或者上下楼梯，伸展运动甚至原地跑步都可以。你可以做任何能够加速血液流动的事。\u003c/p>\u003cp>■保证大量饮用水和健康零食的供给。如果你通过喝咖啡或者喝茶来保持警醒，要少量多饮，而不要多量少饮。\u003c/p>\u003cp> ■在大规模行动日结束时，进行庆祝并给自己一定的奖励——一顿丰盛的晚餐，看场电影，或者任何其他你喜欢的事。\u003c/p>","explains":"\u003cp>在日常工作当中，在完成一些有难度的任务时候，总有各种各样的现实因素会导致你的工作任务拖延、停滞，时间久了，你的信心和热情就会逐渐丧失，甚至你的工作积极性都会降低，以后一遇到这种有难度的工作任务，抗拒性就比较强，能推就推，长远的来看，对个人及事业发展有着不小的损害。\u003c/p>\u003cp> 其实这个问题的关键在于，这些有难度的任务是需要高度集中注意力且需大量的时间精力，而我们平时错误的分配了时间精力，要解决一下“短时间内无法攻破的难题”，我们需要重新整合资源，集中全部精力和时间来攻破，这个方法就是MAD,简称大规模行动日，利在1天之内，8到12小时之间，集中所有时间精力，只专注一件难事，其他的一律不管，一鼓作气完成平时需要1周时间完成的高难度任务。\u003c/p>\u003cp>具体步骤可以这样做：\u003c/p>\u003cp>\u003cstrong>1.设定明确目标。\u003c/strong>设定任务计划表，分解小任务，设定好时间，按节奏推进工作任务，掌控任务进度，让自己有成就感。\u003c/p>\u003cp>\u003cstrong>2.做好准备工作。\u003c/strong>准备好任务所需的物品和文件，在任务推进时，省去找的麻烦事，并准备好大量的水和零食。和家人同事说好，这段时间禁止打扰，留出大段的时间。\u003c/p>\u003cp>\u003cstrong>3.按时做好休息。\u003c/strong>每90分钟休息一次，为高度集中的注意力放松，并做些体育运动，上下楼梯、做俯卧撑都行，主要是为了加速血液循环。\u003c/p>\u003cp>\u003cstrong>4.庆祝给予奖励。\u003c/strong>在任务完成的时候，及时庆祝自己，做一件自己喜欢的事情，产生正向循环，让自己产生对完成高难度任务的正面感觉。\u003c/p>\u003cp>这个“大规模行动日”方法,适合于加快推进高难度任务的时候使用，以及项目进度明显落后，赶进度的时候，集中人力物力进行短时间内攻坚冲刺，不适合在日常工作天天用，毕竟这非常消耗时间精力。也比较适合个人学习工作使用，在需要多人配合的时候，需要提前安排好一切，做好沟通\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp> 记得大学期间，我读的是计算机应用技术，其中有一门课程叫做《计算机电路技术》，这本课其实非常的难懂，而且也非常的枯燥和非常多的专业术语，听课的时候，叫人昏昏欲睡，欲哭无泪，可是偏偏期末的时候，需要考这门课程，于是我就花了周六、周日两天的时间，集中所有精力和时间，不玩游戏，不社交，把这本课的书本以及网上查询打印的考试攻略都下载好，认认真真的研究了2天，还做了思维导图，神奇的是，其他我感兴趣的功课竟然都没这门无聊课程考的高，我竟然得了90多分。\u003c/p>\u003cp>反思：虽然当时没有直接接触这个知识点MAD(大规模行动日)，但确实是应用起来了，按照我当时的说法，就是闭关，一门心思，一鼓作气拿下。其实这就是MAD，集中所有力量，包括时间和精力，目标是拿下这门课程，还细分了一些阶段小任务，包括练习习题集，制作思维导图，难重点攻破等等，时间上因为是整本书的复习，用了2天，相当于使用了2次MAD，虽然少了休息和奖励环节，但做好了所有的前期准备工作，如咨询老师重点是什么，网上下载习题集，让我在闭关期间，节约了不少时间。\u003cbr> A2：\u003c/p>\u003cp>【目标】在12月31日（星期六）当天，早上5点开始，截止中午11:00期间，6个小时，训练TF1-2的所有环节，一举拿下TF1-2。\u003c/p>\u003cp>【MAD】\u003c/p>\u003cp>\u003cstrong>1.设定明确目标。\u003c/strong>训练TF1-2所有流程，限定时间为15分钟，模拟演练一遍，并制作TF1-2 PPT。对着镜子，自己演练一遍，是否时间够，是否能脱稿，是否流畅！\u003c/p>\u003cp>\u003cstrong>2.做好准备工作。\u003c/strong>提前在百度上下载好PPT模板页面，准备好RIA片段内容，还有水和自己最喜欢吃的零食（薯片）以及饼干，为了集中所有注意力，不吃早饭了，并跟家人说好，5点-11点期间，不准打扰。\u003c/p>\u003cp>\u003cstrong>3.按时做好休息。\u003c/strong>90分钟休息一次，在手机上设置好闹钟，休息10分钟，做10个仰卧起床，做10个俯卧撑，加速血液循环，避免长时间的坐姿，引起的身体僵硬和肌肉酸爽，第二个90分钟，去楼下呼吸新鲜空气，第3个自由决定休息10分钟，以此类推，做好休息。\u003c/p>\u003cp>\u003cstrong>4.庆祝给予奖励。\u003c/strong>如果完成，奖励自己看一部电影，是我最喜欢看的电影《小丑回魂2》，以前一直想看，但没时间看，这次刚好作为奖励。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1673218561000,"updated_at":1673419781000,"ria":true},{"id":14016,"topic":"学习创造“心流”状态","learn_goal":"","remark":"大部分人都有同时做几项计划的习惯，且很多人认为几项计划并不多，有信心完成计划目标。但是计划虽美，实操可能一地鸡毛。比如在面对任务时，总是难以进入状态，心神不定，焦虑不已，快到节点的时候才匆匆应付随意交差。但是偶然我们也会进入一种分外清醒，既紧张又兴奋，可以持续专注又不被干扰的状态，这时候效率飞快，任务不知不觉就完成了，时间转瞬即逝。这时候你可能会恍然，“咦，为什么我很少有这种状态呢？”我们一起来学习怎么创造这种“心流”。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"dididi","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>各位小伙伴大家晚上好，我是今晚的第二位拆书家dididi,我刚刚已经完成了我的自我介绍，现在我们直接进入今晚的拆书环节。\u003c/p>\u003cp>今晚拆解的片段来自于一本书《专注力：化繁为简的惊人力量》。\u003c/p>\u003cp>\u003cstrong>【F】特征\u003c/strong> \u003c/p>\u003cp>本书作者是英国的一名作家叫尔根·沃尔夫，他同时也是研究高效方法的咨询顾问。这本书通过一些工具和方法教会读者认清追求目标过程中的阻碍因素，如何去解决，并且学会如何做得对、做得快、做得准；这本书是提供了很多实操方法的工具书。\u003c/p>\u003cp>\u003cstrong>【A】优势，比较：\u003c/strong>\u003c/p>\u003cp>这本书的豆瓣评分是7.0分。相比于其它同类书，这本书的亮点在于提供简明有效的实操工具；相比于英译汉的书，这本书的语言更简练易懂。\u003c/p>\u003cp>\u003cstrong>【B】利益：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【B1】：\u003c/strong>读完这本书，我们会认识到。想要过高效的人生，我们要先知道是什么在影响我们的效率并调整它，再逐步的做正向的规划。\u003c/p>\u003cp>\u003cstrong>【B2】：\u003c/strong>\u003c/p>\u003cp>不知道大家有没有遇到过这样的情况，我们有时候要做一项任务，比如写文章，做方案，一开始怎么都进入不了工作状态。虽然很想沉下心尽快完成，但是头脑迟钝，内心焦虑，进而会做其它事情替代这个工作；有时候工作状态又超好，思路清晰，大脑飞速运转，几乎忘记周围的一切。\u003c/p>\u003cp>那你就会很疑惑，为什么很难遇到那种“分外清醒”的状态呢？我们能不能去锻炼进入这种状态的能力而不是一味的等待它的出现？今晚的学习，我们一起来揭晓。\u003c/p>\u003cp>我们需要分个小组，那就按照上一个拆书家的分组来吧。\u003c/p>","ratings_count":1,"texts":[{"id":18026,"quote":"\u003cp>接下来，请大家快速浏览拆页，读完后抬头示意我下，时间1分钟。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】：\u003c/strong>\u003c/p>\u003cp>这个片段告诉我们，所谓的人间清醒也就是持续专注的状态其实是可以锻炼出来的。不加以锻炼的情况下只能任由“灵感驱动”，克服不了专注障碍。\u003c/p>\u003cp>\u003cstrong>【WHY】：\u003c/strong>\u003c/p>\u003cp>（一般人的做法）写一个方案，写一篇文章，不知道如何写第一句，于是翻看《文案学习技巧》类的书籍，换一换写作软件的主题背景，字体颜色，甚至说时间管理不好，先去网上买一个番茄钟回来，于是刷淘宝买计时器。做这些工作，都不能让我们进入工作状态，越做越烦躁。\u003c/p>\u003cp>（坏处）如果不像片段中提到的这三个方法去锻炼，那么你可能就不知道怎么克服自己的专注障碍。\u003c/p>\u003cp>为此本来两天就可以完成的事情你也许要用10天，工作效率大打折扣；甚至于会让你一直处于特别焦虑的状态，因为你是知道自己在拖延的，但是你找不到改变的方法。所以可以用这个片段的方法去锻炼。\u003c/p>\u003cp>那怎么锻炼呢？\u003c/p>\u003cp>\u003cstrong>【HOW】：\u003c/strong>\u003c/p>\u003cp>（1） 选一个在你能力范围之内的或者稍微高一点的工作。也就是我们先设计一个任务，这个任务具有一定挑战性。这个不是说凭空找一件事情来做，你可以梳理一下你的工作计划、个人计划里面有哪项是符合这个特征的。\u003c/p>\u003cp>（2） 设计完任务之后，要给这个任务添加一些即刻反馈的内容或者机制，让自己保持对这个任务有乐观积极的态度。就像我在做企业品牌战略方案的时候，有些内容我不会写的时候，我会去找同事聊天，甚至去找老板聊天，聊完之后又写下去了。\u003c/p>\u003cp>\u003cstrong>（3）\u003c/strong> 在你执行这个任务的过程中，一定要选一个让你最能集中精力的环境。除了物理空间的环境，也可以准备利于身心的工具等等。对我来说，咖啡+空旷的场地+白噪音就是我最能静下来的地方，所以咖啡馆、办公室都是我专注的场所\u003c/p>\u003cp>\u003cstrong>【举例子】\u003c/strong>\u003c/p>\u003cp>举个例子来说，我前段时间在写品牌策略方案的时候。整个过程我花费了一个多月，后面我再复盘的时候发现我的效率真的很低，很多时候我写不下去我就会先去忙别的事情，还有我每周五都把所有文件资料拷回家，想着周末在家沉下心来做，两天就完成了，事实是在家里我一刻都安静不下来。总是时不时吃点零食，刷刷视频，洗衣服洗鞋子，就是没办法好好做方案。\u003c/p>\u003cp>\u003cstrong>【拆页反思】：\u003c/strong>\u003c/p>\u003cp>所以反观这个片段，我可以去完善很多地方；就是书中提到的内容我们平时是意识到不那么做就会影响自己，但是我们还是没有做。\u003c/p>\u003cp>\u003cstrong>【正面例子】：\u003c/strong>\u003c/p>\u003cp>（1）所以下一次我还是会多去尝试一些有挑战性的工作；\u003c/p>\u003cp>（2）要即刻反馈，不断刺激自己的信心。多和同事、朋友沟通讨论，借由他们打开我的思路，印证自己的想法并尽快实施。\u003c/p>\u003cp>（3）不要太相信自己的意志力，特别是在家办公这件事，周末要加班就去咖啡馆办公。\u003c/p>\u003cp>\u003cstrong>【预防异议】：\u003c/strong>\u003c/p>\u003cp>关于这个方法大家会觉得，看起来容易，但是很难做得到呀，没有那么多只属于自己的时间只做一件事。\u003c/p>\u003cp>关于这一点我们要注意，这个方法不是要我们在固定的一段时间内保持专注，而是要我们随时进入专注状态和一件事里保持专注。比如我写方案写到一半了，我又得去忙别的事，忙完再写的时候，我马上就能接着之前的内容专注继续写下去，做什么专注什么。\u003c/p>\u003cp>而不是再回来的时候，啊~又不知道怎么接着写了，先刷会视频放松一下。\u003c/p>\u003cp>\u003cstrong>【适用边界】：\u003c/strong>\u003c/p>\u003cp>这个方法比较适用于有一定挑战性的，需要个人独立思考完成的工作。而不适用于受外界因素影响的事情，比如做项目预算不够、同事不配合等因素。\u003c/p>","interaction":"\u003cp>A2催化：\u003c/p>\u003cp>\u003cstrong>拆书家提问：\u003c/strong>\u003c/p>\u003cp>那大家想一想，接下来的一周或者一个月的时间内，你准备用这个三步法去做什么事情呢？给大家思考一下，1分钟，等会请一个小伙伴分享。\u003c/p>\u003cp>小伙伴（若水）分享：\u003c/p>\u003cp>想要用这个方法去写作，写出一篇文章。\u003c/p>\u003cp>A2+ 现场加工：\u003c/p>\u003cp>\u003cstrong>拆书家引导：\u003c/strong>\u003c/p>\u003cp>再给大家3分钟时间讨论，你该如何用三步法去完成你刚才想要做的事，等会请刚才的小伙伴接着分享。其它小伙伴可以写在笔记本或者片段上。\u003c/p>\u003cp>小伙伴（若水）分享：\u003c/p>\u003cp>对于写稿子的规划\u003c/p>\u003cp>前两天写出了稿子发现很多段落，句子不通顺，想要改但是越看越心烦，过了好几天也不管。因此接下来要计划\u003c/p>\u003cp>(1) 在1周内（这个礼拜）时间内把稿子改得更完美，（内容质量更高）读起来更吸引人（这个目标有一定挑战性）；\u003c/p>\u003cp>(2) 给自己一些好吃的作为改稿子的奖励，且完成后还要奖励自己去吃一顿更好的。\u003c/p>\u003cp>(3) 选每一天不被打扰的时间，也就是早上7点左右，来做这件事情。\u003c/p>\u003cp>通过这个方法来保持自己写稿子的专注性，保证任务按时完成。\u003c/p>\u003cp>拆书家：看来小伙伴学习能力都很强，都学会了现场即学即用。\u003c/p>\u003cp>好了，今天我们主要学习的是用三步法去克服工作中的专注障碍，以保证我们持续的专注力，达到心流状态。希望大家今后可以把这个方法顺利应用在工作生活中，过更高效的人生。谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1661108860000,"updated_at":1664154758000,"ria":true},{"id":10527,"topic":"内化知识的费曼学习法","learn_goal":"","remark":"运用费曼学习法，掌握学习的技巧","level":"TF1-1","duration":11,"status":30,"type":0,"chaishujia":{"username":"bookcloud","city":""},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>自我介绍 1分钟\u003c/strong> \u003c/p>\u003cp>大家好，(边手指自画像边説)我是爱看书的\u003cstrong>苏.晓.筠\u003c/strong>，我的三个标签:\u003c/p>\u003cp>第一个标签是-\u003cstrong>网页设计师\u003c/strong>-美感是我对自己的基本要求,目标是做出感动人心的设计!\u003c/p>\u003cp>第二个标签是-\u003cstrong>图文笔记法\u003c/strong>-目前爱用知识卡片笔记法。\u003c/p>\u003cp>第二个标签是-\u003cstrong>断捨离实践者\u003c/strong>-从初阶的整理物品到进阶的整理人生或无形物。\u003c/p>\u003cp>\u003cbr>期待今天与大家共同学习成长!\u003c/p>\u003cp>\u003cstrong>拆书帮介绍 2分钟 \u003c/strong>\u003c/p>\u003cp>先跟大家介绍简单的介绍何谓“拆书”？\u003c/p>\u003cp>\u003cstrong>拆书\u003c/strong>是一种有效的学习方法，目的是将书拆为己用, 解决你工作或生活中实际遇到的问题也可以提升能力。\u003c/p>\u003cp>拆书又分为\u003cstrong>个人学习法和组织学习法\u003c/strong>。\u003c/p>\u003cp>个人RIA便签拆书法，\u003cbr>R是英文的Rreading指阅读原文片段，若以一本書為例，就大約是二頁以內的內容，\u003cbr>I是Interpretation 系统化地梳理知识点，\u003cbr>A则是Appropriation 连结自己过去经验和未来规划。\u003c/p>\u003cp>而组织学习法-则是由拆书家引导多位学习者将书拆为己用。\u003c/p>\u003cp>“\u003cstrong>拆书帮\u003c/strong>”是由大陆赵周老师创立的非营利组织，\u003c/p>\u003cp>分为\u003cstrong>正式分舵与筹备分舵\u003c/strong>，筹备分舵需在一年内产生三名三级拆书家或五名二级拆书家才能升正。\u003cbr>台湾目前藉由各伙伴们拆书练级，以达到成立正式分舵的标准。\u003c/p>\u003cp>拆书帮除了推广拆书法外，更希望能帮助更多人成为将书拆为己用甚至帮助他人的拆书家。\u003c/p>\u003cp>接下来要正式进入今天分享的主题—内化知识的费曼学习法\u003c/p>","ratings_count":2,"texts":[{"id":14380,"quote":"\u003cp>\u003cstrong>R 阅读原书拆页 １分钟 \u003c/strong>\u003cbr>\u003c/p>\u003cp>請大家開始閱讀剛發給大家的文章，看完後舉手一下，讓我知道。\u003c/p>\u003cp>片段主题：内化知识的费曼学习法\u003c/p>\u003cp>片段来源：《专注力》\u003cbr>\u003c/p>\u003cp>\u003cstrong>R-原文片段\u003c/strong>\u003cbr>当面对一个\u003cstrong>很难的概念或者理论\u003c/strong>的时候，如何迫使自己真正理解它。\u003c/p>\u003cp>费曼学习法：如果我需要讲解给别人听，我会如何讲？\u003cbr>\u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>选择一个概念\u003c/strong>选择一个你想要理解的概念。拿一张白纸，将这个概念的名称写在这张白纸的顶部。\u003c/p>\u003cp>\u003cbr>\u003cstrong>第二步：\u003c/strong>\u003c/p>\u003cp>想象你正要把这个概念\u003cstrong>教授给一名新生\u003c/strong>写出这个概念的一个解释，就好像你正在把这个概念讲述给一个还没有理解该主题的人那样。这是一个非常关键的环节，因为，在你把一个你已经明白，或者你还没有明白的概念解释给自己过程中，你能够获得更好的理解，并且可以精准地定位那些你仍不知道的细节。\u003c/p>\u003cp>\u003cbr>\u003cstrong>第三步：\u003c/strong>\u003c/p>\u003cp>如果你\u003cstrong>遇到问题，请原路返回\u003c/strong>只要你在一个地方遭遇疑惑或者问题，那么请回到相应的参考资料、教程，或者，到教学助理那里去吧，重新阅读或者再次学习这些材料，直至达到能够通过书面方式解释给别人的程度。\u003c/p>\u003cp>\u003cbr>\u003cstrong>第四步：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>简化并建立类比\u003c/strong>不管你的解释有多啰唆或者如何令人迷惑，请尝试简化你的描述用语，或者创建一个类比，以便于更好地让别人理解。\u003c/p>","explains":"\u003cp>\u003cstrong>分享I便签 3分钟 \u003c/strong>\u003cbr>\u003cbr>\u003cstrong>（why）\u003c/strong>\u003c/p>\u003cp>大部分人的学习大多只停留在\u003cstrong>被动输入，\u003c/strong>像是简单的看过或听过，\u003cstrong>记忆不深\u003c/strong>，學的淺也忘的快。\u003c/p>\u003cp>尤其是知识点\u003cstrong>再複杂抽象\u003c/strong>一点时，就容易\u003cstrong>模煳略过\u003c/strong>。\u003cbr>但若越少动脑深思，就更无法读的更精深，学习效果有限。\u003c/p>\u003cp>\u003cstrong>（what）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>费曼学习法\u003c/strong>源於諾貝爾物理獎獲得者\u003cstrong>理查德•費曼\u003c/strong>，比尔盖兹曾称赞他为\u003cstrong>世界上最棒的教师\u003c/strong>，它是一种\u003cstrong>以教为学\u003c/strong>主动输出的学习方法。\u003c/p>\u003cp>运用對小白讲解找出自己的學習盲點，帮助自己对知识的深入理解与吸收。 \u003c/p>\u003cp>\u003cstrong>（how）\u003c/strong>\u003c/p>\u003cp>费曼学习法具体做法如下：\u003c/p>\u003cp>\u003cstrong>一、选一概念\u003c/strong>\u003c/p>\u003cp>选择一个\u003cstrong>对自己觉得较难的概念或理论\u003c/strong>，可以是新知或是检视旧知是否学习透彻。\u003c/p>\u003cp>用白纸或白板甚至是餐巾纸，将它写在最上方。\u003cbr>\u003c/p>\u003cp>\u003cstrong>二、对小白讲解\u003c/strong>\u003c/p>\u003cp>想像要如何说才能让完全不懂的人甚至是\u003cstrong>10岁的小朋友也能理解\u003c/strong>，语句要\u003cstrong>浅白易懂\u003c/strong>不要使用专有名词，可以举例或用图解辅助说明。\u003c/p>\u003cp>若没有实际对象，也可以用写作或录视频或直接拿家人当讲解对象。\u003cbr>\u003c/p>\u003cp>\u003cstrong>三、遇问题再学\u003c/strong>\u003c/p>\u003cp>备课讲解过程中，若有\u003cstrong>卡关或不顺\u003c/strong>的地方，就是自己不够理解的地方，就需要回去再找\u003cstrong>资料或请教人\u003c/strong>。回到第二步骤，讲到自己觉得顺为止。\u003c/p>\u003cp>实际对小白讲解时，对小白的提问无法回答时，也是检视自己在哪裡仍学的不透彻，需要再学习的地方。\u003cbr>\u003c/p>\u003cp>\u003cstrong>四、简化比喻\u003c/strong>\u003c/p>\u003cp>用通俗简单的比喻来类比简化你所要传达的概念，不但让他人易理解更能昇华自己的理解。\u003c/p>\u003cp>\u003cstrong>（Where）\u003c/strong>\u003c/p>\u003cp>选择的概念或理論需要對＂\u003cstrong>自己\u003c/strong>＂來說，具有一定难度或複杂度，需要挑戰自己習慣的學習舒適圈，例如：专业术语。\u003cbr>若是自己覺得太简单明瞭的知识点，就不适用。\u003c/p>","interaction":"\u003cp> \u003cstrong>A1（激活过去经验） 2分钟 \u003c/strong>\u003c/p>\u003cp>今年5月早上，同事那天她跟我抱怨上司对她的不公平，让她感到生气和难过，考虑离职。\u003c/p>\u003cp>刚好我前几天看了一本有趣的图解书＂工作哲学图鑑＂，裡面有个写让人脱离不开心的正向概念-\u003cstrong>关注圈和影响圈\u003c/strong>。\u003c/p>\u003cp>我就教同事这个方法，\u003c/p>\u003cp>我说：我们生活中会遇到一个大圈叫\u003cstrong>关注圈\u003c/strong>（手比大圈），很多人都会因为它而烦恼，但这个关注圈裡面有很多我们无法掌控的事物，我们无法改变它，\u003c/p>\u003cp>EX：同事态度、外在环境。\u003c/p>\u003cp>相对的裡面也有一个小圈叫\u003cstrong>影响圈\u003c/strong>。（手比小圈）它相对可控，我们可以掌控或是改变它。\u003c/p>\u003cp>EX：我对长官的应对方法。如果我们把注意力多放在影响圈，我们将会努力在我们可以掌控改善的地方，并看见它的成长与进步.....\u003c/p>\u003cp>\u003cbr>\u003cstrong>结果\u003c/strong>：同事也许情感上有倾诉对象，所以到目前没有离职。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>\u003c/p>\u003cp>其实我并不是一开始就刻意要以教为学。而且我当时对这个理论的正式名称或是来源都不甚清楚，所以可见我当时也没做到3遇问题查缺漏和更精进的4简化类比。整体而言，没有这些事前有意识的准备，所以同事的吸收成效就有限。\u003c/p>\u003cp>\u003cstrong>A2 （规划未来应用）3分钟 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件背景：\u003c/strong>\u003c/p>\u003cp>儿子最近有不开心有跟我预约晚上聊聊。\u003cbr>\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>\u003c/p>\u003cp>10/11下午，傾聽完儿子吐完苦水后，我應用关注圈和影响圈的講解，引導儿子找出自己問題的影响圈在哪裡。\u003c/p>\u003cp>\u003cstrong>行动：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、选一概念\u003c/strong>：关注圈和影响圈\u003cbr>\u003c/p>\u003cp>\u003cstrong>二、对小白讲解\u003c/strong>\u003c/p>\u003cp>许多人的烦恼来源，不外乎两种，\u003c/p>\u003cp>一个是关注圈(画一个大圆圈)，一个是影响圈(大圈内画一个小圈)，\u003c/p>\u003cp>大部分的人只注意这个自己无法改变的关注圈，EX:环境、他人、过去。而这些不可控（写Ｘ不可控）\u003c/p>\u003cp>而忽视了裡面还有一自己可以改变的个影响圈，EX: 心态、学习、现在。这些是相对可控(写O可控)\u003c/p>\u003cp>如果你选择忽视让人无力的关注圈，专注在可控的影响圈，你会看到你的努力会有回报而更加进步，也因此有能力扩大你的影响圈，关注圈就相对变小。\u003cbr>\u003c/p>\u003cp>\u003cstrong>三、遇问题再学\u003c/strong>\u003c/p>\u003cp>中途有任何问题，先记录下来，事后再看书找答案，若还有疑问，再问师父。\u003c/p>\u003cp>解惑后，再和小孩讲解一次。\u003cbr>\u003c/p>\u003cp>\u003cstrong>四、简化比喻\u003c/strong>\u003c/p>\u003cp>关注圈和影响圈就像住在你肩膀上的恶魔（手比左肩上）与天使（手比右肩上），\u003c/p>\u003cp>你要常放你的天使影响圈出来跟你说：你太棒了，你又更进步了！还是\u003c/p>\u003cp>恶魔关注圈出来说：你太弱了，你什麽也改变不了！\u003c/p>\u003cp>选择完全取决于你。\u003c/p>\u003cp>\u003cstrong>说完后，问儿子\u003c/strong>\u003c/p>\u003cp>针对你的目前遇到的问题，你觉得什麽是你的关注圈？什麽是你的影响圈？让他区分这二者的差异。\u003c/p>\u003cp>你现在決定要关注的是哪一个？引导他关注在正向的影响圈。\u003c/p>\u003cp>\u003cstrong>結語\u003c/strong>\u003c/p>\u003cp>以上是我的分享，\u003cstrong>拆书练级也是类似费曼的以教为学学习法\u003c/strong>。\u003c/p>\u003cp>瞄准月亮至少射中老鹰，相信我们已走在最棒的成长路上。谢谢大家。\u003cbr>\u003c/p>\u003cp>（附上学习关注圈和影响圈后做的知识卡片。）\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1602417495000,"updated_at":1604407132000,"ria":true},{"id":9392,"topic":"成功具象化","learn_goal":"通过运用“五感具象法”增强对正确选项的选择力量，增强执行力。","remark":"这是由英国作家于尔根 ・沃尔夫所写的一本简明的自我管理类书籍。本书用简洁易懂的语言介绍了提升专注力的5大有效策略和工具。并且配有很多实际的练习，实操性非常强。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"lilyliu","city":"绍兴市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp;\u003cstrong>学习目标\u003c/strong>&nbsp;\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在了解了“正确”选项和“错误”选项的基础上，通过学习和操练“五感具象法”，在面对“正确”选项和“错误”选项时，能把正确选项完成后的结果画面具象化，增强对正确选项的选择力量，增强执行的可能性。&nbsp;\u003c/p>\u003cp>\u003cstrong>（技能点：开场与分组）&nbsp;\u003c/strong>\u003c/p>\u003cp>各位亲爱的小伙伴，大家晚上好！欢迎大家来参加绍兴阳明筹备分舵的线下拆书活动。先自我介绍一下，我是lily。一名高中英语教师，是一名新手拆书家，也是一名终身学习者。今天我要在这里进行2-1的过级拆，今天的活动会进行讨论和分享，所以我们先分一下小组，2-3人一组。好，大家都已经找到了自己的伙伴。\r\n &nbsp;\u003c/p>\u003cp>\u003cstrong>（技能点：图书介绍）\u003c/strong>\u003cbr>\u003c/p>\u003cp>今天我的拆页来源于书籍《专注力：化繁为简的惊人力量》。\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>FEATURE\u003c/strong>\u003cstrong>：\u003c/strong> 这是一本简明的自我管理类书籍。全书包括找到专注的焦点，专注策略，专注工具和归纳总结四个部分。作者是英国知名作家、编剧于尔根·沃尔夫。\u003c/p>\u003cp>\u003cstrong>ADVANTAGE\u003c/strong>\u003cstrong>：\u003c/strong>这本书中没有很大篇幅的理论赘述，而是用简洁易懂的语言告诉读者提升专注力的5大有效策略和工具，并且配有很多实际的练习，实操性非常强。无论在亚马逊还是豆瓣，很多读者都给予了很高的评价，认为它既通俗易懂又能提升行动力。\u003c/p>\u003cp>\u003cstrong>BENEFIT \u003c/strong>\u003cstrong>：\u003c/strong>不知大家是否有这样的经历：你想专注于你的工作，但外来的事物总是来干扰你的注意力，可能是手机也可能是你的同事，无法专注导致工作被拖延，目标无法实现。本书提到的5大提升专注力的有效策略可以帮助解决这些问题。而今晚的拆页便来源于其中一个策略即通过“具象化”想象，来提升你的专注力，提升你排除干扰的能力，使你在日常的生活工作中减少拖延，让你成为一个行动力强大的人，让拖延不再成为你成功路上的一大障碍。\u003c/p>\u003cp>听完后大家是不是对我的拆页产生了兴趣？接下去我把拆页分发给大家，请大家阅读原文。时间是2分钟。阅读完成请抬头示意我。\u003c/p>","ratings_count":1,"texts":[{"id":13193,"quote":"\u003cp>【R】阅读原文拆页\u003c/p>\u003cp>片段来源：《专注力：化繁为简的惊人力量》\u003c/p>\u003cp>作者：【英】于尔根·沃尔夫\u003c/p>\u003cp>主题：成功的具象化 P72-73\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 巧克力蛋糕看起来很棒,闻起来很香,舌尖上的感觉很柔滑细腻,味道好极了!保持身材的想法…呃,嗯,这是个很好的想法……有的时候,比如我们满怀深深的愧疚,这确实有点效果。但不幸的是,这种事情通常只在我们过分放任自己的情况下才会出现。\u003c/p>\u003cp>这里有个办法可以让你每次做出更好的选择:选择“正确”选项的秘诀就是将正确的选项变得和“错误”选项一样生动,一样富有感情,一样的吸引人。怎样才能做到这一点?发挥你的想象力,用比感知“错误”选项更强烈的态度去观察、倾听、品尝、闻、感受“正确”选项。\u003c/p>\u003cp>■闭上你的双眼,开始想象“正确”选项将带来的结果。这很重要:不要想象你做这件事情的过程,想象最终结果或者一个阶段性的成果。\u003c/p>\u003cp>■当完成这件事你将看到什么?比如,你刚开始为自己的生意写经营计划,当生意取得成功,你将看到什么?如果你所经营的生意是一家店铺,你可以想象店堂里充满热情的顾客。\u003c/p>\u003cp>■你将听到些什么?可能你会想象顾客称赞你所销售的货物,或者把你的生意打电话告诉他们的朋友。\u003c/p>\u003cp>■你将感受到什么?这可能是最重要的部分,可能你会觉得骄傲、开心、兴奋和欢乐。\u003c/p>\u003cp>■有时候你可以想象一些味道。你可能会想象自己在闻一些摆放在柜台上鲜花的味道。\u003c/p>\u003cp>■甚至味觉也能成为一个因素。你可能会想象举办一场晚宴来来庆祝开业,有人向你敬酒,你喝了一杯香槟。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 你想象得越生动越令人兴奋,你就能为开始这项工作释放更多的力量。\u003c/p>","explains":"\u003cp>\u003cstrong>（技能点： I拆书家讲解引导）\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>请读完的小伙伴抬头示意我。好，大家已经阅读完成。接下去我向大家解读一下我对这个片段的理解。\u003c/p>\u003cp>在生活和工作中，根据计划和安排，在这个时间我们应该去做的是“正确”选项，而干扰我们做出正确选择的是“错误”选项。比如我在减肥，晚饭后散步是正确选项，饭后立即葛优躺着看电视是错误选项。再比如明天我要会议发言，今天准备发言稿是正确选项，花两三个小时浏览娱乐新闻是错误选项。如果选择了“错误”选项，“正确”选项就被拖延了。就像饭后葛优躺着看电视，减肥的进程就减缓了；花两三个小时浏览网页推迟了我发言稿的准备。那怎么让我们更倾向于选择“正确”选项呢？拆页告诉我们当“错误”选项来干扰的时候，我们可以运用“五感具象法”做出正确选择，排除干扰。具体操作请看表格。假如下周一我要代表公司进行一次很重要的谈判。我的正确选项是现在我要为谈判做各种准备。但是我的注意力被其它事情吸引了，我的准备工作要被拖延了，我该怎么办呢？闭上眼睛想象正确选择带来的结果也就是我现在积极为谈判做准备带来的结果就是下周一的谈判非常顺利非常成功。带着这份成功我回到了公司，我会看到老板满意的笑容，同事竖起的大拇指。我会听到老板的赞许和自己的笑声。我会感受到兴奋，激动，自信，骄傲。我会闻到祝贺谈判成功的鲜花的香味。我甚至可能吃到一顿丰盛的庆功宴。 这个方法使得我们的“五感”的感知力得到了充分的利用和发挥，想象完成后我会比之前更有力量和更倾向于去选择“正确”选项。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>我的\u003cstrong>正确\u003c/strong>选项\u003c/p>\u003cp>（我应该去做的事）\u003c/p>\u003c/td>\u003ctd>\u003cp>积极为谈判做准备\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>想\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>象\u003c/strong>\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>正确选择带来的\u003cstrong>结果\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>下周一的谈判非常顺利非常成功\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>视觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我将看到老板满意的笑容，同事竖起的大拇指。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>听觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我会听到老板的赞许和自己的笑声。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>感觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我将感受到：兴奋，激动，自信，骄傲…\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>嗅觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我可能会闻到祝贺谈判成功的鲜花的香味。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>味觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我甚至可能会品尝到一顿丰盛的庆功宴。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>(一般做法)\u003c/strong>\u003c/p>\u003cp>但事实上，面对“正确”和“错误”选项时，人们通常更倾向于选择眼前的、轻松舒服的、立竿见影的“错误”选项，而放弃长远的、没有吸引力的、暂时看不到结果“正确”选项。\u003c/p>\u003cp>\u003cstrong>（不这样做的坏处\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>这样选择会造成一个后果：“正确”选项被拖延，而拖延会带来焦虑、自责，会降低自尊感和自信，特别是当拖延变成一种自动导航状态时，如果没有强有力的干预，没有有效的策略和工具，就很难从拖延的泥潭中走出来。最可能的结果就是计划和任务都不能按时完成。\u003c/p>\u003cp>\u003cstrong>（反例）\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>我来给大家讲个我自己的例子。今年9月初开始我打算每周三晚上去跑步的（正确选项），跑了4周后，我为了追一部剧（错误选项）把跑步的事搁置了几次，导致到后来越来越不愿意出去跑步，现在周三跑步这事已经完全停止了。这就是错误选项干扰了我的正确选项。\u003c/p>\u003cp>\u003cstrong>（加工成正面的例子）\u003c/strong>\u003c/p>\u003cp>如果应用“五感具象法”，这件事可以这样处理：首先告诉自己我的正确选项是周三晚出去跑步。然后闭上眼睛想象我每周三去跑步带给我的结果是：三个月后我体重减轻了5斤。 \u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>你的\u003cstrong>正确\u003c/strong>选项\u003c/p>\u003cp>（你应该去做的事）\u003c/p>\u003c/td>\u003ctd>\u003cp>周三晚上出门去跑步\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp;\u003cstrong>想\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>象\u003c/strong>\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>正确选择带来的\u003cstrong>结果\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>三个月后体重减轻了5斤。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>视觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我会看到自己跑步后体重下降，身形变好。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>听觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我会听到身边朋友赞美我：不但瘦了而且气色也好。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>感觉\u003c/p>\u003c/td>\u003ctd>\u003cp>自我感觉非常好，自信。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>嗅觉\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>味觉\u003c/p>\u003c/td>\u003ctd>\u003cp>偶尔还能大吃一顿也不那么怕胖了。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>提醒\u003c/strong>：这5感并非每一次想象中都要包括，可根据实际需要进行取舍。\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>\u003c/p>\u003cp>这个方法适用于生活中你一直想做的一件事比如跑步、写作、练瑜伽等，但因为“错误”选项的干扰而迟迟没有行动和开始。也适用于工作中你已经完成一部分目标，但剩余部分你一直拖着不去做的情况，比如剩下的销售任务，部分客户的回访和维护。\u003c/p>\u003cp>以上就是我对片段的理解。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1】激活经验 （技能点：显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家设计提问】\u003c/strong>\u003c/p>\u003cp>接下去我们来联系一下各自过去的相关经历吧。你是否在运动（跑步、瑜伽）、学习（学英语、阅读、写作、拆书）和工作等事情上碰到过类似的情况？当我说到“拖延“两个字的时候，你脑海中立马跳出来的是哪一件事？请你描述下大概是什么时候？你的“正确”选择应该是什么？你做的“错误”选择又是什么？造成了哪些后果？过后你心里的想法和感受？请在小组内分享。时间是2分钟。 2分钟后邀请一位小伙伴给大家分享。\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者者案例记录\u003c/strong>\u003c/p>\u003cp>学习者小云：上周五之前应该要做的一个报价（正确选项），由于嫌这个报价太麻烦，在周一到周四都拖着没有去做，而是选择去做简单一点的事，比如发货，安排会议（错误选项）。一直拖到截止日期周五才不得不去做报价的事情。做完后其实心里有自责和后悔没有早点去完成。如果早点完成，是不是客户对我的印象会更好，会觉得我办事效率高。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】 （反思加工）\u003c/strong>\u003c/p>\u003cp>非常感谢小云的分享，分享的事例也非常的符合拆页的主题。\u003c/p>\u003cp>假如回到当初那个情景下，我们运用一遍今天的“五感具象法”重新处理，并在表格里写出具体的场景画面，以及使用后内心的感受。时间2分钟。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>学习者小云：\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>你的\u003cstrong>正确\u003c/strong>选项\u003c/p>\u003cp>（你应该去做的事）\u003c/p>\u003c/td>\u003ctd>\u003cp>提早报价\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp;\u003cstrong>想\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>象\u003c/strong>\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>正确选择带来的\u003cstrong>结果\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>由于提早报价这事帮助我谈下了新的客户，接到新的订单\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>视觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我会看到新的订单和提成收入的增加。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>听觉\u003c/p>\u003c/td>\u003ctd>\u003cp>我会听到同事的肯定。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>感觉\u003c/p>\u003c/td>\u003ctd>\u003cp>很有成就感。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>嗅觉\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>味觉\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 内心感受\u003c/p>\u003c/td>\u003ctd>有效果\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;非常感谢小云的分享，“五感具象法”你已经会使用了。\u003c/p>\u003cp>结束：\u003c/p>\u003cp>今晚我的拆书到这里就结束了，希望“五感具象法”能在生活和工作中助你一臂之力，也希望大家能在生活和工作中去运用它。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":13194,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":13195,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1575373120000,"updated_at":1575375244000,"ria":true},{"id":9384,"topic":"“第二自我”策略","learn_goal":"如何利用“第二自我”策略，高效处理问题","remark":"“第二自我”策略是关于决定你的众多性格中哪一条对给定情景最有效，以及让这一性格进行主导。我把这些性格称作你的“第二自我”。让正确的性格做主，你会发现自己的办事效率变得更高，并且所需承受的压力也会更少，甚至你会觉得做这些事很有乐趣。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"芊蓉","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>哈喽大家好，我是洛洛，在熟悉的人面前我是一个活泼开朗的小姐姐，偶尔自己待着的时候我是一个很安静的宅女，面对不好应付的学员，我是很严肃的吕老师。\r\n今天给大家拆的这本书叫《专注力：化繁为简的惊人力量》\r\n下面我给大家分一下组。\r\n &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>【F】这本书的作者是于尔根·\u003ca href=\"https://baike.baidu.com/item/%E6%B2%83%E5%B0%94%E5%A4%AB/13350346\">沃尔夫，英国作家、演讲家和咨询顾问，这本书将教会你如何找到真正是自己想要的目标，并找出干扰你实现目标的元凶。帮助你排除万难，全力以赴于你的目标。\u003c/p>\u003cp>【A】与同类型的专注力的书籍相比，本书会一步一步的帮助你剖析出你真正想要的东西，所揭示的方法会自然而然地成为你的习惯，从而让你轻松地做到专注。\u003c/p>\u003cp>【B1】阅读完这本书，你将学到专注力的有效策略：时间管理策略、右脑适用策略、优势策略、战胜拖延策略、第二自我策略！\u003c/p>\u003cp>【B2】假如你在做一件事情时状态不对并影响到你时，你就可以应用我们今天将要学习的“第二自我策略”进行调整。\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，当你要去做一件的事情，而当前的状态与这件事并不匹配并影响到你时，能够应用“第二自我”策略，让符合这件事的性格特质做主导，从而让事情专注高效的完成。\u003c/p>","ratings_count":1,"texts":[{"id":13180,"quote":"\u003cp>片段来源：《专注力:化繁为简的惊人力量》\u003c/p>\u003cp>“第二自我”类别\u003c/p>\u003cp>这里列举了一些你可能会有用的“第二自我”。\u003c/p>\u003cp>■钱眼小姐（MissMoneypenny）：理性、能干、保守。是准备税务、决定购置物品的好人选。\u003c/p>\u003cp>■匈奴王（Attila）：坚强，始终清楚目标所在，不屈服。如果曾经有人盛气凌人地欺负你，让你不能做自己喜欢的或者需要的事情，或者当你处理手头工作时受到很多外界的干扰，这会是很好的人选。\u003c/p>\u003cp>■阿尔伯特（Albert）：能够打破陈规、别出新意地想问题，不惧怕失败或他人的嘲弄。当你需要创造力时，这是很好的人选，是头脑风暴的很好选择。\u003c/p>\u003cp>■大孩子（Big Kid）：幽默、爱冒险、思想开放。当你发现自己对事太严肃认真时，这是个好选择。\u003c/p>\u003cp>■超人（Mightyman/Mightywoman）：坚强、自信、能干。当需要信心，比如在做演讲、拨打并不太肯定的电话时，你需要这样的人选。\u003c/p>\u003cp>■哈耳摩尼亚修女（Sister Harmonia）：温柔、善于安抚、致力于为有关人士寻求双赢局面。在和通情达理的人进行协商时的有利人选。\u003c/p>\u003cp>更多“第二自我”\u003c/p>\u003cp>如果你无法建立自己的“第二自我”，花一个上午看点动画片，然后选一个最能代表你所希望的情绪的角色。如果你需要快乐，海绵宝宝（SpongeBob Squarepants）迟早会有用。\u003c/p>\u003cp>以上是我觉得会有用的一些“第二自我”，你可能觉得想些属于自己的“第二自我”会更有用。可能在一些情况中，你还需要变换自己的性格。举个例子，如果“哈尔摩尼亚修女”在谈判中无法取得任何成效，在必要的时候，我们就需要“匈奴王”来接管这件事！但我希望你能明白如果我们不加任何考虑地就让错误的人选来负责某件事情，结局会变得非常糟糕。你肯定不希望“大孩子”来查收税单的事，或者让“匈奴王”参与你和潜在客户的初次会谈。\u003c/p>\u003cp>从现在开始，你可以从自己的多重性格中选择合适的来对某件事情进行主管。这一过程的简略步骤如下：\u003c/p>\u003cp>1.分析手头的任务。处理这项任务需要什么品质？\u003c/p>\u003cp>2.用你的记忆或想象力创造或再造一个拥有那些品质的人，然后进入这种理想状态。给“第二自我”取个名字。\u003c/p>\u003cp>3.让“第二自我”主宰你，直到任务完成，或者直到你到达某个需要另一个“第二自我”的时刻。\u003c/p>\u003cp>4.完成这项任务，然后自觉地从这种“第二自我”中退出，进入到更典型的自我中，或者进入另一种更适合于你将要做的事的“第二自我”中。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>我们在不同情况下，会呈现出不同的性格特点。而在处理相对重要的事情的时候，因为种种原因，会让不合适的性格做了主导：\u003c/p>\u003cp>比如即将要上台发言了，你做好了充足的准备，可上台就开始脸红，紧张得说不出话来；\u003c/p>\u003cp>你还有1天就要提交方案了，可是你却焦虑得没有办法专注的写方案；\u003c/p>\u003cp>你很熟悉这个项目，当领导派你去谈判的时候，你却胆怯了......\u003c/p>\u003cp>这个时候，你可以采用“第二自我策略”，那么什么是“第二自我”呢？就是在你的众多性格里，选择出对给定场景最有效的那个性格，然后让这个性格进行主导。我们把做主导的性格称作你的“第二自我”。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那么如何采用“第二自我策略”呢？\u003c/p>\u003cp>第一步：\u003cstrong>分析\u003c/strong>手头的任务。处理这项任务需要什么品质？\u003c/p>\u003cp>在这一步，需要我们\u003cstrong>放下情绪\u003c/strong>，可以闭上眼睛，也可以选择不说话，静静的问一下自己，处理这项任务需要什么品质？可以将符合任务的\u003cstrong>标签\u003c/strong>写下来或者在脑海中呈现出来。\u003c/p>\u003cp>第二步：用你的记忆或想象力\u003cstrong>创造或再造\u003c/strong>一个拥有那些品质的人，然后进入这种理想状态。给“第二自我”取个名字。\u003c/p>\u003cp>在这一步，需要去\u003cstrong>回忆\u003c/strong>，在你知道的人或者你自己，有没有符合这些品质的，假如没有，可以自己\u003cstrong>创造\u003c/strong>一个，并给他\u003cstrong>取个名字\u003c/strong>，取名字会让你更重视。\u003c/p>\u003cp>第三步：让“第二自我”主宰你，直到任务完成，或者直到你到达某个需要另一个“第二自我”的时刻。\u003c/p>\u003cp>在这一步，你已经\u003cstrong>复制\u003c/strong>了你所选的这个人的品质，并且这些品质是你自己也做得到，你需要\u003cstrong>暗示\u003c/strong>自己现在拥有这些品质了，并将这些品质\u003cstrong>用\u003c/strong>\u003cstrong>具体的细节\u003c/strong>呈现出来，比如脸部表情、发型、穿着、言语等。\u003c/p>\u003cp>第四步：完成这项任务，然后自觉地从这种“第二自我”中退出，进入到更典型的自我中，或者进入另一种更适合于你将要做的事的“第二自我”中。\u003c/p>\u003cp>【why】——不这么做的坏处是什么\u003c/p>\u003cp>1.&nbsp;&nbsp;指出错误的一般做法：\u003c/p>\u003cp>去做一个有说服力的演讲时，你让温柔的你主宰了自己，需要与人协商时，你让脾气暴躁的你主宰了自己。\u003c/p>\u003cp>2.梳理这些常见做法的坏处：\u003c/p>\u003cp>让不正确的性格做主导，会导致我们效率低下，甚至没有勇气去做一件事。&nbsp;\u003c/p>\u003cp>3.举出一两个简明反例：\u003c/p>\u003cp>昨天身体很不舒服，5点左右好一点了，我坐到电脑面前，打开拆页，上下翻了一下，脑子里是一片的空白的，我尝试着修改，几分钟后我就改不下去了，因为没有思绪，做不到专注。\u003c/p>\u003cp>4.回到原文建议：\u003c/p>\u003cp>首先分析这项任务，第二步创造或再造“第二自我”，第三步让“第二自我”来主宰你，第四步是退出来。\u003c/p>\u003cp>5.将刚才的反例改编成正面案例：\u003c/p>\u003cp>【第一步】首先修改拆页需要：专心、有逻辑、高效率；\u003c/p>\u003cp>【第二步】创造或再造“第二自我”：我想到的拥有这些品质的是欢乐颂里面的安迪，她拥有很强的时间观念，逻辑思维缜密，做事专注高效。现在我进入安迪的状态中，我的“第二自我”就叫安迪。\u003c/p>\u003cp>【第三步】让“第二自我”安迪来主宰你：在修改拆页前准备好我需要的资料、水、台灯、并打开轻音乐，我暗示自己说我现在就是安迪，我端坐在电脑面前，就连面部表情我也想象成是安迪，查看着手头上的资料，并认真的修改。\u003c/p>\u003cp>【第四步】结束后，从“第二自我”中退出。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>当你要去做一件事情，或者和人沟通，又或者你不得不去做一件事情的时候，而完成这个任务和你当前的状态并不匹配，从而影响到你，你就可以采用“第二自我”策略了。而在简单的工作与平常简单的沟通当中，就不用采用这样的方法。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>请回忆一下，最近一次因为要做一件事情，比如面试、演讲，但是当前的状态与这件事并不匹配，从而影响到了你，是什么时候，具体发生了什么？请想一想，在小组内分享一下，限时5分钟。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>媛媛上周六晚上参见演讲沙龙的活动的主持人，状态是紧张，从而影响了她当时的发挥。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>学习完今天的“第二自我”策略，假如再次回到过去的这件事上面，你将如何行动呢？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>媛媛的应用\u003c/p>\u003cp>1.分析做主持人需要自信、有风趣、落落大方\u003c/p>\u003cp>2.符合以上特质的人媛媛想到的是中央电视台的董卿\u003c/p>\u003cp>3.让“第二自我”董卿作主宰，穿一双自信的鞋子、衣服，化一个自信的妆容，面带笑容，并暗示自己就是董卿，让第二自我主宰自己，一直到任务完成\u003c/p>\u003cp>4.从“第二自我”董卿当中退出来\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1575300090000,"updated_at":1575300953000,"ria":true},{"id":9106,"topic":"设定目标的过程应该怎样进展","learn_goal":"怎样从目前的状况到实现目标","remark":"是否有这样的经历：无数次给自己定了目标，就是无法实现？知道自己想要什么，却总是“明天再说”、“想不清楚”？","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"金艳","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是金艳，是今天的拆书家。我的三个标签1.我是一个宝妈，有两个帅气的男孩。2.我是一个经营者，经营着一家建材公司。3.我是一个学习者，希望能做到知行合一。      \r\n 接下来我给大家介绍一下拆书帮。 拆书的“拆”不是拆散的拆，而是转化和内化。“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。  \r\n         拆书分为个人学习的拆书法和组织学习的拆书法：个人学习的应用就是RIA便签法,R是指原书片段，I是用自己的话重述原文，A是关联自己的经验；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\r\n         “拆书帮”是一个全国性的成人学习社群， 目前在北京、上海、广州、深圳等全国30多个城市都建有拆书帮的学习者俱乐部（也叫拆书帮分舵）。拆书帮分舵是一种非盈利性的学习组织，它的使命是帮助更多的学习爱好者成长为拆书家。","ratings_count":1,"texts":[{"id":12860,"quote":"\u003cp>&nbsp; 前文中，我谈到这个过程通常是怎样发展的。下面我们来谈谈如果你确实想要实现目标，设定目标的过程应该怎样进展。\u003cbr>\u003c/p>\u003col>\u003cli>\u003cp>设定一个目标。在例子中，我们还是以实现目标体重为例。\u003c/p>\u003c/li>\u003cli>\u003cp>开始做一切你认为可以帮助你实现目标的事情。比如为了燃烧卡路里，你决定坚持每周徒步三次，每次一公里，目标是每周减轻一公斤的体重。\u003c/p>\u003c/li>\u003cli>\u003cp>对运动过程效果进行监控。如果你所做的事情确实给你带来所希望的成效（比如，你发现自己每周都比设定的目标轻了一公斤），那么你就坚持做下去，直到目标实现。\u003c/p>\u003c/li>\u003cli>\u003cp>如果你所做的事情并没有给你带来想要的结果，那么赶快进行头脑风暴，找些能够替换的措施，开始做些改变。这可能只是一个很小的调整，也有可能是整个策略的彻底改变。比如，你可能发现你的体重只下降了一点点，因此你决定除每周的徒步外，你还要对饮食进行控制，将小吃和甜点改为只吃一些水果。或者你可能决定试试聘请私人教练每周陪你锻炼两次。\u003c/p>\u003c/li>\u003cli>\u003cp>重复步骤3和步骤4，直到实现你的目标。你的截止日期开始变为“直到实现我所设立的目标”。你所做的承诺只不过是尝试做些不一样的事，直到找到有效的方法。有的目标可能很快实现，有的目标可能需要很长时间才能实现。用这种方法，你永远不会失败，这只是一个不断学习的过程。\u003cbr>\u003c/p>\u003c/li>\u003c/ol>","explains":"\u003cp>在生活中我们总会设定很多很多目标，但是有很多目标无法完成，让我们产生挫败感。如何才能实现目标呢？\u003cbr>\u003c/p>\u003cp>&nbsp;关注目标的过程进展，及时调整才能帮助我们实现目标。设定的目标过程应该按5个步骤进行。\u003c/p>\u003col>\u003cli>\u003cp>明确目标。明确符合smart原则的目标。\u003c/p>\u003c/li>\u003cli>\u003cp>行动。做能实现目标的所有事。\u003c/p>\u003c/li>\u003cli>\u003cp>对行动结果进行监控，如果你的行动确实有效，那么坚持做下去，直到成功。\u003c/p>\u003c/li>\u003cli>\u003cp>新行动，行动无效，那么需要进行反思，找到能够替换的新行动。\u003c/p>\u003c/li>\u003cli>\u003cp>重复步骤3和步骤4，直到实现目标。\u003cbr>\u003c/p>\u003c/li>\u003c/ol>","interaction":"\u003cp>上个月，因为我最近的体质不太好，所以我决定每天运动来提高我的体质。我定了一个运动目标，每天做30分钟的瑜伽，坚持了四五天之后，效果不明显就不了了之了。\u003c/p>\u003cp>现在回想，在行动中我只用了一种方法，方法不管用，就直接放弃了，没有尝试用新的方法，没有用步骤4和步骤5，导致失败。\u003c/p>\u003cp>如果重新来过，我会在发现效果不明显时，换一种运动方式，比如慢跑。对慢跑结果进行监控，如果慢跑管用，就一直坚持下去。如果扔然不管用，就再换一种运动方式，直到找到合适的运动。\u003c/p>\u003cp>从明天开始，也就是10月17日到11月17日，用一个月时间，按照目标过程进展的5个步骤，培养写反思日记在习惯。\u003c/p>\u003col>\u003cli>\u003cp>明确目标，我想改变自己，每天用15分钟写一下，对昨天的反思，做的好的地方或做的不好的地方，可以很详细也可以是简单的一句话。\u003c/p>\u003c/li>\u003cli>\u003cp>行动，明天早上5点半开始写，专门准备一个本子放在床头。5点半到6点是反思日记的专属时间。\u003c/p>\u003c/li>\u003cli>\u003cp>对行动进行监控，请爱人帮忙监督。如果能每天坚持写，肯定可以达到目标。\u003c/p>\u003c/li>\u003cli>\u003cp>如果不能坚持，反思原因找到新的方法。比如说早晨起不来，做一个对早起有诱惑的美食。\u003c/p>\u003c/li>\u003cli>\u003cp>重复步骤3和步骤4，直到实现目标。\u003c/p>\u003c/li>\u003c/ol>\u003cp>我如果做到了就奖励自己一个心仪很久的平板电脑，做不到就惩罚做一个月的卫生。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1571663452000,"updated_at":1571663452000,"ria":true},{"id":7973,"topic":"学习如何认可他人","learn_goal":"学习者能够在需要建立关系时，运用四步法对对方进行认可","remark":"如果你感到无法将精力集中到最重要的事情上、周围充斥着各种干扰因素让你无法聚焦到目标上，本书提供了专注的策略和工具来告诉我们如何专注目标，教我们运用现有的力量，以帮助自己取得更大范围的成功。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"沁水茶园","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong> &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;不破不能立，不拆不成器！大家好，我叫沁水茶园。下面我用三个标签介绍一下我自己：1.本职是制造业销售管理，2.希望能成为一名学习促进者的新手拆书家；3.一位小学生的不吼妈妈。下面我们做一点准备活动，继续沿用之前的分组，以方便后面交流讨论环节的开展。&nbsp;\u003c/p>\u003cp>\u003cstrong>FAB图书介绍&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我所拆的片段源自于《专注力:化繁为简的惊人力量》，为什么我选取了这样一本书呢？&nbsp;\u003c/p>\u003cp>F特征（Feature）：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;本书的作者是英国的于尔根·沃尔夫，是一名专门研究高效方法与技巧的咨询顾问。这本书分别从专注的策略和工具两个维度来具体讲了如何聚焦和提高效率。&nbsp;\u003c/p>\u003cp>A优势（Advantage）：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;这本书是豆瓣上专注力方面的书籍中阅读人数最多的，与其他结构化思维的专注类书籍相比，本书专门针对右脑发散性思维的人该如何专注目标，结构和内容都特别通俗易懂。&nbsp;\u003c/p>\u003cp>B利益（Benefit）：&nbsp;\u003c/p>\u003cp>B1:如果你感到无法将精力集中到最重要的事情上、周围充斥着各种干扰因素让你无法聚焦到目标上，本书提供了专注的策略和工具来告诉我们如何专注目标，教我们运用现有的力量，以帮助自己取得更大范围的成功。&nbsp;\u003c/p>\u003cp>B2:在工作或生活中有没有遇到这样的情况：想与别人进行链接，建立或提升关系却不知道如何入手？说几句赞美别人的话，别人却无动于衷。极有可能是因为没有用对方法。今天我们从书中选取的这个片段提供了一个专注于他人的方法，在跟随我学习完本次的RIA现场学习后，大家能够在需要与他人建立或提升关系时，运用四步法有效认可对方。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11535,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>下面我们进入R环节，进行原文阅读。\u003c/strong>请大家花1.5分钟时间进行阅读，阅读完后，请举手示意我下，以便我了解大家进度。\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>片段：如何认可他人（《专注力》\u003c/strong>\u003cstrong>P94\u003c/strong>\u003cstrong>—95\u003c/strong>\u003c/p>\u003cp>极具讽刺意味的是，尽管人们最想得到的东西并不需要我们付出什么，但大多数人对此却非常吝啬。可能我们担心表扬或欣赏感觉会不真诚，或者这样做会让我们感觉自己显得渺小。这并不对，当然，如果你能战胜自己天生的沉默，你会惊奇地发现这会给你的社会关系带来怎样的改善。以下是给予人们所希望认可的一些方法。\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>．学会倾听。\u003c/strong>大多数情况下，当有人和我们说话时，我们会在听到一半的时候就走神，开始想要怎样对我们听到的内容进行评论，而不是注意听别人把事情说完。不要这样做，注意用心倾听他人所说的事直到结束。你依然可以很快给出答案或者评论。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>．增加目光接触。\u003c/strong>大多数人在倾听他人说话时都会保持很好的目光接触，但当他们自己说话的时候，情况就不一样了。当然，你想要自然的而不是令人不悦的凝视，即便如此，如果你能增加和对方目光接触的时间，哪怕只增加25％，谈话效果会有很大不同。如果直视他人的双眼会让你觉得紧张，你可以把目光放在双眼中间，或者轻轻地让你的目光在他们左右眼间移动。不过，不要过多地把注意力集中在这件事情上，以免无法注意别人所说的话。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>．以姓名称呼对方。\u003c/strong>我并不是建议你像肥皂剧里所表演的那样每句话都要以他人的姓名来开头，只是很随意地在谈话中偶尔提到。\u003c/p>\u003cp>最自然的做法就是在和人刚见面打招呼时以及道别时提到他们的姓名，虽然这种做法很没创意，不过人们最爱听到的声音确实就是自己的名字。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>．给出真诚的赞美。\u003c/strong>这可以是他人姣好的外貌、一件衣服、一件别人刚做的事情或者其他任何事。如果你真心觉得这值得赞美，这些话听起来就不会让人觉得虚伪，即便在你习惯这么做之前还是会感觉有些不真实。你不必做得太过火。这可以是简单的赞扬、比如“那双鞋真好看”，或者“你在会上提出的观点很正确，这对事情的进展非常有帮助”。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>好！，我注意到大家都已经看完，下面我们进入【I】环节:\u003cbr>\u003c/p>\u003cp>为什么一本讲专注力的书会提到认可他人呢？我们在专注于自己的目标时，注意力仅仅放在自己身上是不够的，他人的影响也不可忽视。认可他人是将注意力专注于他人的一种方式，以期在需要他人支持时获得他人的帮助，以更好的专注于自己的目标。 &nbsp;\u003c/p>\u003cp>\u003cstrong>（why）\u003c/strong>\u003c/p>\u003cp>心理学家研究发现：大多数人都在某些方面有被认可的需求，而这种需求却经常得不到满足。在我们需要与对方建立或提升关系时，积极认可对方可以帮到我们建立更稳固的合作关系。 &nbsp;\u003c/p>\u003cp>\u003cstrong>（what）\u003c/strong>\u003c/p>\u003cp>认可他人的四步法是从行为和语言两个维度，分别用两种不同的方式，针对具体的事情进行认可的方法。\u003c/p>\u003cp>\u003cstrong>（how）\u003c/strong>\u003c/p>\u003cp>那么认可他人的四步法 具体怎么做呢？\u003c/p>\u003cp>1.\u003cstrong>行为上认可-学会倾听 。\u003c/strong>交谈中别人在说的时候，首先要做到不打断、不评论，然后要有点头、“嗯嗯”的回应的表示。通过这样的方式我们就把注意力放在对方身上。\u003c/p>\u003cp>2.\u003cstrong>行为上认可-注视对方。\u003c/strong>说认可他人的话时，眼睛看着对方。不必全程凝视对方，但要与对方有较多的眼神交流。\u003c/p>\u003cp>3.\u003cstrong>语言上认可-追加称呼。\u003c/strong>对话的开始和说认可的那几句关键句时，追加符合与对方现有关系的称呼，比如马博士、小刘、大师兄等 ，可以让认可更具有指向性。\u003c/p>\u003cp>4.\u003cstrong>语言上认可-具体赞美 。\u003c/strong>赞美可以是简单的赞扬，也可以是深刻的见解。但不是简单的迎合，而是要就对方关心的事物，针对具体细节（如行为、外表、衣着等）进行赞美；赞美的程度要与对方的期望相当，或者稍稍的超预期。\u003c/p>\u003cp>以上就是认可他人的四步法。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>如果不使用四步法会怎么样呢？通常在需要认可他人的时候，我们可能没有做出认可，或者只是做出泛泛的认可。 &nbsp;没有做出认可，对方感到失落甚至愤恨；泛泛口头认可，对方不屑一顾；给对方一个赞许的眼神，对方不明就里、莞尔一笑回敬 。这些行为让我们错过与对方建立或提升关系的机会。缺乏良好的人际关系会导致我们在希望得到对方支持的时候举步维艰 。\u003c/p>\u003cp>\u003cstrong>（反例：强调我们不使用认可他人四步法时，会有什么坏处）\u003c/strong>\u003c/p>\u003cp>为了更好的向大家说明如何认可他人，在这里给大家举一个我自己的例子：\u003c/p>\u003cp>我女儿是个很内向的小朋友，学校里马上要召开运动会，我女儿被选作了垒球项目的选手。我其实蛮为她开心的，回家后就跟她说：“宝贝儿，你选上运动员啦，你怎么那么厉害！”\u003c/p>\u003cp>我说完以后，女儿无动于衷，没有任何被认可的回应。我做了认可的举动，但并没有让我们的亲子关系得到提升。那么我对她提出一些要求时，她也不会比从前有更积极的回应。&nbsp;\u003c/p>\u003cp>\u003cstrong>（加工成正例：如果当时我们使用了认可他人四步法时，会有什么好处）\u003c/strong>\u003c/p>\u003cp>那么，如果在回到当初的场景，运用认可他人四步法来认可孩子，激励孩子，又是怎样的一个状态呢？\u003c/p>\u003cp>1、学会倾听。我会首先问她：“宝贝儿，你是怎么被选上垒球项目的呀？朱老师有没有教过你们怎么投球？”她可能会说：“朱老师教我们这样，”比划给我看，“我都差点把球扔到食堂去了，然后我就被选上了。”在这个说的过程中，我要有“嗯嗯”的回应，或者是点头等行为表现出我一直在听她说话。\u003c/p>\u003cp>2、注视对方。在对她说认可的话的时候，我要把目光集中在她身上。\u003c/p>\u003cp>3、追加称呼。“宝宝”是我对她的亲昵的称呼，在对话的开始和夸她的时候，我要带上这个称呼。\u003c/p>\u003cp>4、具体赞美。接下来我要对她进行具体赞美，看着她对她说：“宝贝儿，爸爸妈妈以前在读书的时候从来没有在个人项目上当过运动员，在这一点上你真厉害！能选上说明你确实用对了方法 ，好好练习，祝你运动会取得好成绩”。大约她也会回应一句，“好的，妈妈！加油！”\u003c/p>\u003cp>通过这样具体的认可，能让孩子真正感受到我对这件事的重视，也让她能感受到我真心的认可她。这样以后她再或者一些成绩的时候，也会更愿意来跟我说。通过这样的正向循环以提升亲子关系。\u003c/p>\u003cp>\u003cstrong>（where）\u003c/strong>\u003c/p>\u003cp>在工作和生活中，当我们试图与对方建立关系、提升关系时都可以运用四步法向对方表达我们的认可。如果没有这个需求，则可以不使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1: 拆书家提问设计（拆书家进行显像提问）\u003c/strong>\u003c/p>\u003cp>接下来我们进入A1环节-激活我们过去的经验：\u003c/p>\u003cp>请你回想一下，在过去的一段时间里，有没有出现这样的情况：\u003c/p>\u003cp>孩子拿来一张自己得意的画作，想要夸夸孩子；\u003c/p>\u003cp>朋友向自己炫耀了一番自己获得的小成就；\u003c/p>\u003cp>同事拿来一个方案，侃侃而谈自己花费了多少心血；\u003c/p>\u003cp>这里给出的3种认可他人时的场景，或者你有其他类似的需要和对方建立或提升关系的经历，是什么事情，什么时候？请大家先简单的把自己经历过的类似场景在便签上写下来，并在小组内分享，时间为1分钟。\u003c/p>\u003cp>提示：（在你的分享中，要有明确的时间，地点，人物，事件的起因，经过和结果。）\u003c/p>\u003cp>（接下来进入志愿者分享阶段、选1-2名志愿者，注意控制好时间）\u003c/p>\u003cp>\u003cstrong>学习者梁丹丹的案例记录\u003c/strong>\u003c/p>\u003cp>上周在公司我做了课件收集，新媒体的同事笑双很辛苦的做了一个课程设计方案，部门的其他同事没有给予更多的关注与赞美，我也只是附和了一句“好用心”而已。\u003c/p>\u003cp>\u003cstrong>A1+拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>好的，下面我们进入【A1+】环节，学习了这个认可他人的片段，了解我们要认可他人，可以通过两个方面、四个维度的认可他人四步法进行：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; 学会倾听；\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; 注视对方；\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; 追加称呼；\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp; 具体赞美；\u003c/p>\u003cp>请大家思考一下，针对以上大家认可的经历，如果运用认可他人四步法该如何做，请大家写下来，在小组内分享，3分钟的时间。\u003c/p>\u003cp>\u003cstrong>A1+学习者梁丹丹的案例记录\u003c/strong>\u003c/p>\u003cp>如果再回到当初的那个场景，我需要运用四步法对笑双做出有效认可，以增进我们之间的关系。\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; 学会倾听：我要聆听笑双的课程构思，在听她说的时候不打断，不评论，同时要有点头或者哦哦的回应；\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; 注视对方：在认可她的辛苦时要眼睛看着她；\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; 追加称呼：在开启对话和认可时，要带上笑双这个称呼；\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp; 具体赞美：笑双，你好用心！目标明确，涉猎广泛，用心钻研。相信通过你的课程，会在网络运营中吸引到更多的粉丝。\u003c/p>\u003cp>\u003cstrong>总结概述\u003c/strong>\u003c/p>\u003cp>以上就是我今天针对《认可他人》的方法进行的拆解，希望认可他人的四步法能为您的生活带来一点小小的改变！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1558740775000,"updated_at":1558740951000,"ria":true},{"id":7498,"topic":"创造流程，提升目标的专注力","learn_goal":"提升专注力","remark":"大家都明白二八法则，明白要专注于20%高附加值的事情，少做或不做那80%低附加值的事情，但事实上缺很难做到。这是因为高附加值的事情往往都有一些达成的难度，而低附加值的事情我们做起来可能毫不费力。但是从个人成长的角度来说，唯有专注于高附加值的事情才能实现个人成长。\r\n\r\n亲爱的小伙伴，是不是有这样的情况：\r\n在朋友圈立下flag，“不瘦十斤头像不换”，但体重一直就没能降下来；\r\n在年初写下年度目标，信誓旦旦，结果到年底却不忍直视；\r\n办了一张健身卡，希望能练出完美身材，没去几次就放弃了。\r\n来一起学习创造流程，让我们的目标落地实施吧。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"沁水茶园","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>自我介绍及分组(1min)\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;大家好，我叫沁水茶园，是一名新手拆书家。下面我用三个标签介绍一下我自己：1.制造业销售管理，2.拆书家，希望能成为一名学习促进者；3.一位小学生的妈妈。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;下面我们做一点准备活动，两人为一组分成小组，木木和贞纯一组、婷英和娟娟一组，泽世和青苗一组，以方便后面交流讨论环节的开展。\u003c/p>\u003cp>\u003cstrong>图书介绍（1min）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>我所拆的片段源自于《专注力:化繁为简的惊人力量》，首先我给大家介绍一下这本书：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;B利益（Benefit）：那么我为什么选择了这样一本书呢？这是一个注意力稀缺的时代，我们每个人每天都会接收大量的信息，这中间有很多信息会对我们造成干扰和打断，本书用了一些很简单的方法和工具教我们如何专注与聚焦。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;F特征（Feature）：本书的作者是英国的于尔根·沃尔夫，是一名咨询顾问，擅长写高效能的方法与技巧类文章。这本书是一本自我管理类的书籍，以二八法则为主，具体讲了如何聚焦和提高效率。&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;A优势（Advantage）：本书在豆瓣上是同类书籍中阅读人数最多的一本，分别从专注的策略和工具两个维度讲述了如何提升专注力，是同类书籍中最简单的自我管理书籍。\u003c/p>\u003cp>在跟随我学习完本次的现场学习后，大家能够不再只是停留在制定目标上，而是通过任务分解、有效执行以达成目标。\u003c/p>","ratings_count":1,"texts":[{"id":10970,"quote":"\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>好的，下面我们用2分钟的时间阅读一下原文片段，如果大家阅读完毕，请示意我一下。\u003c/p>\u003cp>\u003cstrong>R片段：创造流程（《专注力》P54—55）\u003c/strong>\u003c/p>\u003cp>你可能对“流程”的概念比较熟悉，米哈里·奇肯森德米哈依（ Mihaly Csikszentmihalyi）教授对这一概念进行了深入的阐释。当“流程”状态出现时，你无比投入于你所从事的事情，而失去了时间的概念。这是一种令人愉悦的经历，在这个经历中，你仿佛成为你所做事情的媒介——一种紧张而又容易的专注状态。问题是，你要怎样创造这样一个状态，而不是一味地等待并希望这个状态自然发生？这里有三个关键因素：\u003c/p>\u003cp>1．选一个刚好在你能力范围之内或者刚刚高出你能力范围的任务，要是这个任务太难或者太简单，你都不会进入“流程”状态。因此，如果你想写些东西，把这个任务分解成你能够处理的部分。这可能是撰写大概的框架，可能是列一个关键点的清单，或者在脑子里先绘制一张目标地图。像这样写下一个和你的目标相关的任务。\u003c/p>\u003cp>2．确保任务包含即刻的反馈，这样你便能在任务执行过程中随时了解任务的完成情况，是完成得好还是不好。比如，你可以开始设定一个要写一定字数文章的目标，或者在你第一个工作时间内获取某一特定信息。一般来说，你需要在任务前期拥有乐观积极的感觉，渐渐地这项任务可能会让你非常投入，使得你不再去想怎样做这个项目或者项目做得怎么样。写下能够给你带来这种反馈的方法。\u003c/p>\u003cp>3．创造一个注意力分散点尽量少的环境。同样，稍后在这过程中，你可能会非常投人以至于你甚至注意到电话铃响之类的事，但是如果你能在一个容易集中精力的地方开始工作，这显然更有益处。这也包括预留一段时间。在这段时间里，你不会觉得自己必须要去做些其他的事情。写下在何时以及何地你会集中精力做之前所选择的任务。\u003c/p>","explains":"\u003cp>【过渡】好，我注意到大家都已经看完，我们进入【I】环节:\u003c/p>\u003cp>本书基于二八法则主要是指专注于20%高附加值的事情，少做或不做那80%低附加值的事情。因为从个人成长的角度来说，唯有专注于高附加值的事情才能实现个人成长。\u003c/p>\u003cp>要完成有难度的高附加值的事情，我们现阶段与目标有一定的距离，要达成目标，这需要我们把目标分解到可执行的任务单元，运用强化任务执行的工具方法，从而最终实现目标。\u003c/p>\u003cp>那具体该怎么做呢？在这个片段里为我们提供了创造流程的三步法：\u003c/p>\u003cp>1.选择合适的任务。合适的颗粒度因人而异的，要保证任务具有可行性的关键点是：在自己现行的能力水平上下。太简单或太难都会比较容易导致放弃执行任务。（不这么做的坏处）\u003c/p>\u003cp>2.建立及时的反馈。任务是否得到了有效的执行，需要通过及时的反馈进行验证。很多计划没能得到有效的执行其中一个主要的原因就在于缺少这种监测机制。（不这么做的坏处）\u003c/p>\u003cp>3.营造专注的氛围。我们自己一个人要自发的进入专注的状态往往是很难的。（不这么做的坏处）因此我们在做重要的事情时，需要辟出一个相对专注的环境以减少外界的影响。以便于最大程度的专注于任务本身。\u003c/p>\u003cp>以上就是创造流程的三步法。对我们个人成长而言重要的里程碑事件都可以用创造流程的方法，但主要适用于有可行性的目标，如目标本身的可实现有问题，则三步法也不适用。\u003c/p>\u003cp>下面我给大家讲解一个我自己的例子。我的书柜里有很多书，但总是买书的速度跟不上读书的速度。最近参加了朋友张同学的读书圈，居然一个月内也读了两本硬书。那么是怎么完成的呢？\u003c/p>\u003cp>1.首先，设置合适的任务。在这个读书圈里每天学习的学习任务是学习一个思维模型。这个任务对于我来说并没有太大的压力，但每天都要有自己独立的思考去完成作业，因此任务在我的能力水平上下，这个任务设置是合适的。\u003c/p>\u003cp>2.其次，建立及时的反馈。当天的打卡作业必须要在当天24:00前完成。如果有一天的作业没有在当天完成则视为打卡失败。打卡失败的参与者保证金会在结业的时候会以红包的形式被全员瓜分。用一个小小的惩罚来促进大家每天都要打卡。\u003c/p>\u003cp>3.最后，营造专注的氛围。我自己一般会固定在晚上睡觉前半小时完成打卡作业。在这样的专注而少干扰的环境下，我顺利的坚持下来。\u003c/p>\u003cp>通过这样的创造流程三步法，由于任务合适、需要每天及时反馈、有一群书友一起共读有良好的氛围，最终我完成了以前无法完成的任务。这个流程是张同学帮我建立的，大家运用创造流程的时候，可以是自己的创造流程，也可以是参与别人的创造流程。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>接下来我们进入A1环节-激活我们的过去经验：下面按照我们刚才的分组进行小组讨论：请大家回忆一下，在过去的半年里，有没有制定目标，目标的实施大家是怎么做的？时间为3分钟。（在小组分享时倾听各小组分享）\u003c/p>\u003cp>\u003cstrong>学习者娟娟的案例：\u003c/strong>\u003cbr>\u003c/p>\u003cp>参与了100天读30本书的训练营，还有读实体书的读书计划，两个读书计划在一起，白天还要上班，而且训练营的要求很严苛，如果有一天没有完成就会被踢出群。\u003c/p>\u003cp>设置合适的任务：虽然个人成长的愿望很美好，但是由于目标设置超过了个人能力（时间与精力）导致在坚持了一段时间后被踢出群了。\u003c/p>\u003cp>建立及时的反馈：每天都有打卡，反馈确认OK，因此坚持了七期。\u003c/p>\u003cp>营造专注的氛围：晚上读实体书，白天读电子书。固定的时间进行专注的练习。\u003c/p>\u003cp>\u003cstrong>A2拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>刚才我们激活了过去经验，接下来是我们的A2环节—规划未来的应用。\u003c/p>\u003cp>通过今天的学习，下面请大家为自己做一个目标设定：接下来的两周内，有什么目标，打算如何运用创造流程的三步法实施目标，请大家在便签上写下来。\u003c/p>\u003cp>提示：目标设定中请大家明确目标的背景、按照三步法具体的行动步骤分别是什么。大家在写的时候，建议遵循SMART原则，要有可测量的明确目标、具体的做法，目标确定可以实现，这样才能真正学以致用。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>\u003c/p>\u003cp>学习者木木的目标设置：木木是HK二级整理师，做整理师咨询工作，运用三步法的设置如下：\u003c/p>\u003cp>1.设置合适的任务：一周内完成整理师的公益课程；\u003c/p>\u003cp>2.建立及时的反馈：周二前完成PPT，周四前完成一篇讲解稿；\u003c/p>\u003cp>3.营造专注的氛围：每天早起，7:00到办公室利用上班前的时间完成。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>非常感谢木木的分享，由于时间的关系，我们今天的拆书环节暂时告一段落，希望大家把今天学到的《创造流程》的方法应用到实际生活中，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554474937000,"updated_at":1554475267000,"ria":true},{"id":7009,"topic":"谁说你必须从头开始","learn_goal":"让学习者专注于自己喜欢的部分，保持动力去有效快速行动","remark":"我们是否有过这样的经历，当我们准备大干一场时，却发现万事开头难，而吸引我们的却是内部的其它环节，正当我们要下手的时候，就会有个声音跳出来说：“不可以！必须从头开始，哪有大框架都没想好，就去想细节的，不合规矩”，于是两难的我们被卡在原地，迟迟不能行动，而那样的我们看起来好像很糟糕。噢！那怎么办？让我们来看一看，这种情况可能会发生在哪些时候，哪些场合？","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Fairyid4","city":"宁波"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>[自我介绍]\r\n大家好！我叫金娜\u003c/p>\u003cp>三个标签：\r\n标签一：学习践行者 &nbsp; 标签二：自我开发者 &nbsp; 标签三：沙盘游戏师\r\n &nbsp;\u003c/p>\u003cp>很喜欢拆书帮的理念：不拆不成器，不破不能立。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>拆书\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>拆书是一种以提升能力、解决问题为目标的成人学习方式。\u003c/p>\u003cp>强调把知识从书本上迁移到我们的日常生活中，规划具体运用，学以致用，最后融入并提升我们知识及经验体系。\u003c/p>\u003cp>分为个人学习和组织学习两种。\u003c/p>\u003cp>个人学习应用是 便签法，让人读一本书就能达到参加同主题培训的效果。\u003c/p>\u003cp>组织学习的应用是 一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为已用。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>拆书帮\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>1、目标明确\u003c/p>\u003cp>是基于拆书法集结的学习爱好者社群，全国各地都有拆书帮分舵（也叫拆书帮俱乐部）\u003c/p>\u003cp>2、公益性自组织\u003c/p>\u003cp>我们在一起吸收书给我们的力量。在提取总结书中的能量，再把精髓的分享给所有爱好读书的人们。\u003c/p>\u003cp>3、分享传播\u003c/p>\u003cp>在他们在一起成长，他们热爱蜕变的感觉。一起释放学习促进者的能量。他们分享，传播，给予，付出。&nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10395,"quote":"\u003cp>很多情况下，你并不需要从头开始。打个比方，我在教那些写作有困难的人写文章的时候，我会建议他们准备一盒索引卡，记录下天中他们脑子里所冒出来的所有想法。这个方法可以很容易地运用到书写商业计划、开创新发明，或者任何其他大目标的实现过程中。\u003c/p>\u003cp>把这些卡片收集起来，差不多每周都拿出来翻一翻，看看这些想法是不是能拿出来用，或者这些想法能不能促使你想到其他主意。然后再决定你现在能做这一大项工作中的哪一小块。如果你正在写一部小说，你可能已经对最后的关键场最进行了设想，那么完全没理由不先把这个场景的情形写下来，然后再完成之前的其他剧情，如果你正考虑开创一种新产品，而你早就想好了新产品要怎么包装，那么你完全可以在产品完成之前先处理包装方面的工作。如果你选择以做你做得有意思的事情为开始，这么在做的同时你已经为剩余的工作准备好了冲动。\u003c/p>\u003cp>花一分钟想想你的某一个目标。这个目标的哪一部分对你来说是最有吸引力的?不管它们是否与逻辑上正常的开头相关。哪些部分能让你足够激动到想要今天或者明天就立即开始?\u003c/p>\u003cp>捕捉你的灵感：\u003c/p>\u003cp>如果在灵感乍现的瞬间你没能及时捕获它们，很有可能你很快会忘掉这些灵感。你可以周纸、笔，或者索引卡，或录音笔，或者你可以给自己打电话，把这些想法记录在语音邮件\u003c/p>\u003cp>上。要经常捕获这些想法，然后决定哪些可以付诸行动。\u003c/p>","explains":"\u003cp>很多情况下，你并不需要从头开始、打个比方，我在教那些写作有人写文章的时候，我会建议他们准备一盒索引卡，记录下一天中他们脑子里所冒出来的所有想法。这个方法可以很容易地运用到书写商业计划、开创新发明，或者任何其他大目标的实现过程中。\u003c/p>\u003cp>把这些卡片收集起来，差不多每周都拿出来翻一翻，看看这些想法是不是能拿出来用，或者这些想法能不能促使你想到其他主意。然后再决定你现在能做这一大项工作中的哪一小块。如果你正在写一部小说，你可能已经对最后的关键场景进行了设想，那么完全没理由不先把这个场景的情形写下来，然后再完成之前的其他剧情。如果你正考虑开创一种新产品，而你早就想好了新产品要怎么包装，那么你完全可以在产品完成之前先处理包装方面的工作。如果你选择以做你觉得有意思的事情为开始，这么在做的同时你已经为剩余的工作准备好了冲劲。\u003c/p>\u003cp>花一分钟想想你的某一个目标。这个哪一部分对你来说是最有用的？不管它们是否与正常的开头相关。哪些部分能让你足够激动到想要今天或者明天就立即开始？\u003c/p>\u003cp>\u003cstrong>【I：用自己的话重述原文】\u003c/strong>\u003c/p>\u003cp>What:点子想法有去处，索引卡助我们不时之需，不必从头来。\u003c/p>\u003cp>Why:我们是否有过类似的经历，万事开头难，可我们却必须要从头做起，不容我们从旁支入手。不然就会有个声音跳出来说：“不可以！必须从头开始，哪有大框架都没想好，就去想细节的，不合规矩”，就像玩射箭，一开始就要求我们命中靶心，可我们只想先研究下弓是怎么拉的，靶子是用什么东西做的。来自外界的巨大的压力让我们在原地是做呢还是不做呢，那样的我们看起来好像很糟糕。\u003c/p>\u003cp>噢！那怎么办？让我们来看一看，这种情况可能会发生在哪些时候，哪些场合？\u003c/p>\u003cp>Where:写文章的时候、书写商业计划、开创一个项目、写一部小说、投入一个兴趣爱好，考虑开创一种新产品或者任何其他大目标的实现过程中。。。。。。\u003c/p>\u003cp>看起来，这些场景有些熟悉吗？其实我们就其中的一部分已有了一个好的主意，那么我们如何应对呢？能够既轻松，又容易的想先开动起来。\u003c/p>\u003cp>How:\u003c/p>\u003cp>1、准备一盒索引卡。记录下一天中脑子里所冒出来的所有想法。\u003c/p>\u003cp>2、把这些卡片收集起来，每周都拿出来翻一翻，看看这些想法是不是能拿出来用。\u003c/p>\u003cp>3、给那些可以用的上的，画一个“心”。\u003c/p>\u003cp>想想就好激动，对不对？当我们觉得：“我们是可以的”时候。就是选择了有意思的事情来开始行动，那么我们在做的同时就已经为剩余的工作准备好了冲劲。\u003c/p>","interaction":"\u003cp>【A1：描述自己的相关经验】\u003c/p>\u003cp>经验：我一直自认为是“点子王”，每天脑子里能产生大量的想法来，有时候大家一讨论，更是灵感爆棚。因为脑子转太快、点子产量大，我就会即时表达出来，但点子出现的时机不对，就会被嫌弃。比如，我在策划一个沙龙方案时，会突然有个画面感强的超赞的主意。同事就会告诉我：“不行的，我们在讨论前面的，你这个放在最后合适，或是这个不适合这次沙龙。”我当下就会很受伤，选择不说话。\u003c/p>\u003cp>由于方案需要我来写，我就会认为这个方案好难写，这个也不行，那个也不行，我想这么好的点子，怎么大家都没人呼应我呢？\u003c/p>\u003cp>反思：现在想想，我可以做的是：\u003c/p>\u003cp>1、我不必太在意别人的话语，因为我需要把注意力集中在我可以积极关注的部分。\u003c/p>\u003cp>2、这次不适合的点子，我就先通过索引卡记下来。\u003c/p>\u003cp>如：\u003c/p>\u003cp>1.1\u003c/p>\u003cp>－我突然想到可以为客户定制沙龙，可分为男性主题沙龙，女性气质沙龙，家庭亲子沙龙等。\u003c/p>\u003cp>－如果在企业领导的需求中结合员工需求中寻找到共同点，就能解决我之前对于课件标题和课程设计的困扰了。\u003c/p>\u003cp>1.2\u003c/p>\u003cp>－在每次活动计划中，我把固定的框架复制好，需求补充，我会节省出时间来把细节再丰满。\u003c/p>\u003cp>－每天花5－10分钟时间专注在“我”能做的意识中，冥想放松。\u003c/p>\u003cp>【A2：我的应用（目标与行动）】\u003c/p>\u003cp>目标：做我喜欢的部分，保持动力去有效快速行动。\u003c/p>\u003cp>时间：立即做起，计划一周内完成这个习惯。\u003c/p>\u003cp>工具：\u003c/p>\u003cp>手工工具－五色便签纸、一个空盒子，水笔一支。\u003c/p>\u003cp>电子工具－下载有道或简书APP，随时可记录。\u003c/p>\u003cp>行为：\u003c/p>\u003cp>手工\u003c/p>\u003cp>1、手头有纸就可以写下来。\u003c/p>\u003cp>2、放入空盒子。\u003c/p>\u003cp>3、每周整理一次好点子（感觉自己像个油田）\u003c/p>\u003cp>4、可以被使用上的，就在上面标记“爱心”，并奖励自己一次（写好自己最喜欢的也可以抽）。\u003c/p>\u003cp>电子\u003c/p>\u003cp>1、有道随时记录好点子。\u003c/p>\u003cp>2、每天完成一篇简书，挑战日更。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1547028932000,"updated_at":1547208004000,"ria":true},{"id":6662,"topic":"如何认可他人","learn_goal":"1-2过级：如何认可他人","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"涂晓闻","city":"济南"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>【分发拆页】\u003c/p>\u003cp>【自我介绍】大家好，我是涂晓闻，现在是一个三岁孩子的宝妈，职业是一个资深的平面设计师，从事设计7年，平时爱好写作、阅读和手工。近期阅读的书目多为育儿类和专注力方向，后期也会给大家带来这两个方向的分享。\u003c/p>\u003cp>【分组】今天参加活动的一共四个人，那我们就可以分成两组，按照座次相对而坐的为一组。\u003c/p>\u003cp>【图书介绍】﻿今天我们要进行的拆页来自于《专注力——化繁为简的惊人力量》一书，该书作者于尔根•沃尔夫，是一位成功的作家、演讲家和咨询顾问。\u003c/p>\u003cp>作者用17个章节，教给我们拥有专注力的有效策略，书中非常多的测试题能够帮助我们更好的将书中原理与个人生活中的不同状况对应起来。\u003c/p>\u003cp>这本书，是一本非常实用的指导书，是训练自身专注力的入门级书目。﻿本书语言浅显易懂，采用一步步分解问题，解决问题的模式，书的最后还有整本思路的总结。提供了一系列提高效率，攻克生活和工作困难瓶颈的有效方法。\u003c/p>","ratings_count":1,"texts":[{"id":10003,"quote":"\u003cp>极具讽刺意味的是,尽管人们最想得到的东西并不需要我们付出什么,但大多数人对此却非常吝啬。可能我们担心表扬或欣赏感会不真诚,或者这样做会让我们感觉自己显得渺小。这并不对,当然，如果你能战胜自己天生的沉默,你会惊奇地发现这会给你的关系带来怎样的改善。以下是给予人们所希望认可的方法。\u003cbr>\u003c/p>\u003cp>1,学会倾听。大多数情况下,当有人和我们说话时,我们听到一半的时候就走神,开始想要怎样对我们听到的内容进行评论,而不是注意听别人把事情说完。不要这样做,注意用心倾听他人所说，直到结束，你依然可以很快给出答案或者评论。第9章对这一点进行了更详细的阐述,专注于语言卓越的力量。\u003c/p>\u003cp>2,增加目光接触。大多数人在倾听他人说话时都会保持很好的目光接触,但当他们自己说话的时候,情况就不一样了。当然,你想要自然的而不是令人不悦的凝视,即便如此,如果你能增加和对方目光接触的时间,哪怕只增加25%,谈话效果会有很大不同。如果直视他人的双眼会让你觉得紧张,你可以把目光放在双眼中间,或者轻轻地让你的目光在他们左右眼间移动。不过,不要过多地把注意力集中在这件事情上,以免无法注意别人所说的话。\u003c/p>\u003cp>3,以姓名称呼对方。我并不是建议你像肥皂剧里所表演的那样每句话都要以他人的姓名来开头,只是很随意地在谈话中偶尔提到。最自然的做法就是刚见面打招呼时以及道别时提到他们的姓名。虽然这种做法很没创意,不过人们最爱听到的声音确实就是自己的名字。\u003c/p>\u003cp>4,给出真诚的赞美。这可以是他人姣好的外貌、一件衣服、一件别人刚做的事情或者其他任何事。如果你真心觉得这值得赞美,这些话听起来就不会让人觉得虚伪,即便在你习惯这么做之前还是觉有些不真实。你不必做得太过火。这可以是简单的赞扬,比如“那双鞋真好看”,或者“你在会上提出的观点很正确,这对事情的进展非常有帮助&quot;。\u003c/p>","explains":"\u003cp>【what 知识点阐述】这个拆页教我们如何向他人表达真诚认可的方法，总共四个步骤，分别是少说多倾听，目光要接触，称呼对方用姓名和给对方适当、真诚的赞美，学会用这个方法认可他人，会帮助我们改善社会关系。\u003c/p>\u003cp>【Why前因后果说明】人们都渴望认同感，我们都希望能够被他人欣赏、关注，希望自己与众不同。\u003c/p>\u003cp>如果学会了认可他人，并且能积极地要求自己始终如一的这样做，会极大的改善我们与周围人的关系，我们自己会成为非常有魅力的人，人们也都很乐于帮我们实现目标。\u003c/p>\u003cp>【When适用边界 】当你想要改善与他人与社会的关系时，如果你想要拉近与人的距离，与家人更亲密，与同事相处更融洽，与朋友关系更友好，可以使用这个方法。如果你想真诚地传达出你的善意，那么你也可以使用这个方法。当然如果你想要提升自己的魅力，让更多人喜欢自己，这个拆页里的方法也一样适用。\u003c/p>\u003cp>【How步骤流程】人们常常不善于认同和赞美他人，我们可以用下面的步骤进行改变:\u003c/p>\u003cp>第一，倾听要用心，少说多听。不要着急在听到一半时，拼命想怎么评论别人所说的。而是用心倾听他人所说，直到对方说完，尽量不打断别人。\u003c/p>\u003cp>第二，目光接触时间要适当的增加。不仅是在倾听别人说话时要保持良好的目光接触，我们自己说话时更要注意增加与对方眼神交流的时间。可以把目光放在对方的两眼中间或左右移动，这样可以避免一直盯着对方的眼睛带来的尴尬。\u003c/p>\u003cp>第三，称呼对方要说出对方的姓名。方式要自然，在打招呼或告别时提及对方姓名是最自然的，也可以根据交谈内容，在谈话中间偶尔提到。\u003c/p>\u003cp>第四，赞美对方要真诚、自然。在自己真的觉得不错的地方，给出对方简单的赞扬即可，可以是对方的衣服或某一行为，也可以是一些细节。\u003c/p>\u003cp>\u003cstrong>【\u003cstrong>例子\u003c/strong>】\u003c/strong>处女座的老公每周末都会很认真的打扫家里卫生，打扫完他总会说你看我打扫的多干净，东西放的多整齐……希望得到我的认可，而我只是通常只是简单的说一句，辛苦了，时间长了他就会抱怨我对他不够认可。上周看了这个片段后我试着用书里的方法和他沟通，在他做完家务再次向我夸耀时，我耐心听他说完，并在他说的过程中注视着他的眼睛，最后还提着他的名字夸赞他。最后的结果是他很开心，觉得自己的劳动成果终于得到了认可。\u003c/p>","interaction":"\u003cp>[A1激活经验]\u003c/p>\u003cp>【拆书家提问设计】请你想一想自己在过去的经验中，当你向别人表达认可时你是怎么说的， 请大家以小组为单位，我们一起分享一下吧。时间是5分钟\u003c/p>\u003cp>【现场完整案例•学习者：杜鹃】以人马点评为例，一般点评的话点评人员会认真听演讲人员整个的演讲过程，点评过程中点评人员站在前面，他面对的除了演讲者还有其他人，所以他们的眼光是来回移动的，但是他始终会让被点者感受到自己的关注。而且点评时在开头和最后都会说感谢XXX的演讲，一定会提到被点评人员的的名字。 而且采用汉堡包式的赞美，虽然演讲者会有很多不足，但是在开始和最后一定会赞美他们的优点，而把不足放在中间来讲，这就让被点评人员感受到你的真诚，因为你没有一味在夸对方，而开头和结尾的赞美也会让被点评人员感到舒服。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>\u003cstrong>【拆书家提问设计】\u003c/strong>学会了表达认可这个技能以后，你在近期打算如何在同事沟通、朋友相处或者亲子交流中进行应用呢？请把你未来一周内的应用计划，分步骤写在便签纸上吧。\u003c/p>\u003cp>【现场完整案例•学习者：千尘&nbsp;】针对我的下属某姑娘，我想再下个项目中给与她更充分的认可，我打算从下面四个方面来表达我的认可和赞美\u003c/p>\u003cp>首先，工作过程中会有和她交流的环节，一定注意自己不打断她，认真听她把话说完；\u003c/p>\u003cp>第二，在交谈过程中，要注意看她的眼睛，多跟对方进行眼神的交流；\u003c/p>\u003cp>第三，跟小晨说话的时候在开头和结尾称呼她的名字，比如小晨今天我们要做什么，小晨今天你表现得怎么样；\u003c/p>\u003cp>第四，对她工作中做的好的环节进行赞美，尤其她有做事快效率，会重点表扬一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1543899179000,"updated_at":1544158366000,"ria":true},{"id":6274,"topic":"战胜拖延","learn_goal":"运用视觉、听觉、味觉、嗅觉、感觉，想象克服拖延后的积极的画面","remark":" 整个世界好像串通好了要一致阻碍你拥有专注力。每时每刻，你忙于应付外界的各种干扰。!要想改变这种手忙脚乱四处救火的情形，你必须拥有专注力!从现在开始，认清对你来说最重要的事，排除一切无关干扰，专注地投入其中。你的成功概率将以指数方式增长!实现你心中真正渴望的目标!拥有专注力的有效策略:·时间管理策略·右脑适用策略·优势策略·战胜拖延策略·第二自我策略。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"玲珍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是今晚的拆书家玲珍，很高兴今天晚上有机会和大家一起学习成长。首先，我想借助一张导图来做简单的自我介绍：我现在在佛山的一家外资银行工作，平时喜欢阅读和户外徒步。在个人学习成长方面，2018年的第一个季度我专注于时间管理和亲密关系方面的学习和实践，在这个过程中，我除了参加一些课程外，还运用拆书帮的拆书法阅读相关主题的书籍，取得了一定的效果。\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003cbr>\u003c/p>\u003cp>什么是拆书帮以及拆书法呢？下面我会为大家介绍一下。\u003c/p>\u003cp>不知道在大家身上有没有遇到以下类似的问题：读书毕业后就不再读书了觉得读书没有用，或者买了不少别人眼中的好书，可是自己却看不下去而为此懊恼，又或者是热爱读书的伙伴，书读了很多，可是真正运用到生活工作的却很少。当阅读的效果不明显时，读书的动力就减弱了。如果运用拆书帮的RIA读书方法，就能有效地解决以上的一些问题。\u003c/p>\u003cp>&nbsp;“拆书”是运用RIA的一种读书方法，它是以学习者为中心而不是知识为中心，也就是说学习者不是盲目而是带着具体目的去选书读书，并且在阅读的过程中把知识与学习者的经验关联，规划具体运用，把书中的方法落实到工作生活中，让工作生活发生积极的改变。R是reading阅读原文；I是interpretation指的是用自己的语言复述原文内容；A是appropriation，包括了A1和A2，A1是指联结过往经验，A2是规划未来行动。所以说RIA&nbsp;法是把知识、经验、未来行动结合的学习方法。\u003c/p>\u003cp>拆书可分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，组织学习的应用是一位拆书家在现场引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>&nbsp;“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵， “拆书帮”分舵是公益性青年组织，其使命是帮助更多学习爱好者成为拆书家。\u003c/p>","ratings_count":0,"texts":[{"id":9564,"quote":"\u003cp>今天我们拆解的是自我管理类片段，选自《专注力》 &nbsp; 71-72页关于“拖延的诱惑力和如何战胜拖延”的内容。\u003c/p>\u003cp>下面请大家用3分钟时间阅读原文片段，对于有感觉的内容不妨用笔画出来，阅读完的伙伴请眼神示意我一下。\u003c/p>\u003cp>【R阅读原文片段】\u003c/p>\u003cp>所以,为了改变方向,我们需要做努力。但为什么做这件事会这么难呢?我们都清楚这么做的好处是什么。比如,吃健康的食物、锻炼或者有分寸地做事,而不是一直拖到最后一秒才做?&nbsp;\u003c/p>\u003cp>一个原因就是“错误”的选项在当下显得非常有吸引力。“正确”选项的吸引力(或者忽视正确选项的惩罚)在当下显得很弱,它的吸引力要长期才能体现出来。关键问题是:通常而言,“正确”选项在长期才能给我们带来回报。“错误”选项的回报则是立竿见影的。因此,“错误”选项的吸引力会比较强。举个例子,假设接下来我选择花几个小时浏览网页,这马上就能给我带来欢乐。可能我确实应该写那份两个礼拜后就该交的报告，不过就算我现在不作报告,即刻也不会有什么惩罚或者不利情况出现。&nbsp;\u003c/p>\u003cp>这里有个办法可以让你每次做出更好的选择:选择“正确”选项的秘诀就是将正确的选项变得和“错误”选项一样生动，一样富有感情,一样的吸引脸人。怎样才能做到这一点?发挥你的想象力，用比感知“错误”选项更强烈的态度去观察、倾听、品尝、闻、感受“正确”选项。&nbsp;\u003c/p>\u003cp>1.闭上你的双眼,开始想象“正确”选项将带来的结果。这很重要:不要想象你做这件事情的过程,想象最终结果或者阶段性的成果。&nbsp;\u003c/p>\u003cp>2.当完成这件事你将看到什么?比如,你刚开始为自己的生意写经营计划,当生意取得成功,你将看到什么?如果你所经营的生意是一家店铺,你可以想象店里充满热情的顾客。&nbsp;\u003c/p>\u003cp>3.你将听到些什么?可能你会想象顾客称赞你所销售的货物或者把你的生意打电话告诉他们的朋友。&nbsp;\u003c/p>\u003cp>4.你将感受到什么?这可能是最重要的部分,可能你会觉得骄傲、开心、兴奋和欢乐。&nbsp;\u003c/p>\u003cp>5.有时候你可以想象一些味道。你可能会想象自己在闻一些摆放在台上鲜花的味道。&nbsp;\u003c/p>\u003cp>6.甚至味觉也能成为一个因素。你可能会想象举办一场晚宴来庆祝开业，有人向你敬酒,你喝了一杯香槟。\u003c/p>\u003cp>你想象得越生动越令人兴奋,你就能为开始这项工作释放更多能量。 &nbsp;&nbsp;\u003c/p>","explains":"\u003cp>【分享I便签】\u003c/p>\u003cp>\u003cbr>刚才我们已经完成了拆书法RIA中R &nbsp; reading阅读原文的部分，下面我们一起进入I&nbsp;interpretation这部分，我将会引导大家一起理解原文片段：\u003cbr>\u003c/p>\u003cp>（What）当我们要做出改变的时候，是要付出努力的，如果付出努力会让我们感到不舒服，就会出现拖延的情况。\u003c/p>\u003cp>（Why）出现拖延的时候，是因为当前的状态更加舒适，更有吸引力，而付出努力之后的成果并不在眼前，没有足够的吸引力。如果我现在正躺在沙发上看电视，突然我想起来现在我应该要收拾我混乱的房间，这时看电视的当前诱惑是很大的，而收拾房间的过程是相对痛苦的并且收拾后的成果并不在眼前，所以我们更希望维持看电视的舒适状态。\u003c/p>\u003cp>（How）这时候，如果我们能够让努力后的长期选择结果比当前状态更加有吸引力，那么就能够有效地克服拖延症。如果我们能闭上眼睛发挥我们的想象力，运用视觉、听觉、味觉、嗅觉、感觉让努力后成功的画面更加具体有吸引力，我们就会更有动力行动起来，克服拖延症。\u003c/p>\u003cp>1.闭上眼睛想象做出努力后的结果，不要去想具体过程；\u003c/p>\u003cp>2.想象完成这件事情后能看到什么画面,例如房间整理后，书籍整齐地放回了书柜，衣服都收进了衣橱，飘窗只放了两个靠垫没有其他杂物；\u003c/p>\u003cp>3.想象会听到什么？例如先生称赞“你是一位体贴的妻子”；\u003c/p>\u003cp>4.想象当完成这件事情后你能感受到什么，有什么样的心情，比如房间整理后你感到很愉悦放松；\u003c/p>\u003cp>5.想象闻到什么气味，比如是刚刚换洗的床单上还保留着淡淡的清香。\u003c/p>\u003cp>6.想象尝到的味道，你终于收拾好房间，奖励自己喝一杯甜甜的果汁。\u003c/p>","interaction":"\u003cp>【分享A1便签】\u003c/p>\u003cp>结合原文片段，我联想到自己的一个过往经历：\u003c/p>\u003cp>6月底的时候，我要在两周内准备一份20页的英文资料，用于参加行业内的比赛。第一个星期的时候当我想到要整理的资料数据很多，要联系不同的同事，要花费很长时间，当我越想这些困难的时候，就越害怕开始，一直拖延着，情愿把时间花到追电视剧上。在最后一周时间已经非常紧迫了，我需要每天早上4点钟起床赶工，最后即使能够完成任务，但由于休息不够，严重影响第二天的工作效率以及身体健康。如果回到当时，我能运用拆页中的技巧，把获奖时的画面想象得生动具体有吸引力，我会更早地开始准备参赛资料而不是选择看电视剧了。\u003c/p>\u003cp>\u003cbr>我可以闭上双眼想象在华丽的颁奖现场，我在领奖台上接过奖杯，看到台下的同事为我鼓掌拍照，听到同事为我欢呼，此时我感到很骄傲，感到所有的前期付出都值得。颁奖晚会上我还品尝到美味的食物，闻到阵阵香槟的气味。\u003cbr>\u003c/p>\u003cp>【分享A2便签】\u003c/p>\u003cp>学习了克服拖延的方法后，我会运用到学习开车中去：\u003c/p>\u003cp>我的目标是在4月前要能够自己独立开车上下班。\u003c/p>\u003cp>每周工作日花两个晚上每晚练车30分钟，周末白天花两个小时练车。当我出现拖延时，我会闭上双眼想象最终成果：我能够熟练地在环城高速上开车上下班，即使车旁有很多大货车经过，我也能淡定地应对。当我回到小区，天色还没有暗下来，我还可以看到放学的小朋友三三两联两地在玩耍，听到他们的欢笑声，打开家门，闻到阵阵的浓汤的香气，看到家人正为我们准备晚餐，我可以和家人一起共进晚餐，吃到热腾腾可口的饭菜，让我感受到更多温馨的生活气息。当这些画面在我脑海中过一遍后，我行动起来的动力就更强了。\u003c/p>\u003cp>结尾：\u003c/p>\u003cp>如果你在拖延做某件事情，可以发挥我们的想象力，去观察、倾听、品尝、闻、感受行动后取得成功的画面，让画面生动有吸引力，那我们就会更有动力行动起来。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1540033333000,"updated_at":1540033601000,"ria":true},{"id":5914,"topic":"向野拆书升级挑战","learn_goal":"学习MAD法，搞定工作无压力","remark":"","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"向野","city":"济南"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>&nbsp;\u003cstrong>【分发拆页】&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>大家好，我是向野，我的名字源于《论语•雍也》：“质胜文则野；文胜质则史。文质彬彬；然后君子。”一句，感觉自己史而野不足，故称向野。 下边我用三个标签来介绍一下自己，第一个标签是甲方，我在零售行业任职，主要从事宣传和活动组织工作，就是传说中的广告主，就是让所有策划和文案痛不欲生的甲方。第二个标签，兼职文案，正所谓上班甲方虐人，下班乙方被虐，我的文案大多是德芙、维他奶之类的快消品公号文章，一篇文案改个十几遍的经历不少，但依然乐此不疲。第三个标签就是学习成长者，因为无论是工作还是兼职都要求我有丰富的知识准备，不断精进，所以喜欢看书，乐于精进，正是在这个过程中认识了拆书帮，于我而言，拆书帮是一个扩大朋友圈，给自己赋能的平台，希望在这里和大家一起成长，精进。\u003c/p>\u003cp>&nbsp;\u003cstrong>【书籍介绍】\u003c/strong>今天我带给大家的书籍是《专注力：化繁为简的惊人力量》整个世界好像串通好了要一致阻碍你拥有专注力。每时每刻，你忙于应付外界的各种干扰。这种情况下，若你还能取得一星半点的成就，那简直是奇迹！要想改变这种手忙脚乱四处救火的情形，你必须拥有专注力。《专注力》便是教授我们保持专注方法的一本书。作者于尔根•沃尔夫（Jurgen Wolff）作家、演讲家和咨询顾问，著有包括《你的写作导师》、《做些不一样的事》以及《创造力，从现在开始！》等书，他的文章中充满各种能使你更具创造力、更富成效的方法和技巧。 &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>【\u003cstrong>分组】\u003c/strong>今天我们一共4个人，那我们今天就按照桌子左右两侧，每2个人分一个组，请千尘和药山分别作一下组长。下面我们直接进入拆书的环节，请大家先阅读一下拆页，阅读完了请举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":9138,"quote":"\u003cp>大多数项目都有进度减慢、延迟或其他不顺利的事情发生的时候，这不仅会减弱参与者的动力，也会消弱士气。这是使用高度专注技巧的好时机。我将这一技巧成为MAD：大规模行动日（MASSIVE ACTION DAY首字母的缩写）。这一天你抛开其他所有事，集中全部注意力，在8个、10个或12个小时内完成平时可能花一星期才能完成的事。当然你并不会想要一直保持这个速度；这和长跑运动员要超过对手时所进行的冲刺道理相同。他能够给项目注入新的能量，能量重振你和其他人的热情和信心。以下是如何进行MAD的方法：\u003c/p>\u003cp>1. 提前一天准备好所有必须物品和文件。在大规模行动日，你不想为寻找文件、订书机、或任何其他东西而浪费一点时间。\u003c/p>\u003cp>2.在大规模行动日开始时为这一天设定明确的目标。制定一份一小时为单位的行动计划。\u003c/p>\u003cp>3.完成每项任务后再计划表上相应做出记号，保持享受任务完成所带来的成就感。\u003c/p>\u003cp>4.每90分钟休息一次。研究表明，90分钟是注意力集中的循环周期，所以没过一个半小时休息10分钟将会比连续工作更具成效。\u003c/p>\u003cp>5.在休息时做些体力活动：绕建筑物快走或上下楼梯，伸展运动甚至原地跑步都可以。你可以做任何能够加速血液流动的事。保证大量饮用水和健康零食的供给。如果你通过喝咖啡或者喝茶来保持清醒，要少量多饮，而不要多量饮水。\u003c/p>\u003cp>6.在大规模行动日结束时，进行庆祝并给自己一定的奖励——一顿丰盛的晚餐，看场电影，或者任何其他你喜欢的事。\u003c/p>","explains":"\u003cp>【I】\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>what\u003c/strong>\u003cstrong>知识点阐述】\u003c/strong>这段拆页是在介绍一种叫MAD的技能， MAD是“大规模行动日”的缩写，这是为完成高强度的工作而保持专注力的方法。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>why\u003c/strong>\u003cstrong>前因后果说明】\u003c/strong>当你临近工作期限的时候，当你需要短时间内完成巨量工作的时候，这个技能便是你的救命绝技，它可以让我们有目标、有节奏的保持专注力。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>where \u003c/strong>\u003cstrong>适用范围】\u003c/strong>本方法适用于当工作进度滞后或不顺利，需要有一天抛开所有事，集中注意力，完成一周或者更长时间工作的情况。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>how\u003c/strong>\u003cstrong>步骤流程】\u003c/strong>MAD技能的步骤具体如下：\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）提前准备：\u003c/strong>准备好所需工具和资料，高压之下，我们不想为找东西而分心，要保持最高的效率。\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>）明确目标：\u003c/strong>首先我们要为这一天定一个明确的大目标，而后拆解目标制定每一个小时的工作行动计划。\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>）阶段激励：\u003c/strong>完成计划表上每一个部分都要做出记号，用成就感激励自己。\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>4\u003c/strong>\u003cstrong>）把握节奏：\u003c/strong>90分钟休息一次，因为90分钟是注意力集中的极限，合理的休息让工作更有节律。\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>5\u003c/strong>\u003cstrong>）休息有方：\u003c/strong>做点运动，来回走走，加速血液循环。做点舒展运动；喝点东西、吃点零食，让高强度的工作自己有个喘息的机会。如果你通过喝咖啡或者喝茶来保持清醒，要少量多饮，而不要多量饮水。\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>6\u003c/strong>\u003cstrong>）要有奖励：\u003c/strong>完成大规模行动日后，要适当的奖励自己，吃点好的，玩点好的等等。\u003c/p>\u003cp>\u003cstrong>【例子】\u003c/strong>我们部室是要负责全年总结会议的，筹备时间会是一个月，在工作中因为涉及多部门协调，经常出现滞后和不顺利的情况，就需要我们在临近会议日期的某一个周天加班，赶进度。这一天主要工作就是领导发言材料、PPT制作等等工作，劳动强度不是一般的大。因为巨大的压力所以那一天真的很难熬，难以保持专注力，效率也特别低下。如果之后再遇到这种情况，我会运用MAD法则这样做：（1）在开会前一周便已经按照往年的情况将想要的材料准备好了，并且建立了索引标签系统，比如超市开店情况，只要我搜索超市、开店两个关键词相关材料就可以出来了。（2）而后将工作进行划分，明确每个小时要做什么，要写出那个段落，比如超市的利润情况等等。（3）每隔一段时间休息一次，保持节奏。一般是做颈椎操。（4）当然工作之后用大餐或其他方式奖励，棒棒的自己是必不可少的啦。\u003c/p>","interaction":"\u003cp>【A1激活学习者经验】以上我们对拆页有了具体的了解，知道了在高强度的大规模行动日保持专注力的MAD方法，下面请大家想自己有没有类似的经历，短时间内要完成大规模的任务，比如一天要完成一周工作的痛苦经历，但是我们面对排山倒海、迫在眉睫的任务，我们却难以专注，效率地下，只能仰天长啸、暗自神伤，只能敷衍了事，难以高效，更得不到上级的认同。让我们一起在小组内进行分享。注意实例或者经验一定要涉及自己，一定要是具体的某一件事情。分享时间5分钟，下面请千尘和大家一起分享一下自己的相关经验。\u003c/p>\u003cp>【\u003cstrong>现场完整案例\u003c/strong>\u003cstrong>•学习者：千尘\u003c/strong>】之前要准备拆书课，初步认为需要1-2天的时间，但真正做起来发现需要更长的时间才能完成，最后只能在最后期限前，用一天的时间去补上进度，但是因为之前没有准备，也没有明确出具体的目标，并将其拆分成具体的计划。所以只能草草的选定书籍，尽快的完成相关内容，完全强迫自己在准备工作中没有丝毫的休息时间，虽然弄到晚上12点，但是因为高强度的工作下，难以保持专注力，效率十分低下，最终还是导致了任务的拖延，而且自己也疲惫不堪。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>催化学习者应用】\u003c/strong>下面请大家将综合以上的讲解和分享，将MAD方法应用规划写在便签上，未来一段时间内是否有这样需要短时间完成大强度工作的情况，在这个工作中我们如何使用MAD法则来实现专注力和效率的提升。注意要有具体的做法、有明确的实限、有可衡量或可观测的预期结果。下面我邀请分享一下自己的A2便签。\u003c/p>\u003cp>【\u003cstrong>现场完整案例\u003c/strong>\u003cstrong>•学习者：药山\u003c/strong>】我们之后8月30日要进行一个十九大报告的考试，政治任务对我十分重要而且复习量很大，但是我又没有一大段时间进行复习，所以计划选择一天集中力量复习，现在学会MAD法则之后我计划如下进行：（1）选择一个安静环境，做好材料及手机在线模拟考试系统准备工作。（2）设定目标为在一天内将考点复习完，估计有几百道题目。根据单选，多选等不同的题型设定阶段性的计划，具体到每一个小时。（3）每隔90分钟休息一次，喝点咖啡等。（4）如果能考试成绩达到90分以上，奖励自己吃顿大餐。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1535372493000,"updated_at":1535440433000,"ria":true},{"id":5804,"topic":"如何保持专注","learn_goal":"通过拆书，学习者能够学会保持专注的4个方法，让工作更有效","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"向野","city":"济南"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>【自我介绍】大家好，我是向野，我的名字源于《论语·雍也》：“质胜文则野；文胜质则史。文质彬彬；然后君子。”一句，感觉自己史而野不足，故称向野。 下边我用三个标签来介绍一下自己，第一个标签是甲方，我在零售行业任职，主要从事宣传和活动组织工作，就是传说中的广告主，就是让所有策划和文案痛不欲生的甲方。第二个标签，兼职文案，正所谓上班甲方虐人，下班乙方被虐，我的文案大多是德芙、维他奶之类的快消品公号文章，一篇文案改个千遍的经历不少，但依然乐此不疲。第三个标签就是学习成长者，因为无论是工作还是兼职都要求我有丰富的知识准备，不断精进，所以喜欢看书，乐于精进，正是在这个过程中认识了拆书帮，于我而言，拆书帮是一个扩大朋友圈，给自己赋能的平台，希望在这里和大家一起成长，精进。\u003c/p>\u003cp>【拆书帮介绍】拆书是一种学习的方法论，它以学习者为中心，与传统学习中的以老师或者知识为中心不同，拆书的立足点是学习者自身的提升和所面临问题的解决。拆书法分为两种，一种是个人的拆书学习法，就是一个人利用便签法，完成整个拆书过程，选择拆页之后，首先进行I便签的部分，就是用自己的语言阐述拆页内容，其次开始A1便签的部分，就是将内容和自己的联想到的相关经验写下来。最后我们完成A2便签写下当你在遇到类似的情况时该如何运用片段中的方法步骤去解决。第二种是组织学习的拆书法。便是由一位拆书家，带领一群学习者共同完成四个便签的内容，将知识拆为己用。\u003c/p>\u003cp>拆书帮就是以热爱拆书学习法的青年组织的社群为基地，构建的公益性组织。在各地的下属组织我们称之为拆书帮分舵。以把更多的学习爱好者培养为拆书家为使命。 &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9012,"quote":"\u003cp>当你对于信息的使用缺乏目的性时，你便无法掌控信息。如果一开始便带有目的性，你会自动对信息进行筛选过滤，这能帮助你分辨有关及无关的信息。多数人接收到的大量邮件就是个很好的例子。有些是需要你关注的私人邮件，有此进立即删除的垃圾邮件，问题是剩下的那些邮件。80/20法则再次适用：这些信息中可能只有20%适用于你最重要的目标，剩余的80%可能只是在一般意义上比较有趣，并没有直接的关系。我们将在第12章具体讨论如何处理邮件，目前还是来看看你所能够运用的四条策略，这些策略同样也可以运用于处理其他来源的信息。\u003c/p>\u003cp>&nbsp; ——在接触新信息之前，先快速提醒自己此时最具吸引力的话题，那些和你最要的目标相关的话题。\u003c/p>\u003cp>&nbsp; ——如果你知道这条信息并不相关，看都不要去看它一眼，直接丢弃这条信息或者先将这条信息搁置在一边，直到它所含的信息可能更加相关时再去看。\u003c/p>\u003cp>&nbsp; ——在可能的时候，分配其他人进行这份材料的查阅工作，告诉他们你正在寻找什么信息。他们可以复印或者扫描相关内容以供你查看。\u003c/p>\u003cp>&nbsp; ——对于你所面对的信息，扫视最要的信息点而不是全部通读。\u003c/p>","explains":"\u003cp>下面我来说一下拆页的主要内容。\u003c/p>\u003cp>【what】文段主要在阐述提高信息处理效率的方法。\u003c/p>\u003cp>【why】主要解决我们在具体工作中信息处理目标不明确，易受不相关信息干扰等因素影响而导致处理效率低下的问题。\u003c/p>\u003cp>【where】主要用于工作中需要大量信息处理的情景中。\u003c/p>\u003cp>【how】拆页中首先提出了二八法则，以目标为导向，来进行信息的筛选，我们所接触的信息中只有2成的信息是和我们的目标相关的，是有价值的，我们只要把握住了这20%便可以高效的处理信息。以便达成我们自己的目标。为了保证我们准确的找到这20%，书中给了我们4个原则。\u003c/p>\u003cp>（1）有的放矢，在收集、查看信息之前要明确目前工作的目标是什么，给所要处理信息一个大致的标准，或者说形象，从而确保整个信息处理过程更加清晰。\u003c/p>\u003cp>（2）摒却不相关信息：当前的信息处理等工作多从电脑、手机上完成，有无数的推送、广告在干扰你。同时要用之前确定的信息标准快速的筛选信息，如果判断某个信息与目标无关，则立即停止浏览。\u003c/p>\u003cp>（3）懂得授权：工作需要团队，信息处理同样也是，要让同事们知道你需要的信息，同时也可以将该项工作授权给对信息更为了解的下属去做。这样可以更加快速的完成既定目标所需的信息。\u003c/p>\u003cp>（4）把握重点：在具体的信息处理中，我们要做的是快速的找到重点信息，切勿全部通读。\u003c/p>","interaction":"\u003cp>【A1】在具体工作中会有很多和信息处理相关内容，但是具体操作中会存在很多问题因为工作原因和媒体沟通的比较多，大多时间是利用微信，但是就是很容易受到不相干信息的干扰，例如昨天我在进行一场活动策划相关的信息处理工作，晚报的业务给我发了活动的策划方案，在接受完方案后，我并没有立即去看方案，而是没有经受住诱惑，浏览了朋友圈，看了几个公号，当我开始看方案的时候已经是20分钟以后了。在这个例子中我就没有能根据自己需要信息的标准，有效的把握重点信息，摒除不相关信息干扰，从而导致了信息处理的效率低下。\u003c/p>\u003cp>【A2】未来一段时期，我们最重要的工作便是店庆活动的宣传策划，为提升在该项工作中的信息处理效率，我决定按以下要点完成相关工作。（1）在工作前明确自己的处理信息的目的。将工作进行分解，根据不同阶段的工作需要制定信息处理的标准。可以用写出来，贴在电脑上。（2）微信等工具尽量使用网页版，页面比较干净，不容易受其他信息的干扰。内部信息传输、沟通可以用OA系统完成。（3）对于自己不熟悉的、或者说基础性的信息处理工作，可以交给相关的同事去做，提高自己的信息处理效率。（4）信息处理时要把握重点，迅速判断是否和工作目标相关，例如搜索同行店庆案例，便只看相关内容，浏览时先看重点，如有必要再看细节。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1534249306000,"updated_at":1534250167000,"ria":true},{"id":5481,"topic":"专注力的方法","learn_goal":"3-1","remark":"工作和生活中总有一些必须马上去做的事情，但这件事却不是你情愿去做的所以在不得不在时我们总会拖拖拉拉。如何将坏情绪转化，高效率完成任务？","level":"TF3-1","duration":25,"status":30,"type":0,"chaishujia":{"username":"月宫","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，欢迎大家来到今晚的拆书现场。做个自我介绍，张力珩。三个标签：体验式培训倡导者、国际色彩（服饰）搭配认证师/户外爱好者。稍后我们分为两个小组，通过今天的学习，大家能够解决情绪不好时而无法专注做一件事的问题。\r\n【场景法介绍】\r\n【事件】工作和生活中总有一些必须马上去做的事情，但这件事却不是你情愿去做的。比如，领导要求你去档案室整理文件，但这并不是你职责内的。因为心情不好，所以做起来也拖拖沓沓，无法做到专注。\r\n【提问】之前你遇到这种情况都是怎样处理的？是不是没想到更好的解决办法？\r\n【影响】如果每次遇到这类事情，你总是无法做到专注，那么你会浪费更多的时间来处理，也无法给到领导满意的结果。不仅影响了自己的本职工作，还使得领导对你的工作能力产生质疑。\r\n【解决】这本书中提出的思路比如利用“第二自我”策略在规定时间内完成任何任务，或者利用平均残差绝对值（MAD）策略快速解决进展缓慢或者让人感觉进退两难的项目。你将要体验的，正是这样一条捷径。可以帮你解决问题，甚至你的收获比你想象的要多。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8651,"quote":"\u003cp>“第二自我”策略是关于决定你的众多性格中哪一条对给定最有效，以及让这一性格进行主导。我把这些性格称作你的“第二自我”。让正确的性格做主，你会发现自己的办事效率变得更高，并且所需承受的压力也会更少，甚至你会觉得做这些事很有乐趣。\u003c/p>\u003cp>你可以在需要对某一情形进行反应时或者计划做某一任务时对“第二自我”进行选择。首先，如果在某些情况下你的反应总是毫无建设性可言，你可以停止做出这种反应，用其他方式进行替代。这么做的一个例子就是在你愤怒的时候，“从一数到十”。在不满情绪不断上升的情况下，这给你时间考虑不满情绪是否真的有用，也给你时间重新进行反应。即使“急性子的你”想要控制场面，你还是可以选择让“坚定而冷静的你”来处理问题。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;当你准备着手处理一项任务时，这也同样有效。假如你得打扫车库，但你真的不想做这件事。你宁愿四处闲逛，或者看看今天早上刚寄来的杂志。你可能会拖拉着不去打扫车库，或者你可能会强迫自已清理车库，但你还是会想着出去逛逛或者看看书要比这有意思得多。如果你做后者，这项工作很有可能会花费你更多的时间，完成得也很一般，当然也没什么乐趣可言。\u003c/p>","explains":"\u003cp>【学习目标】大家跟我学完这个片段后，能够【可观察到的动作】使用第二自我策略解决【具体内容】情绪不好时无法专注完成一件事情的问题。【完成程度】提升效率，快速实现目标。\u003c/p>\u003cp>【概念讲解】大家回忆下，我们在不同情境下是否呈现出不同的性格。比如，跟小孩子讲话和我们接到诈骗电话我们的反应一定的不同的。其实我们每个人的性格中都具有霸道总裁的主动快速强势、万人迷的热情积极爱炫、温家宝总理的平和亲切和法官执法时的严谨刻板不苟言笑。当你接到一项你不喜欢完成的任务时，先分析出最适合完成这项任务的角色，然后参照他们的性格特点调动自己，并将自己代入角色，完成“第二自我”策略。\u003c/p>\u003cp>【易混淆例子】小A是一名财务，领导要求她在客户来之前把会议室收拾了。虽然小A很不情愿，但她还是没反驳领导，忍气吞声去做了。“忍气吞声”是使用第二自我策略么？不是，因为她没给自己选择的机会。\u003c/p>\u003cp>周末在家大扫除，看到满屋的凌乱我就想，如果有一位心细又手脚麻利的家政阿姨帮我收拾就好了。我躺在沙发里，幻想着阿姨忙前忙后，屋子瞬间整洁明亮。“幻想”是使用第二自我策略么？当然也不是，因为没有实际行动。\u003c/p>\u003cp>【概念提出】那什么才是“第二自我”策略？是在我们具有多种性格特点中，挑选出最适合完成当下任务的性格，并使用这种性格行动起来，直到完成这项工作。\u003c/p>\u003cp>【概念步骤HOW】\u003c/p>\u003cp>具体按照如下四步递进式来做：\u003c/p>\u003cp>1、分析当下任务（处理这项任务需要哪些品质）；\u003c/p>\u003cp>2、回忆自我表现（这些品质自己在哪些不同情景下表现过）\u003c/p>\u003cp>3、创造代表人物（给拥有这些品质的人物起名字，形成第二自我）；\u003c/p>\u003cp>4、投入到角色中（让“第二自我”主宰你的行为直到任务完成）。\u003c/p>\u003cp>【概念难点】这四个步骤大家觉得最难的是哪一步？可能每个人的认为的难点不是完全一致。没关系，下面跟大家分享一个我在学完第二自我策略后是准备如何应用的。\u003c/p>\u003cp>【正确案例】公司刚刚入职一位新员工需要先学习ERP流程，由于这个系统非常复杂，我们都不想在这个问题上消耗时间。如果领导把这件事交办给我，我肯定也不开心，但又不能不去完成。那我就要使用“第二自我”策略来完成了。\u003c/p>\u003cp>首先，分析教给他使用ERP需要哪些特质。耐心、细心、语速慢、不着急。\u003c/p>\u003cp>第二，回忆我曾经出现这些特质的情景。教孩子喊妈妈我可以重复几十次，给客户制作报价单时心细。\u003c/p>\u003cp>第三，我给自己创造一个代表人物“知心姐姐”。\u003c/p>\u003cp>最后，将自己代入到“知心姐姐”的角色中，保质保量的完成这项工作。\u003c/p>\u003cp>【预防异议＋讲解】如果你觉得这样分析人物太麻烦啦，你也可以平日看些动画片，记住性格鲜明的卡通人物。当你需要解决问题时，将最适合的人物召唤出来，想象自己化身为它也可以。只要我们记住在遇到不喜欢又不得不做的事情时，是有多种解决方案的。不要沉浸在坏情绪中，让它拖延我们的时间。\u003c/p>\u003cp>【适用边界】这里大家注意使用第二自我策略一定是你已经确定必须马上要执行而你又不情愿去做的事件。\u003c/p>","interaction":"\u003cp>接下来邀请大家一起来为自己编写一个小剧本。剧本里要求有起因、经过、结果，并且剧情中的人物和对话能够应用到刚刚学到的方法：“第二自我策略”，让不得不做的事情更愉悦的完成。\u003c/p>\u003cp>&nbsp; &nbsp; 剧本是大家未来可能碰到的场景。给到大家五分钟的时间。写到便签上（写摘要即可）。随后我们邀请小伙伴给我们分享一下。\u003c/p>\u003cp>【结束语】感谢熊磊的分享。第二自我策略是在我们不情愿去做某事又不得不做时给出我们正确的选择，使我们从坏情绪中快速抽离，专注高效的完成工作。期望大家今后不让坏情绪拖延我们宝贵的时间。谢谢大家今天的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1531063380000,"updated_at":1531065149000,"ria":true},{"id":5412,"topic":"提高专注力","learn_goal":"TF3-1","remark":"工作和生活中总有一些必须马上去做的事情，但这件事却不是你情愿去做的所以在不得不在时我们总会拖拖拉拉。如何将坏情绪转化，高效率完成任务？","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"月宫","city":"天津市"},"club":{"name":"天津北洋分舵","city":"天津市"},"prologue":"大家好，欢迎大家来到今晚的拆书现场。做个自我介绍，张力珩。三个标签：体验式培训倡导者、国际色彩（服饰）搭配认证师/户外爱好者。稍后我们分为两个小组，通过今天的学习，大家能够解决情绪不好时而无法专注做一件事的问题。\r\n【场景法介绍】\r\n【事件】工作和生活中总有一些必须马上去做的事情，但这件事却不是你情愿去做的。比如，领导要求你去档案室整理文件，但这并不是你职责内的。因为心情不好，所以做起来也拖拖沓沓，无法做到专注。\r\n【提问】之前你遇到这种情况都是怎样处理的？是不是没想到更好的解决办法？\r\n【影响】如果每次遇到这类事情，你总是无法做到专注，那么你会浪费更多的时间来处理，也无法给到领导满意的结果。不仅影响了自己的本职工作，还使得领导对你的工作能力产生质疑。\r\n【解决】这本书中提出的思路比如利用“第二自我”策略在规定时间内完成任何任务，或者利用平均残差绝对值（MAD）策略快速解决进展缓慢或者让人感觉进退两难的项目。你将要体验的，正是这样一条捷径。可以帮你解决问题，甚至你的收获比你想象的要多。","ratings_count":1,"texts":[{"id":8572,"quote":"\u003cp>\u003cstrong>“第二自我”策略是关于决定你的众多性格中哪一条对给定最有效，以及让这一性格进行主导。我把这些性格称作你的“第二自我”。让正确的性格做主，你会发现自己的办事效率变得更高，并且所需承受的压力也会更少，甚至你会觉得做这些事很有乐趣。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你可以在需要对某一情形进行反应时或者计划做某一任务时对“第二自我”进行选择。首先，如果在某些情况下你的反应总是毫无建设性可言，你可以停止做出这种反应，用其他方式进行替代。这么做的一个例子就是在你愤怒的时候，“从一数到十”。在不满情绪不断上升的情况下，这给你时间考虑不满情绪是否真的有用，也给你时间重新进行反应。即使“急性子的你”想要控制场面，你还是可以选择让“坚定而冷静的你”来处理问题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当你准备着手处理一项任务时，这也同样有效。假如你得打扫车库，但你真的不想做这件事。你宁愿四处闲逛，或者看看今天早上刚寄来的杂志。你可能会拖拉着不去打扫车库，或者你可能会强迫自已清理车库，但你还是会想着出去逛逛或者看看书要比这有意思得多。如果你做后者，这项工作很有可能会花费你更多的时间，完成得也很一般，当然也没什么乐趣可言。\u003c/strong>\u003c/p>","explains":"\u003cp>【学习目标】大家跟我学完这个片段后，能够【可观察到的动作】使用第二自我策略解决【具体内容】情绪不好时无法专注完成一件事情的问题。【完成程度】提升效率，快速实现目标。\u003c/p>\u003cp>【类似概念的例子】同事小A平日大大咧咧的，每周上报计划不是有错别字，就是把日期搞混淆了。今天临下班，领导突然着急要一份出差行程单，让小A做好了发给他。小A 知道这事马虎不得，马上不再讲话并在白纸上用尺子认认真真比划着打线。刚画好线格，她为了严谨又跑到财务室，让同事帮忙看看她设计的表格是否可以。到了财务室，发现她的一份合同批复下来了。觉得这个合同可以一起给领导签字，这样会节省领导的时间，所以又领取了合同。 但领回了合同，她又开始担心领导要的是行程单，给他合同会不会又说我没脑子？时间就这样犹豫过去了，最终小A 也没能按时上交一份领导满意的行程单。小A很疑惑，在接到任务后明明也有使用“第二自我”策略啊，但事情为什么还是没办好？因为刻板的压抑自己情绪使得她越来越焦虑。这种情况下能高效的处理好事情么？显然也是不能的。\u003c/p>\u003cp>【类似概念】其实小A就是将“第二自我”策略 的概念搞混淆了。我们常常认为在坏情绪下处理任务只要将自己原有状态“封闭”，展示出另一个自己就可以完成工作，但真正的“第二自我”策略关键点在于“选择”。\u003c/p>\u003cp>【概念提出】那什么才是“第二自我”策略？是在我们具有多种性格特点中，挑选出最适合完成当下任务的性格，并使用这种性格持续到任务完成。\u003c/p>\u003cp>【概念讲解】大家回忆下，我们在不同情境下是否呈现出不同的性格。比如，跟小孩子讲话和我们接到诈骗电话我们的反应一定的不同的。其实我们每个人的性格中都具有霸道总裁的主动快速强势、万人迷的热情积极爱炫、甘地的平和亲切和冷面先生的严谨刻板不苟言笑。当你接到一项你不喜欢完成的任务时，先分析出最适合完成这项任务的角色，然后参照他们的性格特点调动自己，并将自己代入角色，完成“第二自我”策略。\u003c/p>\u003cp>【概念步骤HOW】\u003c/p>\u003cp>具体按照如下四步递进式来做：\u003c/p>\u003cp>1、 分析当下任务（处理这项任务需要哪些品质）；\u003c/p>\u003cp>2、 回忆自我表现（这些品质自己在哪些不同情景下表现过）\u003c/p>\u003cp>3、 创造代表人物（给拥有这些品质的人物起名字，形成第二自我）；\u003c/p>\u003cp>4、 投入到角色中（让“第二自我”主宰你的行为直到任务完成）。\u003c/p>\u003cp>【概念难点】这四个步骤大家觉得最难的是哪一步？\u003c/p>\u003cp>钠老师觉得第一步对她来说最难，因为如果分析不准确就会影响接下来的行动。其他人呢？我们可以带着自己的问题来听我下边的这个例子。\u003c/p>\u003cp>【举出案例】终于周末不加班了可是屋子也必须打扫了，但你真的不想做这件事。你宁愿刷刷朋友圈或出门逛逛书店。你可能会拖拉不去打扫房间，或者你会强迫自己行动起来，但你还是惦念逛逛或者看看书要比这有意思得多。不论怎样这项工作很有可能会花费你更多的时间，完成得也很一般，更别提乐趣了。这时你可以运用“第二自我”策略。\u003c/p>\u003cp>假装你将要雇用别人来帮你做这项工作。你想要这人具备怎样的品质和态度呢？（分析当下任务）这可能包括专注、全心全意、能理智地判断什么该扔掉、有效率、动作快且目的性强。回忆你曾经表现了这所有或大多数品质的时候。（回忆自我表现）这和你手头上这件工作无关。你可以把记忆中不同的事组合起来（比如，你精神完全集中的时候和你非常理性地对待所需处理的事项的时候可能是两件不同的事）\u003c/p>\u003cp>现在闭上双眼让你的记忆进入那种状态，花几分钟来完全投人这种状态中，这会比较有帮助。当你通过这种方式进行感受时，记住你所看到的、你所听到的以及你内心的感受。如果你对此并没有什么很深的印象，用你的想象力创造这些感受。给这个状态的自己取个有意思的名字。（创造代表人物）\u003c/p>\u003cp>然后让“第二自我”来负责，做你需要做的所有事情。如果你发现自己忽然有些分神，那么赶紧打住，立即引导自己进人理想状态。（投入到角色中直到任务完成）\u003c/p>\u003cp>【预防异议＋讲解】如果你觉得这样分析人物太麻烦啦，你也可以平日看些动画片，记住性格鲜明的卡通人物。当你需要解决问题时，将最适合的召唤出来，想象自己化身为它也可以。只要我们记住在遇到不喜欢又不得不做的事情时，是有多种解决方案的。不要沉浸在坏情绪中，让它拖延我们的时间。\u003c/p>\u003cp>【适用边界】这里大家注意使用第二自我策略一定是你已经确定必须马上要执行而你又不情愿去做的事件。\u003c/p>","interaction":"\u003cp>接下来邀请大家一起来为自己编写一个小剧本。剧本里要求有起因、经过、结果，并且剧情中的人物和对话能够应用到刚刚学到的方法：“第二自我策略”，让不得不做的事情更愉悦的完成。\u003c/p>\u003cp>剧本是大家未来可能碰到的场景。给到大家五分钟的时间。写到便签上（写摘要即可）。随后我们邀请小伙伴给我们分享一下。\u003c/p>\u003cp>【给出反馈】\u003c/p>\u003cp>从熊磊的这段自我对话我们就能发现，通过使用“第二自我”策略她很快可以转化不良情绪，积极主动的完成这项工作。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>希望大家在今后的工作生活中，遇到不喜欢做而又不得不马上做的事情，快速使用“第二自我”策略，帮助我们摆脱怀情绪引起的拖拉，告别低效，成就更好的自己！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1530151838000,"updated_at":1530151838000,"ria":true},{"id":4431,"topic":"发现消极行为模式","learn_goal":"发现自己的消极行为模式，并改正拖延这种大部分人都存在的模式","remark":"一直在变换交往对象的小王发现，换来换去，自己身边出现的都是同一类型的人。小李无数次重复陷入资金困境中，因为控制不住自己，她的信用卡总被刷爆。其实，不论是小王还是小李，他们的行为是有一定模式的，是一些消极的行为模式。\r\n我们每个人都难免有些消极行为模式，这些行为模式不断重复出现在我们的生活工作中，拖我们的后腿，并让我们痛苦不堪。 所以，想摆脱这样的痛苦是自然的，也是必须的。让我们来发现这些隐秘模式，并把它们根除吧!","level":"TF3-3","duration":55,"status":30,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是今天的拆书家王蕾，这次的拆页来自《专注力》这本书。\r\n【场景】：今天上午老板交给你一个任务，完成一个20页的项目报告，为了这个艰巨的任务，你把整个下午的时间都空了出来，专门用来写报告。但是在写的过程中，一会儿刷下手机，一下又看下邮件，等下呢又打两个电话，完全没有专注在写报告这件事上。你知道这样的工作方式并不好，但你就是无法做出改变。\r\n【提问】：不知道大家是否留意过自己的一些反复出现的行为，并且留意到它们导致了一些比较不好的结果呢。如何去发现这些较为消极的固定模式，我们应该用怎么样的方法去发现？\r\n【影响】：这些固有的消极模式让你陷入消极的循环中，阻止你做出好的改变。当它们已经变成你的坏习惯时，是很难改正的。也就是说一旦你有了某种消极模式，想要改变是不容易的。\r\n【回答】：本书教给我们发现自己的消极行为模式的方法，带我们发现消极行为模式比如拖延的模式，最后找出解决的方法，从而来提高我们的专注力。","ratings_count":1,"texts":[{"id":7441,"quote":"\u003cp>每个人都有自己的行为模式。当然，一遍一遍做同样的事就自然会一遍遍得到相同的结果。例如，有的人一直在变换交往的对象，但换来换去，他身边出现的都是同一类型的人。人们还总是喜欢重复旧有的方式，即便以前利用这些模式所得出的效果并不理想。所以，这样看来，人们会年复一年地使用低效的甚至无效 时间模式就不足为奇了。\u003c/p>\u003cp>人们通常能够意识到别人的模式，却意识不到自己的模式。如果我们连自己的模式都不清楚，就更别提改变了。一旦我们弄清楚这些模式是什么，那么想要改变就会比较容易了，如此才能改变结果。\u003c/p>\u003cp>模式也可以包括情感、想法影像和行动。比如，你向老板提出涨工资的请求遭到拒绝，你可能会接着想起自己之前遭人拒绝的所有事情。接着，你耳边可能会响起儿时某个曾在你心里留下阴影的成年人的声音，这个声音在说你永远也做不成任何事。接着你脑中可能会浮现出目前你所做的一个项目将来也遭到拒绝的画面，然后你可能觉得摆脱这些消极想法和感觉最好办法就是去酒吧买醉。那是一种灭人志气的消极模式。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>我们本次学习的目标：通过现场RIA学习，能够用询问他人法或演员观众发或记录自己行为法，来找到（行为）你消极的行为模式（界定），至少找到一个消极模式。并针对我们大部分身上都存在的消极行为模式——拖延，学会3个方面的多个方法（行为），至少运用1个方法来缩小现在的A与未来的B之间的差距，从而解决拖延的消极模式（界定）\u003c/p>\u003cp>【\u003cstrong>对比概念\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>这里说的行为模式，而不是行为，因为模式的特性是固定的、重复的，而行为很可能不是这样，它可能是特殊的，没有规律的。\u003c/p>\u003cp>\u003cstrong>【匹配例子】\u003c/strong>\u003cstrong>(\u003c/strong>\u003cstrong>引出逻辑、步骤)\u003c/strong>\u003c/p>\u003cp>&nbsp; 比如你从来不迟到，今天因为地铁出了故障，不得不改变路线，不小心就迟到了，这是行为模式吗？大家回答：不是的\u003cstrong>（互动）\u003c/strong>。那我们一周上班5天，有4天是迟到的，那么迟到已经成为我们固定的行为，这是行为模式吗？大家回答：是的\u003cstrong>（互动）\u003c/strong>\u003c/p>\u003cp>因为行为模式存在重复发生的特征，所以它有据可循，我们只需要找到这些重复的行为，就能从中发现消极模式。上班迟到这件事，大部分人是自己有意识的，你只需要回想下，昨天、前天、大前天这个时候，你上班的画面，就能知道自己是否迟到。\u003c/p>\u003cp>&nbsp; 有些行为自己不容易意识到。我有个同事，一遇到大型的汇报就爱跑洗手间，这个是不是行为模式？大家回答：是的\u003cstrong>（互动）\u003c/strong>。那如果这个人只是偶尔一次出现这个状况，或者只是今天水喝多了，那是不是行为模式？大家回答：不是。是这个行为模式容易被自己发现吗？，大家回答：可能不容易\u003cstrong>（互动）\u003c/strong>。是的，因为你会误以为这只是自己的正常生理需求。在你发现不了的情况下，可以用一个比较笨的方法，就是记录自己的行为，从这些记录中找出重复的消极行为。我们自己发现不了，可以依靠别人去发现，你的朋友就是你行为的见证人。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>刚刚说了，如果是自己能意识到的模式，那么我们可以用回想的方法，这边给大家讲一种比较有趣的回想方法。\u003c/strong>\u003c/p>\u003cp>方法一：\u003cstrong>演员观众法\u003c/strong>。想象自己，你既是一个演员又是一个观众，你在看自己演的电影。作为观众的你不会对你所看到的东西有任何的特殊的感情，不会觉得愧疚、尴尬或者其他感觉。比如你可以平静的回忆曾经已经开始学习但后来又放弃的一种新的技能，仔细回顾并想想到底发生了什么才让你放弃。\u003c/p>\u003cp>\u003cstrong>如果自己比较难意识到自己的模式，那就需要用记录的方法或者让你的朋友帮你去发现\u003c/strong>\u003c/p>\u003cp>方法二：\u003cstrong>记录自己的行为\u003c/strong>。一开始我们说了一个经常会发生在大家身上的场景，今老板交给你一个任务，完成一个20页的项目报告，为了这个艰巨的任务，你把整个下午的时间都空了出来，专门用来写报告。当你真的开始动手做的时候，首先你刷了手机20分钟手机，再花10分钟来浏览了邮件，再给你客户打两个电话，1小时就过去了，在你做每件事情的时候，都一一记录下，记录具体内容，如果你忘记用了多少时间，也可以不记录时间，光记你的行为。记录一周，你基本就能清晰的看到自己的行为模式了。\u003c/p>\u003cp>方法三：\u003cstrong>询问他人。\u003c/strong>虽然我们自己看不到自己的行为模式，但借用别人来看到自己的行为模式。那么找一个你能够信任的，并且和你经常接触的人，让他来叙述下他眼中看到你的行为模式，并把看到的整个行为过程详细的说出来，同时你需要记录下来，你就能得到你的详细行为模式。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>那么如果我发现了自己的模式，就能改掉吗？大家觉得可以吗？\u003cstrong>大家回答：“不是的。”（互动）。\u003c/strong>是的\u003cstrong>，\u003c/strong>并不能改掉，发现了你的行为模式，并不代表就能解决。这只是一个开始，如果想要解决你的行为模式的问题，需要找到你模式背后的真正原因，可能才能解决。本拆页并不能解决行为模式问题。\u003c/p>\u003cp>\u003cstrong>【边界】\u003c/strong>\u003c/p>\u003cp>我们刚刚给出的方法还是有一定的复杂性的，那并不是所以的消极模式都需要我们去花那么多时间和精力，值得我们用这些方法把它找出来。如果你非常容易就能发现你的行为模式，并且能够判断它是消极行为模式，那就不需要用相对复杂的方法去找到它们。\u003c/p>","interaction":"\u003cp>想象下我们现在坐在电影院中，作为观众正在观看者屏幕上播的电影，这个电影就是你自己演的，放的是你这周周一从床上慵懒的起来到这周五晚到家后葛优躺。你看到这周你做的所有的事，你心里所有的想法，看电影的过程中你渐渐发现自己的行为模式。给大家3分钟时间，仔细回顾下，写出具体发生的事情，找到自己的模式，然后分享。\u003c/p>\u003cp>分享者1：我看到我这一周以及以前几周经常出现的情况是，每周都会制定很多的计划。\u003c/p>\u003cp>\u003cstrong>拆书家反馈：具体能说说看是哪种计划吗？（对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈）\u003c/strong>\u003c/p>\u003cp>分享者继续：比如说我制定了一周健身3次，每天看书1小时，每天6点起床学习，我的计划的确是这样制定的，但是基本都没有完成，然后内心会开始自责，心里会想，我这样下去怎么可能成为更厉害的人呢，然后情绪会不好。\u003c/p>\u003cp>拆书家点评：我们来看下小伙伴刚刚说的这个例子，不单单是一种模式，它包括了行为方面的和情感方面的，行为方面的是常常定计划但却没有去执行这些计划，情感模式是你每次只要没有完成计划，你就会出现消极的情绪。\u003c/p>\u003cp>【\u003cstrong>A2催化应用\u003c/strong>】（布置作业）\u003cstrong>\u003c/strong>\u003c/p>\u003cp>在这里给大家布置一个小作业，完成现场学习后，在这个月中，希望大家运用这三个方法中的任意一个或几个，去发现自己的行为模式，包括行为方面、情感方面的，并且呢，给我反馈，说说你是如何发现的，详细讲解下你整个行为过程。\u003c/p>\u003cp>学习者2，3天后反馈：我这几天用了自己记录自己行为的方法，发现自己有倾向于做简单的事，而不是让自己有所成长的、有挑战的事的模式。具体事情，每天需要制作数据表格，表格数据计算每次会用到的计算公式不太一样，有的难有的简单，我周一上午上班问数据组的同事要来数据后，我会把我会算的数据填上，然后把表交给我同事，她完成较难的部分。这不是我们提前分配了说谁做哪一部分，我是自己把简单的分配给自己，她也没有说什么，每天的数据表格我基本都是这样去处理。在写项目报告中也是，我会把报告简单的部分写完，剩下的交给同事处理。我就渐渐养成了处理简单事情的行为模式，而不是去做提高自己的事。这些都导致我工作一年来，工作能力没有进步，只会处理简单事务。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【过渡段】（体现\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>个拆页之间的逻辑关系）\u003c/strong>\u003c/p>\u003cp>&nbsp;既然发现了自己的消极行为模式，那必然会想去解决它。大部分人运用以上方法都能找到自己存在的一个消极的行为模式——拖延模式，接下来就来一起解决拖延这个消极行为模式。（过渡段时间分配在拆页2中）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":7443,"quote":"\u003cp>要了解拖延的动力学，让我们来看看诱惑是怎么奏效的。通常情况下，你需要从两个或更多事情中作选择。有时这是个简单的“是与否”的选择：你是否应该吃这块巧克力蛋糕？有时这是几项活动中的一个选择：你将要在家看电视还是去健身房运动？什么在左右着你的决定？\u003c/p>\u003cp>处在向某方向运动的人（比如，享用一顿丰盛的晚餐）将倾向于继续此方向上的运动（吃一大块巧克力蛋糕作为甜点）。所以，为了改变方向，我们需要作出努力。但为什么做这件事会这么难呢？\u003c/p>\u003cp>一个原因就是“错误”的选项当下显得非常有吸引力，“正确”选项的吸引力（或者忽视正确选项的惩罚）在当下显得很弱，它的吸引力要长期才能体现出来。关键问题是：通常而言，“正确”选项在长期可能给我们带来回报。“错误”选项的回报则是立竿见影的。因此，“错误”选项的吸引力会比较强。\u003c/p>\u003cp>举个例子，假设接下来我选择花几个小时浏览网页，这马上能给我带来欢乐。可能我确实应该写那份两个礼拜后就该交的报告，不过就算我现在不做报告，即刻也不会有什么惩罚或者不利情况出现。一个礼拜后我受到了惩罚，当我意识到自己已经无可救药地远远落在别人后面；或者两个礼拜后，我错过截止日期，客户对我大发雷霆。\u003c/p>\u003cp>还有另外一个关键的不同，短期选择常常含有我们强烈的感觉和情感，而长期选择因为并不在眼前，只是和我们智慧相关。\u003c/p>\u003cp>巧克力蛋糕看起来很棒，闻起来很香，舌尖上的感觉很柔滑细腻，味道好极了！保持身材的办法……呃，嗯，这是个很好的想法……有的时候，比如我们满怀深深的愧疚，这确实有点效果。但不幸的是，这种事情通常只在我们过分放任自己的情况下才会出现。\u003c/p>","explains":"\u003cp>\u003cstrong>【量表】\u003c/strong>\u003cstrong>(\u003c/strong>\u003cstrong>由于讲解需要，量表放在的I讲解之前进行)\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.对于不喜欢的事情，我总是拖后做\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.我总是不按照承诺的期限来完成任务\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我总是会在最后期限来临前才开始动手完成任务&nbsp;&nbsp;\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.我总是在开始动手完成任务时，被其他人事物吸引，而延迟完成任务\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.我总是认为今天没有执行的事情可以明天再完成，导致事情一直没有开始执行\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>量表解释\u003c/strong>：1分代表极少发生这样的事，6分代表总是发生这样的事。大家计算下分数，这个量表可以反映出大家的拖延情况，分数越高说明你的拖延模式越严重，总分在6分以下表明你很少会拖延，22分以上表明你比较严重。不过不用担心，我们接下来会一起来解决这个消极模式。\u003c/p>\u003cp>【I讲解】\u003c/p>\u003cp>拆页中的拖延是许多拖延中的一种，是应该选当下错误的A，还是未来正确的B。大家可以回忆下，拆页中的情境是在写报告，大家在遇到这个情境的时候，是会选择做当下的A，还是未来的B相？大家回答：“选A”\u003cstrong>（互动）\u003c/strong>。\u003c/p>\u003cp>拆页给了我们两个原因，一是选择错误的A在当下就能得到好处，正确的B在久远的未来才能有好处，A比较有吸引力。第二个原因，A就在眼前，你看着它、感受它，它美啊、好吃啊，令我心情愉悦，你当下产生的这种强烈情感促使你更倾向于选择当下的A。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3微行动学习】\u003c/strong>\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家选现在的A，不选未来的B，是因为A比B吸引力更大，\u003c/strong>A比B产生更多情感，\u003cstrong>那么当下的\u003c/strong>A吸引力大于B、\u003cstrong>当下的\u003c/strong>A比B产生更多情感的本质是什么呢？大家注意结合自己生活中的经历，通过一些具体的例子追问问题本质。\u003cstrong>可以先把结果记录在纸上。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003c/strong>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>引导讨论本质\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>分享者2：是反馈的快慢造成的，人们倾向于当下就能有结果的事情，类似我们平时玩的游戏中的即时反馈\u003c/p>\u003cp>分享者3：是画面感造成的，A会让人脑海里产生画面感，让大家不怎么有理智，使非理性代替理性\u003c/p>\u003cp>分享者1：是否能在当下获益， A短时间内获得收益，在当下做A比做B要获益多，长久的话肯定是B，比如运动，长久来说肯定运动有很大好处，但是在当下不会产生明显好处。\u003c/p>\u003cp>其他小组认同吗？大家回答：认同\u003c/p>\u003cp>通过大家的讨论，\u003cstrong>那么当下的\u003c/strong>A吸引力大于B、\u003cstrong>当下的\u003c/strong>A比B产生更多情感的本质概括为3点：\u003c/p>\u003cp>1.是否能即时反馈&nbsp;&nbsp;\u003c/p>\u003cp>2.画面感是否强烈\u003c/p>\u003cp>3.是否当下获益和获益多少\u003c/p>\u003cp>【引导讨论解决方案】\u003c/p>\u003cp>\u003cstrong>根据刚刚说的本质，我们如\u003c/strong>\u003cstrong>何使当下的\u003c/strong>A吸引力小于未来B、A\u003cstrong>比B产\u003c/strong>\u003cstrong>生更少的情感，从而能够让我们在选择的时候会选择做未来的B,就能解决拖延的消极模式了。我们分成3组，给大家5分钟时间，大家可以把讨论出的可行的思路先记在纸上\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>代表分享\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>下面请小伙伴分享下\u003c/p>\u003cp>讨论\u003cstrong>当下收益本质\u003c/strong>的分享者：\u003c/p>\u003cp>1.分享者5：\u003c/p>\u003cp>对应当下获益的本质，可以减少A的获益，去想想当下A的坏处，比如你看到这个蛋糕时，去想想蛋糕里有多少卡路里，要花多少时间去消耗这个卡路里，你可能就不想吃了。\u003c/p>\u003cp>2.分享者6：\u003c/p>\u003cp>对应当下获益的本质，用奖励来增加未来B的当下的收益。我需要做项目报告，项目报告本身没有特别的收益，但是往往在做的时候会想要去看小说，做一些我当下就能得到好处的事情。\u003c/p>\u003cp>拆书家反馈：那对于你来说你会设置怎样的奖励呢？（对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈）\u003c/p>\u003cp>分享者6继续回答：我能想到的比较大的奖励是去日本游学2个周。如果我能顺利把这个项目结项，我想我可以奖励自己去日本游学2周。\u003c/p>\u003cp>讨论\u003cstrong>即时反馈本质\u003c/strong>的分享者：\u003c/p>\u003cp>3.分享者1：\u003c/p>\u003cp>对应当下反馈本质，可以去增加未来B的当下反馈，可以模仿游戏，给自己设置打分机制，比如今天做了运动给自己加10分，没有做到的话给自己扣10分，每个重要事项都可以这样。如果一周下来你的分数很高，你可以给自己奖励。分数很低，可以给自己惩罚。\u003c/p>\u003cp>4.分享者4：\u003c/p>\u003cp>对应当下反馈本质，增加B的反馈，给未来的B找导师，导师会给即时你反馈，并且鼓励你鞭策你。也可以找朋友或者团体来监督你、督促你，这些都能在当下得到反馈。\u003c/p>\u003cp>讨论\u003cstrong>画面感本质\u003c/strong>的分享者：\u003c/p>\u003cp>5.分享者2：\u003c/p>\u003cp>对应画面感本质，我们可以增加未来B的画面感，比如贴你希望成为的样子的照片，或者想象你希望成为的样子的具体画面，类似电影画面那样，让我们想到B就能产生美好的画面。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>拆书家概括\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>大家分别对本质的三个方面进行了讨论，解决方法有：\u003c/p>\u003cp>\u003cstrong>1.当下收益：\u003c/strong>\u003c/p>\u003cp>减少A的收益：想A有哪些坏处 &nbsp; &nbsp; 增加B的收益：给B设置奖励\u003c/p>\u003cp>\u003cstrong>2.即时反馈\u003c/strong>\u003c/p>\u003cp>增加B的反馈：打分机制；找导师指导你，找团体、找朋友督促你\u003c/p>\u003cp>\u003cstrong>3.画面感\u003c/strong>\u003c/p>\u003cp>增加B的画面感：想象具体画面；找到对应的照片、画面，贴在墙上\u003c/p>\u003cp>\u003cstrong>【A2编剧本】\u003c/strong>\u003c/p>\u003cp>下面请大家给自己编一个剧本，剧本的情节是你又开始拖延了，可能是拖延老板交代给你50页的ppt任务，又去刷手机了。可能是拖延你另一半让你每周末打扫卫生，又去打游戏了。先描述下你拖延的具体情况，要求有情节、有对话。最后你小宇宙爆发了，用我们刚刚讨论出来的方法，达到解决消极模式拖延的目的，具体说下你在故事中用了哪些方法来解决的。请大家根据上面的要求给自己编一个剧本。\u003c/p>\u003cp>分享者5：在未来我可能拖延的情况是，我晚上刷今日头条的时候，不自主的沉迷其中，忘记了听微课学习。根据我们刚刚对应当下反馈本质，提出的找他人来监督我的方法，来增加反馈，我可以找我妈来提醒我，我可以跟她说：“我微课7点半开始，妈，到7点半还看见我在刷手机，你就严厉点训下我”，然后妈就会在那个时间点看到我还在刷今日头条：“时间到了，你怎么还没有开始听课！！！”，然后我就会把头条给关掉，就开始听课。\u003c/p>\u003cp>分享者2：到了下周，我又开始拖延，拖延的事情将会是泡脚，我会在准备泡脚之前想我要不先做些其他事情吧，坐在桌前面我就开始准备拆页这些拆书帮的事情了。这时候可以想象一个美人出浴的画面，你的脚泡在花瓣浴里面，好养生啊，想象那个热量从脚底直灌到丹田，这种画面给我强烈鼓动，我会想我就是要做这样健康、养生的人。然后呢我就很愉快的去泡脚了。\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：也可以从电视剧中截取一段视频，就放美人出浴的那段，然后就觉得自己要是泡了脚也会像她一样美美哒。\u003c/p>\u003cp>分享者3：关于泡脚我有些心得，泡脚真的是有利我们身体的，我就经常泡脚\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：的确泡脚对我们的健康是件重要的事情，大家都有很多心得体会，我们拆页结束后可以来深入讨论。（对学习者的分享和提问，有体现通过向学习者提问来进行回应式反馈）\u003c/p>\u003cp>\u003cstrong>总结\u003c/strong>：\u003c/p>\u003cp>那么今天第一个拆页是发现自己的行为模式，运用发现消极行为模式的方法，我们能够发现自己可能存在的一个模式是拖延，第二个拆页针对拖延的模式，来给出解决方法。希望这两招能让大家在生活和工作中更加专注，今天我的拆书就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1515467808000,"updated_at":1515550692000,"ria":true},{"id":4113,"topic":"一分钟战胜专注障碍","learn_goal":"让学习者掌握克服专注于重要任务的方法，学会行动的具体步骤","remark":"你有没有过这样的体验，有一个重要的任务要求限时完成，而你却拖到最后一刻才匆匆开始？只需花费半小时的活动，却迟迟没有行动？如何不费吃灰之力战胜专注的障碍，成为出色的即刻行动者？让我们一起来拆书现场寻找答案吧！","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"蘭梅","city":"株洲"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位爱阅读爱拆书的小伙伴们，晚上好！很荣幸今天能与大家一起参与我们株洲幸福分舵的拆书认证，下面我先用三个标签介绍一下我自己：我的第一个标签—一位爱孩子的妈妈，第二个标签—一位热爱工作的企业高级人力资源师，第三个标签—一个爱自已的二级心理咨询师。为了更好的扮演这些角色，我坚定地选择了阅读和拆书，期待把所学的知识拆解成自己的能力！\r\n第一次听说“拆书帮”这个名词是在去年年底，之后我便阅读了《这样读书就够了》，今年三月我有幸参加了“拆书帮联合训练营”，自此我对拆书帮有了更深入的认识：\r\n拆书，是一种将知识拆为己用的学习方法。是通过对书本进行阅读、筛选，将对自己有启发的知识片段与自己的经验关联起来，然后通过反思和整理，形成适合自己的行动方案，最后进行体验-反思-再体验的螺旋式学习。拆书学习方法的途径有三种：RIA便签法、拆书帮俱乐部和拆书帮现场学习。\r\n拆书帮，是一个社群，一个开放的学习型组织，在全国各地以分舵的形式存在。这是一个互相尊重、互相支持、轻松愉悦的学习社群。拆书帮的成员都是爱学习、爱家人、爱朋友的充满活力一族。“教是最好的学”，我们一起来感受这场过级“打小怪兽游戏”吧！\r\n下面","ratings_count":0,"texts":[{"id":7085,"quote":"\u003cp>一项过于庞大的任务会让人望而却步、心生不悦。要完成这种任务，秘决是把任务分解成易于完成的子任务。要持续不断地对任务进行分解，直到这些子任务都很容易完成，直到你不再惧怕面对这些任务。举个例子，你不得不打电话解雇你的网站开发工程师。你知道这不是什么令人愉快的差事，于是你就一直没打这个电话。但这么做有个问题，那就是原本的工程师只要还在位，你就没办法雇用新员工，这使得网站信息的更新受到延误，而网站信息的滞后直接限制了网站盈利收入的增加。这种“捡了芝麻，丢了西瓜”的现象非常普遍。首先，检查这项任务是不是可有可无？不是。第二，这项任务是否可以委派他人完成？有可能，但如果没法分配给其他人，那么你可以把打电话这件事情分解成以下步骤：\u003c/p>\u003cp>&amp; 找到这个人的电话号码，记录下来。\u003c/p>\u003cp>&amp; 写下你想要说的话以及你将怎样说这些话。\u003c/p>\u003cp>&amp;做好最坏的打算。在这种情况下，这可能是对方非常情绪化的或者非常敌对的反应，那么你可以准备好说这样一些话，比如：“很抱歉这件事情让你如此烦恼，我会给你发一个书面声明，表明我们之间的合同将不再生效。”如果这听起来好像整个事情即将变成一个法律问题，告诉对方剩下的事情将由你的律师出面解决。大多数情况下，这种最坏的情形并不会出现。\u003c/p>\u003cp>&amp;现在不要去想这个任务会怎样，而是想想结果会怎样。一旦你打完这个电话，你将会感觉多么轻松？不用再为这件事情感到烦恼将会多美好？用这种积极的预期激励你完成这项任务。\u003c/p>","explains":"\u003cp>原文片断主题是“如何克服专注障碍”，它阐述了如何克服自身的障碍，去专注于所做事情中最关键的20%。这个秘决就是：先把任务分解成一个个易于完成的子任务，这些分解后的任务看起来非常简单，我们对完成它有信心有动力，因而我们能够非常迅速地去行动。片断例举了一个关于“解雇你的网站开发工程师”的故事，因为“一直没打这个电话”，导致事情影响起来越大，最后通过分析，归纳了克服问题的三个步骤：\u003c/p>\u003cp>1． 评估这项任务是不是必须完成的；\u003c/p>\u003cp>2． 这项任务是否可以委派他人；\u003c/p>\u003cp>3． 把这项任务分解成最简单的几个子任务；\u003c/p>\u003cp>4． 用积极的预期即刻行动：迈出任务的第一步。\u003c/p>","interaction":"\u003cp>记得两周前，我提前一天预约好了第二天的面试工作，一大早我来到办公室处理邮件和其他事务，准备10点去参加面试，9点50分接到上级的电话，说转发一个紧急邮件给我，需要在12点前提交一个重要方案。我当时懵了，心里想：两个小时怎么可能完成这么复杂的方案，简直不可能，太没有计划性了！我当时就回复说上午已有面试安排，这个方案两小时是不够的！可是上级并没有接受我的建议，只是强调这项工作的重要性。我只好硬着头皮做接下来的事，内心非常地焦虑。当我打开邮件仔细阅读的时候，我发现任务不是我想象的那样，方案很简单，只不过是三张表格和几点说明而已。于是我协调好面试安排并委托下属处理，然后开始处理那项紧急工作……\u003c/p>\u003cp>通过这个片段的学习，在以后的工作和生活中，当我再遇到重要而又非常有压力的任务时，我可以不用再紧张不安，而是淡定的这样去处理：\u003c/p>\u003cp>1.评估: 尽可能获取完整的准确的信息，判断任务是不是必须做的；\u003c/p>\u003cp>2.借力：这项任务是否可以借助外部资源，如：委派他人、寻找助手、求助等；\u003c/p>\u003cp>3.分解：把这项任务分解成几个子任务，并分解成最简单的几个实施步骤；\u003c/p>\u003cp>4.行动：把预设问题考虑好，接下来积极的迈出第一步。\u003c/p>\u003cp>这个方法听起来很简单，但确实是一个让你立刻行动起来的好方法，良好的开端，是成功的一半。下次遇到复杂或棘手的任务时，我们不妨来试一试！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1511828904000,"updated_at":1511829162000,"ria":true},{"id":3910,"topic":"消极行为模式","learn_goal":"学会发现自己的小鸡行为模式","remark":"","level":"TF3-3","duration":55,"status":0,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好我是王蕾，今天给大家带来的拆页是来自《专注力》这本书。大家有没有这样的经历\r\n【场景】：今天上午老板交给你一个任务，完成一个20页的项目报告，为了这个艰巨的任务，你把整个下午的时间都空了出来，专门用来写报告。但是在写的过程中，一会儿刷下手机，一下又看下邮件，等下呢又打两个电话，完全没有专注在写报告这件事上。你知道这样的工作方式并不好，但你就是无法做出改变。\r\n【提问】：所以不知道大家是否留意过自己的一些反复出现的行为，是否留意到它们导致了一些比较不好的结果。如何去发现这些较为消极的固定做法和想法呢？\r\n【影响】：这些固有的模式让你陷入消极的循环，阻止你做出好的改变。当它们已经变成你的坏习惯时，是很难改正的。\r\n【回答】：本书教给我们发现自己的行为模式，从中找到会拖你后腿的模式。比如拖延等，最后找出战胜它的方法，从而来提高我们的专注力。","ratings_count":0,"texts":[{"id":6852,"quote":"\u003cp>每个人都有自己的行为模式。当然，一遍一遍做同样的事就自然会一遍遍得到相同的结果。例如，有的人一直在变换交往的对象，但换来换去，他身边出现的都是同一类型的人。人们还总是喜欢重复旧有的方式，即便以前利用这些模式所得出的效果并不理想。所以，这样看来，人们会年复一年地使用低效的甚至无效 时间模式就不足为奇了。\u003c/p>\u003cp>人们通常能够意识到别人的模式，却意识不到自己的模式。如果我们连自己的模式都不清楚，就更别提改变了。一旦我们弄清楚这些模式是什么，那么想要改变就会比较容易了，如此才能改变结果。\u003c/p>\u003cp>模式也可以包括情感、想法影像和行动。比如，你向老板提出涨工资的请求遭到拒绝，你可能会接着想起自己之前遭人拒绝的所有事情。接着，你耳边可能会响起儿时某个曾在你心里留下阴影的成年人的声音，这个声音在说你永远也做不成任何事。接着你脑中可能会浮现出目前你所做的一个项目将来也遭到拒绝的画面，然后你可能觉得摆脱这些消极想法和感觉最好办法就是去酒吧买醉。那是一种灭人志气的消极模式。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>我们本次学习的目标：通过现场RIA学习，能够用询问他人法或演员观众发或记录自己行为法，来找到（行为）你消极的行为模式（界定）。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>我们的行为模式是影响专注力的重要一环，比如说拖延的行为模式，它会使我在计划的时间内专注力受到严重的影响，导致不能按时完成任务。\u003c/p>\u003cp>【\u003cstrong>对比概念】\u003c/strong>\u003c/p>\u003cp>这里说的行为模式，而不是行为，因为模式的特性是固定的、重复的，而行为很可能不是这样，它可能是特殊的，没有规律的。我们学习这个拆页是为了找到我们的消极的哪些模式\u003c/p>\u003cp>\u003cstrong>【匹配例子\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>我们其实存在很多固有的行为模式，都会削减或者分散我们的注意力，除了行为外，也包括非行为类的，比如就是最后一段的例子，是偏情感和想法方面的。情感或者想法类的模式是指只要发生相同类型的事情，事后你的想法或情感基本是固定的，很多时候这个想法或情感基本是消极的。也有可能是想法、行为等混合的模式\u003c/p>\u003cp>比如我一旦被别人批评，我就会浮想联翩，我会想起以前也是被批评的各种场景。然后开始陷入深深回忆，想到了那是一个周五的灰蒙蒙的早上，外面下着小雨，我搞砸了一个重要的项目汇报，结果被老板当着所以同事的面骂了一顿，还降了我的薪水。这种联系过往和悲伤的情感是我固定的模式，属于想法和情感类。为了不再难过，我粗暴的用暴饮暴食来解决。以后一旦被批评，我就开始心情低落，暴饮暴食。暴饮暴食是消极的行为模式\u003c/p>\u003cp>\u003cstrong>【预防异议\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>那么如果我发现了自己的模式，就能改掉吗？大家觉得可以吗？\u003cstrong>大家回答：“不是的。”（互动）。\u003c/strong>是的\u003cstrong>，\u003c/strong>并不能改掉，发现了你的行为模式，并不代表就能解决。这只是一个开始，如果想要解决你的行为模式的问题，需要找到你模式背后的真正原因，可能才能解决。本拆页并不能解决行为模式问题。\u003c/p>\u003cp>\u003cstrong>【边界\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>并不是所以模式都需要引起我们注意，值得我们用一些方法把它找出来。如果你非常容易判断，这个模式是一个积极的模式而非消极模式，那可以跳过这些行为、想法和情感，没有必要也用我接下来会讲的这些方法，对模式进行记录。\u003c/p>\u003cp>\u003cstrong>【HOW\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>(引出逻辑、步骤)\u003c/strong>\u003c/strong>\u003c/p>\u003cp>那怎么样才能发现自己的行为模式呢？下面给大家三个方法。\u003c/p>\u003cp>方法一：\u003cstrong>询问他人。\u003c/strong>虽然我们自己看不到自己的行为模式，但借用别人来看到自己的行为模式。那么找一个你能够信任的，并且和你经常接触的人，让他来叙述下他眼中看到你的行为模式，并把看到的整个行为过程详细的说出来，同时你需要记录下来，你就能得到你的详细行为模式。\u003c/p>\u003cp>方法二：\u003cstrong>演员观众法\u003c/strong>。想象自己，你既是一个演员又是一个观众，你在看自己演的电影。作为观众的你不会对你所看到的东西有任何的特殊的感情，不会觉得愧疚、尴尬或者其他感觉。比如你可以平静的回忆曾经已经开始学习但后来又放弃的一种新的技能，仔细回顾并想想到底发生了什么才让你放弃。\u003c/p>\u003cp>方法三：\u003cstrong>记录自己的行为\u003c/strong>。比如，假设你计划周六在家完成一份报告。结果是直到中午，你都没能开始写这份报告。可能你起床后发现家里的脏衣服已经堆积如山。你决定把衣服放进洗衣机然后再来写报告。放入后你准备在书桌前坐下，开始你的报告写作，这时一个朋友给你打电话。你非常难过，需要有人安慰她，于是你花了一个小时倾听她悲伤爱情故事。后来你饿了，给自己做了份午餐，因为在你饿的时候，你肯定没法写好报告……，在你出现这些情况的同时，把自己做的每件事都记录下，你就能清晰的看到自己的行为模式了。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>想象下我们现在坐在电影院中，作为观众正在观看者屏幕上播的电影，这个电影就是你自己演的，放的是你这周周一从床上慵懒的起来到这周五晚到家后葛优躺。你看到这周你做的所有的事，你心里所有的想法，看电影的过程中你渐渐发现自己的行为模式。\u003c/p>\u003cp>给大家3分钟时间，仔细回顾下，写出具体发生的事情，找到自己的模式，然后分享。\u003c/p>\u003cp>\u003cstrong>学习者1\u003c/strong>：如果周末报名了拆书，我就会有拖延。（\u003cstrong>拆书家反馈：“你可以描述下详细的拖延状况。”）\u003c/strong>我觉得我的安排是星期一晚上就要准备稿子，这样我就比较有信心，到拆的前一天就不会焦虑了。那下班以后，觉得星期一还早，明天准备也可以的。到星期三的时候我就会想我前两天为什么会拖延，我其实不是再考虑拆书的事情了，而是在考虑拖延的事情，然后我就开始想内心的冲突点1、2、3、4，可是我自己根本解决不了，因为不知道这些冲突是为什么。到了星期四、星期五，我还是会为了这些冲突而郁闷，然后我心里就对拆书产生了抵触。但下次其实我还是会报名，但是还是会有这样一个循环。\u003c/p>\u003cp>拆书家点评：其实我们可以看到刚刚说的这里例子是行为和想法的模式共同存在的，因为她一直在考虑自己的矛盾点以及自己的行为是周一并没有去执行计划。\u003c/p>\u003cp>\u003cstrong>【布置作业\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>在这里给大家布置一个小作业，完成现场学习后，在这个月中，希望大家运用这三个方法中的任意一个或几个，去发现自己的行为模式，包括行为方面、情感方面的，并且呢，给我反馈，说说你是如何发现的，详细讲解下你整个行为过程。\u003c/p>\u003cp>\u003cstrong>学习者2一周后反馈\u003c/strong>：我这周用了自己记录自己行为的方法，发现自己有倾向于做简单的事，而不是做让自己有所成长的、有挑战的事的模式。具体事情，每周五都需要交这一周做的数据表格，表格数据计算每次会用到的计算公式不太一样，有的难有的简单，我周二问数据组的同事要来数据后，我会把我会算的数据填上，然后把表交给我同事，她完成较难的部分。这不是我们提前分配了说谁做哪一部分，我是自己把简单的分配给自己，她也没有说什么。在写项目报告中也是，我会把报告简单的部分写完，剩下的交给同事处理。我就渐渐养成了处理简单事情的行为模式，而不是去做提高自己的事。\u003c/p>\u003cp>\u003cstrong>过渡段：\u003c/strong>发现行为模式只是一个开始，那么接下去就来帮大家改变一个大众普遍存在的行为模式，那就是拖延。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":6853,"quote":"\u003cp>要了解拖延的动力学，让我们来看看诱惑是怎么奏效的。通常情况下，你需要从两个或更多事情中作选择。有时这是个简单的“是与否”的选择：你是否应该吃这块巧克力蛋糕？有时这是几项活动中的一个选择：你将要在家看电视还是去健身房运动？什么在左右着你的决定？\u003c/p>\u003cp>处在向某方向运动的人（比如，享用一顿丰盛的晚餐）将倾向于继续此方向上的运动（吃一大块巧克力蛋糕作为甜点）。所以，为了改变方向，我们需要作出努力。但为什么做这件事会这么难呢？\u003c/p>\u003cp>一个原因就是“错误”的选项当下显得非常有吸引力，“正确”选项的吸引力（或者忽视正确选项的惩罚）在当下显得很弱，它的吸引力要长期才能体现出来。关键问题是：通常而言，“正确”选项在长期可能给我们带来回报。“错误”选项的回报则是立竿见影的。因此，“错误”选项的吸引力会比较强。\u003c/p>\u003cp>举个例子，假设接下来我选择花几个小时浏览网页，这马上能给我带来欢乐。可能我确实应该写那份两个礼拜后就该交的报告，不过就算我现在不做报告，即刻也不会有什么惩罚或者不利情况出现。一个礼拜后我受到了惩罚，当我意识到自己已经无可救药地远远落在别人后面；或者两个礼拜后，我错过截止日期，客户对我大发雷霆。\u003c/p>\u003cp>还有另外一个关键的不同，短期选择常常含有我们强烈的感觉和情感，而长期选择因为并不在眼前，只是和我们智慧相关。\u003c/p>\u003cp>巧克力蛋糕看起来很棒，闻起来很香，舌尖上的感觉很柔滑细腻，味道好极了！保持身材的办法……呃，嗯，这是个很好的想法……有的时候，比如我们满怀深深的愧疚，这确实有点效果。但不幸的是，这种事情通常只在我们过分放任自己的情况下才会出现。\u003c/p>","explains":"\u003cp>【量表】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.对于不喜欢的事情，我总是拖后做\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.我总是不按照承诺的期限来完成任务\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我总是会在最后期限来临前才开始动手完成任务&nbsp;&nbsp; \u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.我总是在开始动手完成任务时，被其他人事物吸引，而延迟完成任务\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.我总是认为今天没有执行的事情可以明天再完成，导致事情一直没有开始执行\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>量表解释\u003c/strong>：1分代表极少发生这样的事，6分代表总是发生这样的事。大家计算下分数，这个量表可以反映出大家的拖延情况，分数越高说明你的拖延症越严重，总分在6分以下表明你很少会拖延，22分以上表明你拖延严重。拖延重症患者的也不用担心，我们接下来会一起来解决这个问题。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>学习目标：通过本次现场学习后，通过大家微行动学习得出的解决方法来解决你自己的拖延症问题。\u003c/p>\u003cp>拆页中的拖延是许多拖延中的一种，是应该选当下错误的A，还是未来正确的B。大家可以回忆下，拆页中的情境是在写报告，大家在遇到这个情境的时候，是会选择做当下的A，还是未来的B相？大家回答：“选A”\u003cstrong>（互动）\u003c/strong>。大家看完拆页能不能归纳下自己为什么会选当下的A？拆页是有明确说到原因的。学习者1回答：“即时反馈”，学习者2回答：“你现在去做当下的，就马上会得到欢乐。但是你不去做计划的那件事情，也不会有什么惩罚。”\u003cstrong>（互动）\u003c/strong>\u003c/p>\u003cp>拆页给了我们两个原因，一是选择错误的A在当下就能得到好处，正确的B在久远的未来才能有好处，A比较有吸引力。第二个原因，A就在眼前，你看着它、感受它，它美啊、好吃啊，令我心情愉悦，你当下产生的这种强烈情感促使你更倾向于选择当下的A。未来的B太久远，画面感太弱了，你的感受就没有那么强烈。我在详细解释下这是什么样的一种情感，我们一般用身体器官去感受外界事物，眼耳鼻舌身，看着好看、听着好听、闻着好闻、吃着好吃、摸起来舒服，那这个时候我们就会产生爽的感觉，这种情感就是就是拆页当中所说的情感强烈。\u003c/p>\u003cp>【本质】\u003c/p>\u003cp>简单来说当下的A和未来的B之间的本质区别是就是A能够马上能得到好处，但是B不能，所以A的吸引力比较强，B的吸引力比较弱。当下的A能够让我们得到强烈的情感，B不能产生强烈的情感。你拖延的问题，\u003cstrong>本质\u003c/strong>就在于，你选了吸引力大的和情感强烈的选项。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>那么请大家小组内分享下，你生活中、工作中的哪些拖延是符合我刚刚讲的这个本质的，而后选择了当下的A。\u003c/p>\u003cp>\u003cstrong>学习者1\u003c/strong>：我一般晚上十点半睡觉，但是我晚上看书，看书很愉悦嘛，就会拖延到十一点半才睡（当下使产生强烈情感的A），就导致了第二天早上起不来。（拆书家反馈：具体说下你本来第二天早上是准备干嘛的）本来是计划第二天早上运动半小时，然后做早饭（明早吸引力较弱、无强烈情感的B）。起晚后没时间运动了，只能做早饭。\u003c/p>\u003cp>\u003cstrong>学习者3\u003c/strong>：一直打算追门公开课（吸引力较弱、无强烈情感的B），一下班，一打开电脑，就开始玩微博、看看足球消息、看小说、看电视剧，一下子就到睡觉的时间12点了（当下有吸引力、使产生强烈情感的A），到现在我都还是这样，公开课也没有追完。\u003c/p>\u003cp>【A3微行动学习】\u003c/p>\u003cp>根据刚刚说的本质，我们能想到哪些办法来解决拖延的行为？我们分成4组，两组来讨论A的情况，两组来讨论B的情况\u003c/p>\u003cp>\u003cstrong>学习者3分享\u003c/strong>：\u003c/p>\u003cp>对未来的B：\u003c/p>\u003cp>1.增加B吸引力：如果要按时完成任务，我们会把它分成比如说20个小任务，但一般情况下不知不觉会去看电视剧（\u003cstrong>拆书家反馈\u003c/strong>：那么你们想到的解决的办法是什么？）我会把这20个任务分配在一个月的不同的时间。按天来算，周一到周五如果每天能完成1个任务，那么周六周日能够休息、看剧。我把这个周六周日能够休息、看剧当作是一个奖励，这样就会让周一到周五的任务变得有吸引力。刚刚说的是周奖励，还可以设置月奖励，如果我这个月完成了任务的80%，我会和我妈商量说，给我奖励一个ipad。\u003c/p>\u003cp>2.增加对B的情感：如果你想好好学习，贴个男学霸的照片在墙上，或者是把戴博士帽的学霸的脸P成是自己的脸，这样就有一种视觉化的效果，就能增强对好好学习的向往之情。\u003c/p>\u003cp>\u003cstrong>学习者4分享\u003c/strong>\u003c/p>\u003cp>对现在的A：\u003c/p>\u003cp>1.减少A吸引力：提前给自己制定惩罚机制。如果忘记了惩罚怎么办呢，我们会列一个清单，把自己要惩罚自己的事情贴在墙上，随处可以看到，比如惩罚自己回到家1个星期不能刷网站。\u003c/p>\u003cp>2.减少对A的情感：贴一张胖子的图片在墙上，一看到你就不吃不下去了\u003c/p>\u003cp>【A2编剧本】\u003c/p>\u003cp>下面请大家给自己设置一个情境，可能是拖延老板交代给你50页的ppt任务，可能是拖延你另一半让你每周末打扫卫生，你保持一贯的拖延，请描述下你拖延的具体情况，要求和你老板、另一半要有对话。最后你小宇宙爆发了，用我们刚刚讨论出来的步骤解决拖延问题。请大家根据上面的要求给自己编一个剧本。\u003c/p>\u003cp>\u003cstrong>学习者1\u003c/strong>\u003cstrong>剧本\u003c/strong>：晚上睡觉之前，我儿子跟我 说：“妈妈，明天早点起吧，不要像今天一样，急急忙忙像打仗一样。”我说：“好的，明天吃什么？”我儿子回答：“明天吃水果汁，和鸡蛋饼。我们可以定一个闹钟，6点中起床。”我用他的IPAD、他的手机和我的手机都定了闹钟。到第二天的时候，一直睡到7点还没有起，急急忙忙穿上衣服，到外面买了两个包子，吃完就送儿子上学了。\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：那么在剧本中你是如何运用刚刚的解决方法来解决这个问题的？\u003c/p>\u003cp>\u003cstrong>学习者1剧本\u003c/strong>（延续上面剧本）：有一天儿子对我说：“我已经受够了吃包子了，我再也不想吃包子了。我通过读专题书的方法来改掉拖延症，因为书上给了很多治疗拖延症的方法。”\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：“我们刚才讨论的方法中，有奖励机制，有视觉化的方法等等，你是用的哪一种呢？”\u003c/p>\u003cp>\u003cstrong>学习者1回答\u003c/strong>：“我认为用的是视觉化。”\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：“那视觉化是指呈现一个画面的意思，那么你的视觉化是指什么？”\u003c/p>\u003cp>\u003cstrong>学习者1回答\u003c/strong>：“我说的视觉化是说，通过读书，它不仅给了我们解决方法，而且会让我对不再拖延后的生活产生期待，不再拖延后的生活那种画面特别美好”\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：“我明白了，的确解决拖延的书很多，方法也很多。但是用我们今天我们自己提出的解决方案的话，如果通过阅读能让你产生对未来B的美好画面，也是能够减轻你的拖延症的，因为增加了对未来B的情感。我还建议可以把这种美好的画面，画出来或者照一张类似的图片贴在墙上，说不定效果会更好。”\u003c/p>\u003cp>\u003cstrong>总结\u003c/strong>：拖延问题是世纪难题，很多时候我们会发现专家啊，书啊提供的方法不怎么管用，我个人觉得应该要用组合拳，把刚刚我们提出的这些方法都用起来，这样给你创造了一个相对严密的系统，从五感眼耳鼻舌身都管住你，建议大家回去试试。\u003c/p>\u003cp>那么今天第一个拆页是发现自己的行为模式，这样才能知道需要纠正的方向。大家很普遍的一个模式是拖延，第二个拆页指引我们找到了拖延的方法。希望这两招能让大家在生活和工作中更加专注，今天我的拆书就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1508902958000,"updated_at":1508908820000,"ria":true},{"id":3841,"topic":"专注于积极事件为什么重要","learn_goal":"把注意力集中在积极的事件上","remark":"写给“被催一族”最简明的自我管理书！即刻将注意力专注于你最重要的目标！活出心底真正渴望的人生！","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"家桢","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"大家好，我是家桢。家庭的家、木字旁一个贞洁的贞。\r\n我先来做个自我介绍，用三个标签的形式。\r\n第一个标签，我是一个文科毕业的人，大学里学习的是语言，是日语。\r\n第二个标签，我目前的工作也是一门跟语言有关的工作，不过是计算机语言，所以是一名程序猿。\r\n第三个标签，我是一个喜欢阅读的人，我称这个标签名为“阅读控”。\r\n我是在今年三四月份的时候接触拆书帮的，结果发现了一个全新的读书方法，特别有趣。\r\n所以在两个月前，我正式通过投名状的方式加入，并且今天开始第一次我的拆书之旅。\r\n那拆书帮是什么，拆书又是怎么回事呢？我为什么会如此感兴趣？\r\n那是因为，我以前的读书方法都是陶渊明的方法，叫“好读书、不求甚解”。\r\n那拆书则是一种完全不一样的读书方式，它的步骤被称为RIA。\r\n所谓R，就是reading，阅读原文。通常我们看书就只有这一步。\r\n而之后是I，就是interpretation，就是用自己的话来把原文说清楚。\r\n再往后的A，是appropriation，是指连接自己过往的经验，来指导今后的工作与生活。","ratings_count":0,"texts":[{"id":6771,"quote":"\u003cp>【R】\u003c/p>\u003cp>那我今天介绍的片段来自于《专注力》这本书。\u003cbr>\u003c/p>\u003cp>这本书有一个副标题，很好地概括了这本书讲的内容，叫：\u003c/p>\u003cp>化繁为简的惊人力量。\u003c/p>\u003cp>那接下来大家可以看一下，我给大家的片段。\u003c/p>","explains":"\u003cp>【I】\u003c/p>\u003cp>我不知道大家看下来是什么样的感受。\u003c/p>\u003cp>那我当初看完，简直是太感同身受了。\u003c/p>\u003cp>因为我从小就生活在父母、老师和长辈这样的教育之下。\u003c/p>\u003cp>他们告诉我，要看到自己身上的不足，努力改正，然后才能获得进步。\u003c/p>\u003cp>我相信自己绝不是个例，这样的教育模式，存在在大部分人的身上。\u003c/p>\u003cp>然而作者的观点认为并不是这样，他认为我们把注意力集中在积极的事物上，\u003c/p>\u003cp>才会更有可能、更有效率的帮助自己成长。\u003c/p>\u003cp>为此作者给我们提供了一些方法：\u003c/p>\u003cp>比如，早晨醒来的时候，想一想积极的事物以及今天所期待的事物。\u003c/p>\u003cp>记录当天的积极事件，去关注和赞美别人做的积极的事情。\u003c/p>\u003cp>同时，作者也并没有否认应该查漏补缺，总结经验教训，\u003c/p>\u003cp>只是这个工作应该放在一天的最后。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>那我想到一个过去的教训。\u003c/p>\u003cp>有一次呢，我需要接待一名日本客户，带他去工厂看样品。\u003c/p>\u003cp>结果我在去机场等待客户抵达的时候，发现少带了一个文件。\u003c/p>\u003cp>然后呢，我就开始焦虑不安了，生怕这个文件会产生什么影响。\u003c/p>\u003cp>但结果是这个文件一整天都没有被用到，是虚惊一场。\u003c/p>\u003cp>最后一天的工作结束，客户跟我交谈，说我今天似乎有些异常。\u003c/p>\u003cp>我表示有一个文件没有带，客户大笑表示其实这并不影响进程。\u003c/p>\u003cp>不过可以看到，被客户注意到异常，其实也是一种影响。\u003c/p>\u003cp>事后回想，因为惦记着这个失误，导致今天的工作畏首畏尾，\u003c/p>\u003cp>如果一开始就不去care这件事情，应该会有更好的发挥。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>那经由作者的启发呢，我决定将我惯有的、对消极事物的注意力放到积极的事物上。\u003c/p>\u003cp>比如呢，我可以每天都记录一点自己觉得做得还不错的小事情，\u003c/p>\u003cp>这样可以让自己愉悦起来，可以更好地在工作和生活中保持活力。\u003c/p>\u003cp>在上班的时候呢，就看看同事们认真工作，在沟通工作的时候呢，多感谢对方的付出。\u003c/p>\u003cp>假设今后再遇到诸如不重要的文件没有带的情况，\u003c/p>\u003cp>我会先专注于已经准备好的文件，保证它们在被用到的时候万无一失。\u003c/p>\u003cp>而至于我工作遗漏这件事情，就放到睡前再去总结吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1508067784000,"updated_at":1508325538000,"ria":true},{"id":2843,"topic":"如何关注于自己的专注力","learn_goal":"学习者能够掌握达到目标的有效方法，并运用于实际生活中的目标","remark":"拥有专注力将改变你的人生。\r\n人们认为专注就是要对自己所专注的东西说YES，但恰恰相反，专注意味着要对上百个好点子说NO，因为我们要仔细挑选。这就是我的秘诀——专注和简单。简单比复杂更难：你必须费尽心思，让你的思想更单纯，让你的产品更简单。但是这么做最后很有价值，因为一旦实现了目标，你就可以撼动大山。\r\n——乔布斯 苹果公司前总裁","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"李小点","city":"西宁"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"专注力就是竞争力。在工作、学习中，你总是心不在焉吗？那么今天我们就一起来学习有效专注实现既定目标的方法。\r\nF（特征）：《专注力》获得大众心理学特殊贡献奖，以及基础科学应用心理学特殊贡献奖。\r\nA（优势）：很多畅销书都不同程度地引用了本书的经典心理学实验：《影响力》、《谈判的力量》、《全新思维》等书中，《专注力》的思想无处不在，时至今日，一旦人们谈及“心智”，本书仍然是参考之首选。\r\nB（益处）：通读全书，你会有顿悟后的快感：任督二脉一旦打开，生活也会因此打开，变得更加丰润、充满更多可能性。面对烦心琐事，专注的你将不再烦恼如昔，解决方案很可能就在下一个转角处。\r\n我们常常会出现以下这种情况：在年初的时候会设定很多计划和目标，然后在年终感慨韶光易老，一事无成。我们会被各种新鲜的有趣的事物所吸引，给自己设定多个目标，却最终一无所成，像极了小学课本里狗熊摘玉米的故事，最终让我们无所成就。归根到底的原因在于专注力不足，不发有效达到目标，那么怎样才是具有专注力的有效目标实现方法呢？我们来看下面片段","ratings_count":0,"texts":[{"id":5620,"quote":"\u003cp>达成目标的最有效方法\u003c/p>\u003cp>我们来谈谈，如果你确实想要实现目标，设定目标的过程应该怎样进展。\u003c/p>\u003cp>1.设定一个目标。我们以实现目标体重为例。\u003c/p>\u003cp>2.开始做一切你认为可以帮你实现目标的事情。比如为了燃烧卡路里，你决定每周徒步三次，每次一公里，目标是每周减轻一公斤的体重。\u003c/p>\u003cp>3.对运动效果进行监控。如果你所做的事情确实给你带来所希望的成效（比如，你发现自己每周都比设定的目标轻了一公斤），那么你就坚持做下去直到目标实现。\u003c/p>\u003cp>4.如果你所做的事情并没有给你带来想要的结果，那么赶快进行头脑风暴，找些能够替换的措施，开始做些改变。这可能只是一个很小的调整，也有可能是整个策略的彻底改变。比如，你可能发现你的体重只下降了―点点，因此你决定除每周的徒步外，你还要对饮食进行控制将小吃和甜点改为只吃一些水果。或者你可能决定试试聘请私人教练每周陪你锻炼两次。\u003c/p>\u003cp>5.重复步骤3和4，直到实现你的目标。你的截止日期开始变为“直到实现我所设立的目标”。你所要做的承诺只不过是一直尝试做些不一样的事，直到找到有效的方法。有的目标可能很快实现，有的目标可能需要很长时间才能实现用这种方法，你永远不会失败，这只是一个不断学习的过程。\u003c/p>","explains":"\u003cp>what：人类总是希望不打断的进化，越来越优秀，所以我们为了让自己优秀会经常会给自己设定很多目标。但是有些目标实现了，有些目标仅仅成为了目标。\u003c/p>\u003cp>why：不知道在场的小伙伴是否有这样的经历？非常用心的运用smart原则制定了三个月或者半年的目标，自信满满并坚定的执行了，但是三个月过去了，并没有实现目标，挫败感十足。那么原文拆页提供了方法和步骤。\u003c/p>\u003cp>how：达成目标的有效方法包含五个步骤：\u003c/p>\u003cp>1.设定目标：要具体可执行，在这里就不重述了\u003c/p>\u003cp>2.选择可以帮你实现目标的事情，比如选择1-3个开始实施\u003c/p>\u003cp>3.对效果进行监控：根据目标完成的程度及效果进行周期性监控 。比如减肥可以以周进行监测。\u003c/p>\u003cp>4.头脑风暴，及时调整改变 ：根据监测效果及时调整，比如跑步减肥，你是想一周减一斤，但是只减了半斤，是不是可以加入控制饮食这一条。\u003c/p>\u003cp>5.重复3和4，直到实现目标\u003c/p>\u003cp>所以设定目标是一个动态的过程，如果只是执行计划，就很容易出现欲速则不达的情况。也可能因为方案本身并不是最有效的。白白浪费了很多时间，消磨了最初的热情。\u003c/p>","interaction":"\u003cp>举例：比如说在大二的时候英语考四级，这个呢就是第一步设定目标。第二步呢就是给自己制定了具体的学习计划，每天20个单词，3篇阅读理解。在第二个月的时候检视学习成果，发现前面背的单词很多都会忘记，效果并不如人意，所以呢请教了英语很好的师兄，他建议我不要从A到Z的背单词，而是要先背词根，再背核心词汇，最后再过单词表，果然背单词的效果就好很多。这个呢就是监控目标完成情况并及时进行调整。\u003c/p>显像提问法：相信大家在日常的工作学习生活中也都给自己制定过健身、学习、写作等目标，大家回想一下自己的目标实现过程，是不是是按照这五个步骤进行的？\u003cp>参与者分享：\u003c/p>\u003cp>分享者1：学习英语，当时的目标方案与实际情况不是很符合，因为缺乏了步骤4 ，没有及时的改变策略进行调整，所以没有达到既定的目标。\u003c/p>\u003cp>分享者2：也是学习英语，当初给自己定的目标是通过托福，但是后来连四级都没有达到，在定制目标的时候是按周计划的，但是因为步骤3没有做到，所以到计划时间终点的时候，并没有完成整个学习计划。\u003c/p>\u003cp>A2：请大家根据目前最迫切想要实现的一个目标，可以是已经启动的，也可以是准备启动的，根据今天所学习片段中的目标实现方法，制定具体的实现计划，并在小组内分享。\u003c/p>\u003cp>参与者分享：最想要实现的目标是恢复写作的技能，实施的事情是加入橙子学院的码子岛，开始每周不限字数写一篇文章，先从少开始写后期增加。在简书平台发布帮助效果的检测，可以通过请老师和小伙伴反馈的不足进行调整并针对性优化，然后对优化的写作手法再进行检测，请老师和小伙伴继续提出改进意见，不断循环优化，从而实现写作技能的提升。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496757695000,"updated_at":1496759118000,"ria":true},{"id":2740,"topic":"如何把新知识内化进自己的知识库","learn_goal":"学习者能够运用费曼学习法真正理解新知识并教授给别人","remark":"为知识付了费用，却没有得到任何实质性的回报；为精神打了鸡血，却依然停留在原地打转。\r\n还在为看了很多书却没记住什么内容懊恼吗？\r\n还在为参加了很多训练营却没有任何改变自暴自弃吗？\r\n你缺少的不是行动，也不是毅力，而是方法。方法不对，努力白费。让我们一起来学习一种有效的学习方法吧。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"李佳","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是六子，今天给大家分享的主题是如何把新知识内化进自己的知识库，内容节选自一本电子书。\r\nF: \r\n这本《专注力管理：让你的努力更高效》作者是胖子邓，毕业于北京大学金融系并获得数学双学位，这本书的内容是他在北大四年总结的专注力管理方法和心得。\r\nA:\r\n这本书是知乎推出的《一小时》系列短小精炼的电子书，写书的作者是经过知乎团队的精心寻找，在本领域拥有独到见解的专业人士。在一个小时的时间里让人对世界多一分认识，收获一种思路，拓展一个视角。\r\nB:\r\n你是不是经常有任务安排的过满而根本无法执行？你有没有感觉自己的思维能力没有进步，想要提升？你是不是经常焦虑到没有办法沉下心来做事？这本书从目标设定、思维能力提升、专注力等方面分析并给出了这些问题的答案。","ratings_count":0,"texts":[{"id":5491,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>当面对一个很难的概念或者理论的时候，如何迫使自己真正理解它。\u003c/p>\u003cp>费曼学习法：如果我需要讲解给别人听，我会如何讲？\u003c/p>\u003cp>\u003cstrong>第一步：选择一个概念\u003c/strong>\u003c/p>\u003cp>选择一个你想要理解的概念。拿一张白纸，将这个概念的名称写在这张白纸的顶部。\u003c/p>\u003cp>\u003cstrong>第二步：想象你正要把这个概念教授给一名新生\u003c/strong>\u003c/p>\u003cp>写出这个概念的一个解释，就好像你正在把这个概念讲述给一个还没有理解该主题的人那样。这是一个非常关键的环节，因为，在你把一个你已经明白，或者你还没有明白的概念解释给自己过程中，你能够获得更好的理解，并且可以精准地定位那些你仍不知道的细节。\u003c/p>\u003cp>\u003cstrong>第三步：如果你遇到问题，请原路返回\u003c/strong>\u003c/p>\u003cp>只要你在一个地方遭遇疑惑或者问题，那么请回到相应的参考资料、教程，或者，到教学助理那里去吧，重新阅读或者再次学习这些材料，直至达到能够通过书面方式解释给别人的程度。\u003c/p>\u003cp>\u003cstrong>第四步：简化并建立类比\u003c/strong>\u003c/p>\u003cp>不管你的解释有多啰唆或者如何令人迷惑，请尝试简化你的描述用语，或者创建一个类比，以便于更好地让别人理解。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>学习目标：\u003c/strong>希望大家在跟随我完成本次RIA现场学习后，学习者能够运用费曼学习法真正理解新知识并教授给别人\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例说明：\u003c/strong>\u003c/p>\u003cp>在我接触拆书帮之前，我看书的方式是这样的：买来一本书之后，从头到尾一字不落的看完才会觉得没有白花这个钱。看到新的概念的时候，我首先就是拿出笔来在下面画线，再到后来为了写公众号，我会把这些重点都摘录下来，汇总到一篇文章里面。\u003c/p>\u003cp>\u003cstrong>不那么做的坏处：\u003c/strong>\u003c/p>\u003cp>我回顾一下我的阅读收获，除了公众号里的摘要文章，我并没有把任何知识内化到自己的知识体系，也并没有改变任何行为。也就是说，买书读书如果没有真正运用的话是最大的浪费，浪费了金钱，还浪费了大量的时间和精力。\u003c/p>\u003cp>\u003cstrong>正确案例：\u003c/strong>\u003c/p>\u003cp>拆书帮有一个理念：教是最好的学！这个跟费曼学习法所主张的是一个理念。按照费曼学习法的步骤去理解一本书中的知识点，看书的效率就大大的提高了很多。\u003c/p>\u003cp>1、选择概念\u003c/p>\u003cp>上次参加拆书帮定级，拆的是《精进》里面的内容。在拆书片段里有一个概念，把事情按照收益值高低和半衰期长短分类，以此来判断自己最应该做的事情。\u003c/p>\u003cp>2、讲述概念\u003c/p>\u003cp>当我决定拆书之后，反复琢磨所选片段里这两个概念的含义，思考如何讲解才能让大家都能明白。收益值就是做完一件事情的收获多少，而半衰期呢，就是做完这件事对我们产生的影响能够持续的时间。\u003c/p>\u003cp>3、遇到问题\u003c/p>\u003cp>其中也遇到了很多问题，对待事情分类并不能清晰的解释出来，在野人大叔的指点下，我发现了这个分类的适用边界，要有一个前提，那就是对于每个人的职业发展和成长目标，分类都是不一样的。这样，我自己对片段的理解也逐渐的深刻起来。\u003c/p>\u003cp>4、简化类比\u003c/p>\u003cp>最后，建立了一个类比，把收益值大小简化成收获多少，把半衰期长短简化成能否对目标产生长期积累，这样更容易理解。\u003c/p>\u003cp>不止懂概念，把这个概念传递给了别人，甚至在生活中改变了行为，这次阅读才是真正的有收获。\u003c/p>\u003cp>当然，我们有时候面对一个概念并不需要完全遵从这个条件，只需要把概念让你把自己想要传述给别人的概念让听者能够理解透彻，没有偏差就够了。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>\u003cstrong>A1拆书家设计提问：\u003c/strong>\u003c/p>\u003cp>你有没有参加过学习训练营？你有没有看过致用类的书？你有没有听过在线个人成长微课？在学习的过程中，以上的类似的经历你有没有遇到过？你有没有把学到的知识真正的理解并且运用到你的生活中？仔细想下，你最近一次遇到新知识或者读完一本书时是怎么做的，又是怎么分享的？\u003c/p>\u003cp>学习者分享： 最近在学习思维导图，我们是自己公司组织学习的，学习方式是大家根据一篇文章的内容，用思维导图的方式提炼出来，以打卡的方式，然后发在群里，有人专门负责点评，我目前也在工作生活中开始运用思维导图。\u003c/p>\u003cp>我： 在座的各位都是学习达人，都有自己的学习方式，刚才分享的思维导图的学习也已经得到了运用，这是个很好的案例，这在懂思维导图的人面前，这样很容易理解，如果放在从来没接触过思维导图的人，这样分享的话，估计要听的云里雾里了。所以，今天我们的费曼学习法就派上了用场。\u003c/p>\u003cp>\u003cstrong>A1+反思加工:\u003c/strong>\u003c/p>\u003cp>想一想最近一周内，学到的一个新知识或者新概念，或者说你刚才想到的例子，怎样按照费曼学习法的步骤，跟大家分享一下，看能不能加深自己的理解，以及让大家都听懂？\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>最近在学非暴力沟通，首先，介绍非暴力沟通的四个要素，通过自己的观察，表达自己的情绪，说出自己的需求，提出自己的请求。通过和生活中的常见的沟通方式直接宣泄情绪与非暴力沟通的对比，让我们很直观的就可以看到非暴力沟通的优势。\u003c/p>\u003cp>面对老公晚回家的现象，换做以前我会很生气的说：“怎么又这么晚回来，你到底在干吗？你还要不要这个家了？”这样做的话，肯定双方都会心情不爽，导致后果更严重。当接触到了非暴力沟通后，换了种表达方式：（观察）最近连续三天都回家很晚，（感受）我感到非常的不开心，（需要）因为我需要你的陪伴，（请求）我希望不能把身心放在家上，你能每周至少两天多花点时间陪伴我吗？\u003c/p>\u003cp>这就是我在阅读非暴力沟通时学到的非暴力沟通技巧。\u003c/p>\u003cp>我： 先介绍非暴力沟通的概念，然后用亲身经历给我们举例示范，有了例子，表达起来就很清晰，有说服力。也就不需要后面的简化类比了。因为已经让没接触过的人都很容易就明白了非暴力沟通的主要思想。非常感谢你给大家带来的分享。\u003c/p>\u003cp>今天我的分享就到这里，很感谢大家的积极参与以及分享，希望大家在今后能够把费曼学习法运用到工作和生活中，以便可以检验自己有没有真正掌握新学的概念也可以把学到的新知识讲解给别人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496032381000,"updated_at":1508077622000,"ria":true},{"id":1845,"topic":"8020法则达成高效人生","learn_goal":"运用法则找到自己的高效事件并增加精力做到更好","remark":"80/20法则的寓意很简单，它几乎可以运用于一切场合。这个过程也很简单，确认你最重要的20%的工作事项，更多的重复这20%的工作，这当然就意味着，少做那些不太有利的80%。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"房宸","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好！\r\n我是今晚的拆书家房宸，大家对我比较熟悉了，我也就不详细介绍了，跟大家汇报最近的两个近况，我已经申请了拆书帮的组织长老，准备继承师父小柔的衣钵发光发热了，再就是我申请了12月的翰林分舵的主持人，欢迎大家周三国贸来参加活动，听我逗比，给我拍砖。\r\nF：本书的作者是英国的于尔根沃尔夫，本书有4个部分17章的内容，主要围绕时间管理、自我管理等内容，重点帮我们达到做事专注高效。\r\nA：本书较其他书籍的妙处在于，并没有鸡血的煽动性的语言，把重点更多的放在了行之有效的解决方法上，很容易操作。读起来非常容易，经常读书的人估计也就用个个把小时。\r\nB：大部分人可能一直过着随遇而安的生活，没有规划，对工作和生活尽力而为。《专注力》可以让你更高效！可以帮你战胜拖延！可以让你管理自己的同时管理他人，摆脱平庸，帮你在工作中建立信息专注，掌控会议和社交，有条不紊的实现目标，而不是随遇而安，没有计划单纯的尽力而为。\r\n今天我们就来一起拆解其中的一个片段","ratings_count":0,"texts":[{"id":4437,"quote":"\u003cp>花点时间想想80/20法则可以怎样运用到你的工作中。在工作周中，你所做的最多产的事情是什么？\u003c/p>\u003cp>现在大概估算一下，你有多少时间是花在真正做这件事情上。我曾经对很多人问过这个问题，包括行政人员，艺术家，儿童节目，喜剧人员，教师医生，基本上这些人都说他们只花费了10%到20%的时间做这些最有产出性结果的事情。当然这也就表明他们大多数时间都花在一些产出性很少的事情上，这个事实解释了为什么如此多的人总是无法摆脱平庸的境地，我们大多数人都在浪费自己的宝贵时间。\u003c/p>\u003cp>80/20法则的寓意很简单，它几乎可以运用于一切场合，如果你能够在关键的20%事项上花费更多的时间，那么你就可以做到更多产(并且很有可能赚到更多的钱)\u003c/p>\u003cp>这个过程也很简单：确认你最重要的20%的工作事项，更多的重复这20%的工作，这当然就意味着，少做那些不太有利的80%。\u003c/p>\u003cp>首先第一步要看看你目前正在做些什么。在下面的横线上，写出你工作时会做的十项任务或活动，当然，从事不同事业的人所给出的答案千差万别，但这里面可能会包括写报告、参加会议、拨打销售电话或者浏览网页，了解相关新闻。这十项任务，不要写成你的工作描述或者写你打算做的事情，而要实实在在是你工作时间中确实会去做的事情。\u003c/p>\u003cp>现在对你说，列出的这十项任务，分别写出它们在你工作时间中所占据的比重，如果你所做的事情，远不止这十件之多，那么你的比例总数就无法达到100%，你也不用像个完美主义者，一定要把所有比率计算准确，只要合理的猜测就好，如果你想更赚钱，那你可以用计算器，比如说，你一周工作四十个小时，花了三个小时做第一项工作，那么就用，3÷40，结果得到7.5%，那么这个数值就是你在这件事情所花费的时间比重，\u003c/p>\u003cp>在下面的空白处，写下你工作时所做的三件最有价值的事情，也就是帮你取得更多金钱或者代表你所做出的最大贡献，这些事情可能已经包含在你上的清单内，又或者他们中的某个或多个根本不在你做的最多的十件事情清单中。因为这些事情，实在占据了太少时间。\u003c/p>\u003cp>现在估算下，你在这件事情上花费了多少时间。理想状态是这三件最有价值的事情，同时占据你工作中最大的三块，但实际情况往往并非如此。不过别担心，用不了多久你就能了解一种方法，这种方法将教会你如何改变对于时间的利用方式，而这将会决定引导你走向快速成功。\u003c/p>\u003cp>目前占据你工作时间的十项任务：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>事件\u003c/p>\u003c/td>\u003ctd>\u003cp>比重\u003c/p>\u003c/td>\u003ctd>\u003cp>事件\u003c/p>\u003c/td>\u003ctd>\u003cp>比重\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>7\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>8\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>9\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>10\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>工作中最能增加价值的三件事：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>80/20的法则的核心思想就是你的80%的收益或价值其实仅来源于20%的努力。针对消极的事情也是如此。\u003c/p>\u003cp>举个我看到这个片段就想到的事情，我一个人的东西每次搬家需要一个金杯车来拉，我每次收拾的时候发现我拖来拖去手边用到的东西就只有化妆品和衣服，哈哈，衣服也只穿当年新买的几件……估计我80%时间所用的东西占搬家所有东西的20%都不到。\u003c/p>\u003cp>为了提高效率，这个原则可以怎样运用到你的工作中？\u003c/p>\u003cp>作者给了很明确的建议：\u003c/p>\u003cp>1、写出你目前工作中确实会做的时间占比比较多的十件事情并估算他们分别占你总工作时间的比重。（罗列100%的工作及时间占比）\u003c/p>\u003cp>2、写出你工作中三件最有价值的事情并估算他们分别所占用的时间。这三件事肯定是产出最多的三件事。（找出那“20%”占比）\u003c/p>\u003cp>3、审视一下你这三件重要的事情是否在你的十件事情里面，没有，那么就要加进去，如果有，加重这三件事在你工作中的时间比重。（多做20%）\u003c/p>\u003cp>预防异议：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 你会觉得它说得简单，我们要是能那么做，不就早就多产了了么？事实上，任何事情都需要知行合一，你知道却做不到应该想想是客观原因还是自身原因？如果你跟我一起能在这件事情上缕清思路加深印象，也许会更有执行力。\u003c/p>","interaction":"\u003cp>A2分步催化 7-9min\u003c/p>\u003cp>文中提到了80/20可以适用于一切环境-拿工作环境来说，你工作中80%的时间都会用到的物品（比如订书机、文件夹、起钉器）是否可以放在唾手可得的位置，或者你的办公桌上是否堆满20%时间都不太可能用到的东西？再比如公司的重点的产品有哪些？重点的客户是哪几个？衣橱里常穿的衣服？和伴侣及父母最容易吵架的话题？以上哪种情景你遇到了8020法则？请小伙伴们分组讨论一下并找1人分享。\u003c/p>\u003cp>&nbsp;&nbsp; 学了今天的方法，畅想一下明天、后天接下来以后的日子里，自己可以在亲人沟通、工作重点、处理问题上如何用8020法则重新规划自己的重点，又或者干脆想一想如何在你刚才想到的场景中用到8020法则。请大家规划一下并写在纸上。\u003c/p>\u003cp>总结：\u003c/p>\u003cp>这个片段很好的帮你梳理了自己的时间分配，能让你分清楚目前自己重要的事情是什么，该从哪提升自己，这三个步骤是：罗列日常事件和时间——罗列对自己有价值的事件——有价值的事件更多的放到你的日常里去。希望大家以后都能手执牛耳、事半功倍。\u003c/p>\u003cp>谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1484617010000,"updated_at":1484617010000,"ria":true},{"id":1425,"topic":"达成目标的最有效方法","learn_goal":"找到专注的焦点，制定合理的目标","remark":"你是否整天被一大堆事情包围，心烦意乱。你是否总是被微信消息、朋友圈分散注意力而无法保持专注，达成目标。你是否自信满满、热情澎湃的做过一些计划，并且自认为特别的详细周全，但是最后却还是以失败告终？如何找到专注的焦点，如何制定合理的目标，我来分享给你。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"陈宏玉","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"自我介绍+图书介绍：3min\r\n大家好，我是今晚的拆书家宏玉，我的三个标签是新媒体培训、拆书家、逻辑思维。新媒体培训是我的工作，拆书家呢，现在我是一级拆书家，希望能够尽快成为三级拆书家。逻辑思维是指，我今年下半年会主要关注和学习逻辑思维、思考方式方面的书籍，培养自己的结构化思考的能力。\r\nFAB\r\n今天我要拆解的书籍是《专注力》。\r\n不知道大家是不是有这样的感觉啊？整天被一大堆事情包围，心烦意乱。总是被微信消息、朋友圈分散注意力，总是把事情拖延到最后一刻，那么我推荐你看看这本书。它会告诉你如何找到专注的焦点，如何制定合理的目标，如何克服专注障碍，如何战胜拖延，如何建立在海量信息中保持信息专注。本书提供了一些策略、工具和方法。\r\n这本书的优势在于，书中有很多的互动演练内容,帮助你及时把学到的知识进行应用、输出。\r\n我今天给大家带来的主题是《达成目标的最有效方法》，希望通过五个步骤的学习，让大家更轻松和高效的达成目标。接下来我们来看一下拆页。","ratings_count":0,"texts":[{"id":3926,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; 达成目标的最有效方法\u003c/p>\u003cp>我们来谈谈，如果你确实想要实现目标，设定目标的过程应该怎样进展。\u003c/p>\u003cp>1.设定一个目标。我们以实现目标体重为例。\u003c/p>\u003cp>2.开始做一切你认为可以帮你实现目标的事情。比如为了燃烧卡路里，你决定每周徒步三次，每次一公里，目标是每周减轻一公斤的体重。\u003c/p>\u003cp>3.对运动效果进行监控。如果你所做的事情确实给你带来所希望的成效（比如，你发现自己每周都比设定的目标轻了一公斤），那么你就坚持做下去直到目标实现。\u003c/p>\u003cp>4.如果你所做的事情并没有给你带来想要的结果，那么赶快进行头脑风暴，找些能够替换的措施，开始做些改变。这可能只是一个很小的调整，也有可能是整个策略的彻底改变。比如，你可能发现你的体重只下降了―点点，因此你决定除每周的徒步外，你还要对饮食进行控制将小吃和甜点改为只吃一些水果。或者你可能决定试试聘请私人教练每周陪你锻炼两次。\u003c/p>\u003cp>5.重复步骤3和4，直到实现你的目标。你的截止日期开始变为“直到实现我所设立的目标”。你所要做的承诺只不过是一直尝试做些不一样的事，直到找到有效的方法。有的目标可能很快实现，有的目标可能需要很长时间才能实现用这种方法，你永远不会失败，这只是一个不断学习的过程。\u003c/p>","explains":"\u003cp>I：3min\u003c/p>\u003cp>看到大部分小伙伴都看完了，接下来是拆书家讲解引导部分。不知道在场的小伙伴是否有这样的经历？非常用心的运用smart原则制定了三个月或者半年的目标，自信满满并坚定的执行了，但是三个月过去了，并没有实现目标，挫败感十足。那么原文拆页提供了方法和步骤\u003c/p>\u003cp>1.设定目标：要具体可执行，在这里就不重述了\u003c/p>\u003cp>2.选择可以帮你实现目标的事情，比如选择1-3个开始实施\u003c/p>\u003cp>3.对效果进行监控：根据目标完成的程度及效果进行周期性监控 。比如减肥可以以周进行监测。\u003c/p>\u003cp>4.头脑风暴，及时调整改变 ：根据监测效果及时调整，比如跑步减肥，你是想一周减一斤，但是只减了半斤，是不是可以加入控制饮食这一条。\u003c/p>\u003cp>5.重复3和4，直到实现目标\u003c/p>\u003cp>所以设定目标是一个动态的过程，如果只是执行计划，就很容易出现欲速则不达的情况。也可能因为方案本身并不是最有效的。白白浪费了很多时间，消磨了最初的热情。\u003c/p>\u003cp>\u003cstrong>说到这里，我记得我大学的时候想要练口语，于是就每天背单词，背诵日常口语，结果坚持了半年，还是没能流畅的表达。一度对自己产生了怀疑，认为自己没有语言天赋。很有挫败感。学了今天这个达成目标的五个步骤，我将这样制定和完成目标。我设定的目标是半年内可以与外国人流畅的交流半小时。可以帮助我实现目标的事情有参加英语角、背诵日常英语900句。\u003c/strong>\u003cstrong>然后我以一个月为周期进行监测，\u003c/strong>\u003cstrong>衡量标准是能够在英语角与人英语交流五分钟以上。如果不能，及时作出调整。要么延长目标达成时间，要么改变练习方式。\u003c/strong>\u003c/p>\u003cp>关于是否要给目标设置截止日期，在这里强调一下，对于某个目标，你可能并不知道怎么做或者只有一点点概念，那最好不要设置截止日期，但是如果是具体的，你完全能够控制的目标，是可以设置截止日期的。\u003c/p>","interaction":"\u003cp>A1：2min &nbsp;\u003c/p>\u003cp>Ok，下面请大家思考一下，生活中你是否自信满满、热情澎湃的做过一些计划，比如我三个月要减肥十斤。五个月要看五十本书，半年要考钢琴十级。你坚持做了，但是因为没有监控和及时调整，比如没有考虑你自己的时间问题、精力问题等等。最终没有实现你的目标，以失败告终了？谁可以分享一下？\u003c/p>\u003cp>分享者1:我七月份去了四川，学习打坐禅修，回来我也想自己练习打坐盘腿，但是因为盘不上，比较有难度，也没有监控和调整，最后失败了。\u003c/p>\u003cp>A1+：7-9min\u003c/p>\u003cp>接下来我们以小组的形式讨论一下，选择一个小伙伴的计划进行修正，分析一下为什么坚持了这个目标，但是最终没有实现，请帮助这个小伙伴用最有效的方法实现这个目标。重点是建议的第三步和第四步。如何监控和利用头脑风暴作出调整和改变。现在给大家四分钟的时间，小组内讨论一下。等下我们请小伙伴来分享改进后的计划是如何制定的。\u003c/p>\u003cp>分享者1:我之前做计划都不是很成功，然后报了一个线上英语学习小组，需要打卡21天，每天读一篇英语短文，机制就是交50块钱，21天后返给你，我的计划就是，惩罚力度可以加大，并增加奖励机制，能够让自己有成就感。\u003c/p>\u003cp>分享者2:我想练劈叉，一开始练的比较猛，没有坚持下去，小组成员给我的建议就是第一，每天发照片到群里，第二，获得鼓励，第三，找专业的人指导，贴一张照片，树立标杆，第四给自己一些奖励，如果达到了，就奖励自己。\u003c/p>\u003cp>最后总结一下，想要有效的实现目标，可以使用五个步骤。1.设定目标 2.选择可以帮你实现目标的事情&nbsp; 3.对效果进行监控 4.头脑风暴，不断调整&nbsp; 5.重复3.4，直到实现目标。\u003c/p>\u003cp>最后希望大家都能够学会合理有效的制定目标，希望每个人都可以实现心中之所想。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479959935000,"updated_at":1485339608000,"ria":true},{"id":1393,"topic":"学会如何认可他人","learn_goal":"让大家掌握认可他人的方法并且运用到生活当中","remark":"你知道人们最希望得到的东西是什么吗？当你的孩子会对你说：“妈妈，你看我画的兔子好看吗？”当你的女朋友经常问你：“老公，你看我今天的衣服漂亮吗？”当你的下属做了一个非常成功的项目的时候，你知道他们最想得到的是什么吗？本期活动，跟着拆书家丫头一起学习怎样认可他人！","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"李青芳（丫头）","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"自我介绍：\r\n大家好，我叫丫头。我的三个标签是旅行、画画和二级拆书家。【学习目标】：在跟随我完成本次RIA现场学习后，学习者能够运用今天学习到的方法解决（行为）在别人寻求认可时（界定）如何认可他人的问题。\r\n【用学习者场景法介绍图书】：\r\n今天拆解的片段来自《专注力 化繁为简的惊人力量》。\r\n【事件场景】：你有这样的感觉吗，你经常忙于应付来自各界的各种干扰，一会是同事找你救火，一会是合作部门找你协作，好不容易坐下来开始做自己的事，老板把你又叫了进去；回到家中终于可以自我学习了，老人、孩子、爱人也需要你，你发现自己手忙脚乱，忙忙碌碌，整个世界好像串通好了要阻碍你拥有专注力。\r\n【提问】：你是怎么处理的呢？面对自己设定的目标，你觉得自己真的能够完成，你还有很多的潜力可以发挥，可是却不知道该怎么跨越这些障碍。\r\n【影响】：这很值得重视，如果你没有处理好，你将一直处于这种忙碌又毫无成就的状态，这一定不是你想要的，因为他将使你离目标越来越远。\r\n【解决】：那这本书就给了我们一个提高专注力的方法，从改变认知到可以去实践的方法，帮我们从几个维度去提高专注力，找到到达目标的方法。","ratings_count":0,"texts":[{"id":3892,"quote":"\u003cp>想要他人给你所希望的东西，秘诀在于帮助他人获得他们想要的。人们最希望得到什么？日复一日，绝大多数人都在渴望着同一样东西：认同感。我们都希望能够被他人欣赏、关注，希望自己与众不同。当我们还很小的时候，我们就已经在渴望着同样的东西：“妈妈，看看我！”“爸爸，看我能做什么！”只不过随着渐渐长大，我们学会了要表现的冷静，不去过多的显露出我们对于关注的热切渴望。如果你学会了认可他人，并且能始终如一的要求自己这样做，你不仅会被认为是非常有魅力的人，并且你会发现人们都很乐于帮你实现你的目标。\u003c/p>\u003cp>大多数情况下，当有人和我们说话时，我们会在听到一半的时候就走神，开始想要怎样对我们听到的内容进行评论，而不是注意听别人把事情说完。不要这样做，注意用心倾听他人所说的事知道结束。你依然可以很快给出答案或评论。\u003c/p>\u003cp>对别人真诚的赞美，这可以使他人姣好的外貌、一件衣服、一件别人刚做的事情或者其他事情。如果你真心觉得这值得赞美，这些话听起来就不会让人觉得虚伪，即便在你习惯这么做之前还是会感觉有些不真实。你不必做的太过火。这可以是简单的赞扬，比如“那双鞋真好看”，或者“你在会上提出的观点很正确，这对事情的进展非常有帮助”。\u003c/p>\u003cp>人们都爱解决他人的问题，可能因为这样可以让注意力不再集中在他们自己身上。当你向他人征询建议时，这意味着你看重他人的智慧和经验，这对别人来说就是一种奖励。在征求别人意见时，你需要保证自己所选择的事情是自己确实希望采取别人意见的事。\u003c/p>","explains":"\u003cp>通过片段我们了解到，“其实每个人都渴望被欣赏，被关注，希望自己与众不同。”每个人都需要被认可。那么我们怎样去传递你对他人的认可呢？从原文片段中我们总结出了3个方法： 1、认真倾听。当有人和我们说话时，注意用心倾听他人所说的事知道结束，并且有眼神交流。不要走神； 2、给出真诚的赞美。赞美要具体。我们可以从外貌、服饰、具体行为和事情。比如今天女朋友换了一件新衣服我们可以夸她衣服漂亮，眼光好等等不同的点进行赞美；朋友每周都回家陪父母，我们可以夸他孝顺；同事策划了一个会员活动非常完美，我们可以夸他的策划和组织能力强等等。3、向他人寻求建议。在别人做出一定成绩，我们刚好希望像对方采取学习意见的时候可以用寻求建议。在表达你对他人的认可时，这几个方法，可以随机的结合使用，你一定要根据场景去匹配合适的方法。\u003c/p>\u003cp>\u003cstrong>强化讲解概念：\u003c/strong>在这里我们说一下第三点——向他人寻求建议。如果他人分享的经验对你没有帮助，也不是你感兴趣的事情，这时候你可以使用第三种方法向他人寻求建议吗？显然不可以，因为他人的建议对我们毫无用处，是我们不需要的，这个时候我们是不适用向他人寻求建议这个方法的，这个方法只用在我们寻求的建议刚好是我们想要学习的和采纳的意见的情况下。\u003c/p>\u003cp>\u003cstrong>案例：\u003c/strong>我一直想吃家里做的饭，有一次我一回家，我朋友就高兴的跟我说今天给我做饭了，然后就把做饭过程的前前后后跟我说了一次，问我做的怎么样，我就结合了3个方法表达了认可，我是这样做的首先，1.我认真的听她把话讲完。2.我说亲爱的，你太厉害了，不会做饭都能做的这么好，你看颜色，西红柿炒鸡蛋，红黄搭配，国旗的最高配置，其次香，我闻了一下，太香了我都忍不住想吃了，最后味，我吃了一口，太好吃了。3.寻求建议。你是怎么做的啊，感觉比我做的好吃多了，有什么特殊方法吗？她跟我说放了糖，所以会感觉更鲜，我说你太厉害了，可以当大厨了都，以后我做饭的时候也放点糖试试，然后就开开心心吃饭了。\u003c/p>\u003cp>如果我们能够做到以上3点，那么我们一定会成为一个非常有魅力的人。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>大家回想一下在你的生活中是否经常会有这样类似的场景，你的孩子会对你说：“妈妈，你看我画的兔子好看吗？”你的女朋友经常问你：“老公，你看我今天的衣服漂亮吗？”当你的下属做了一个非常成功的项目的时候，虽然他嘴上不说，但是内心一定希望得到你的认可。比如我每次拆完书就会缠着师父问：”师父，我拆的怎么样怎么样？“希望得到认可。\u003c/p>\u003cp>根据自己生活中的经历，编一个故事，在这个故事里你需要用到今天的知识（1、认真倾听；2、真诚赞美；3、寻求建议。）可以是几点组合的应用，你用他成功的表达了认可，解决了问题。请将编成一个剧本，编成一个完整的故事，包含具体的人物、情节的变化，以及当时的语言动作，一定要有认可对方的细节。给大家五分钟时间，小组讨论并且选出两人，一个人扮演寻求认可的人，另一个扮演认可对方的人，进行角色扮演，等会邀请讨论最激烈的小组分享。\u003c/p>\u003cp>分享者：\u003c/p>\u003cp>A:我今天办了一个特别自豪的事情，我女儿喜欢画画，我们就找到幼儿园园长找了一块场地给我女儿办了一个画展，我们从想法开始，设计主题，设计海报，然后去做PPT，为了使女儿有更好的体验，我们每天在家练习讲解，经过所有的准备，今天画展终于开始了，为期三天，今天讲了两场PPT，在周五的时候我们会给她举行答谢会，请园长给她颁发奖杯，我觉得这是我们做的很自豪的一件事。\u003c/p>\u003cp>B：你真的是太棒了，因为很多家长都会逼着孩子去学兴趣班，很少关注孩子自己喜欢什么，你知道孩子的爱好之后主动去帮助孩子找园长办画展，这一点真的非常难得，帮小孩学习小愿望。我儿子非常调皮，并不喜欢这种静止的运动画画什么的，他可能更喜欢射击类的活动，你有什么建议给我，可以帮助他实现他的兴趣。\u003c/p>\u003cp>A：我给你一个建议，你不要去逼着孩子做什么，而是要跟他一起做，当你们一起做的时候这个过程就会变得有趣。\u003c/p>\u003cp>B:好的，非常感谢你的建议。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>\u003c/p>\u003cp>简直是演出了灵魂，演出了高潮，演出了奇迹！刚刚他们演练的很好，由于时间的关系，就不邀请其他组上来演练了，相信大家通过自己设计的故事对我们今天学习的知识点有了更深刻的理解。接下来我总结一下，我们今天学习了如何认可他人的三个步骤：1.学会倾听；2.真诚赞美；3.寻求建议。希望各位小伙伴能够在工作中运用我们今天学习的技巧，从而在人群中脱颖而出，成为一个有魅力的人！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479871403000,"updated_at":1507541882000,"ria":true},{"id":924,"topic":"专注力之目标设定","learn_goal":"完成TF2－2以及片段分享","remark":"如有有效的设定计划目标","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[{"id":2858,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1474129005000,"updated_at":1496909620000},{"id":923,"topic":"化简为繁的惊人力量","learn_goal":"过级2-2","remark":"","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"（学习目标）通过本次学习，参加活动的爱好者能从我设计的现场练习中，按照５个步骤修改一个有关自我能力提升的行动案例。\r\n（FAB介绍）这本书的作者于尔根 沃尔夫，是一位著名剧作家，本书从专注的角度讲了时间管理、战胜拖延等高效学习和工作的策略（F介绍），相比同类经典书，这是一本充满了争议的准经典，在豆瓣的评论中也充满争议，有人认为是是模仿经典的复制品，但更多人认为书中真指内心、挖出了自己的血泪史（A比较）。我的认识是只要认真实践书中的方法技巧，将使我们可以应付各种干扰，可以专注于最重要的事，并实现我们心中真正渴望的目标（B利益）。","ratings_count":0,"texts":[{"id":2857,"quote":"\u003cp>【R】下面我们来谈谈如果你确实想要实现目标，设定目标的过程应该怎样进展。\u003c/p>\u003cp>1、设定一个目标。在例子中，我们还是以实现目标体重为例。\u003c/p>\u003cp>2、开始做一切你订为可以帮你实现目标的事情。比如为了燃烧卡路里，你决定坚持每周徒步三次，每次一公里，目标是每周减轻一公斤的体重。\u003c/p>\u003cp>3、对运动过程效果进行监控。如果你所做的事情确实给你带来所希望的成效（比如，你发现自己每周都比设定的目标轻了一公斤），那么你就坚持做下去直到目标实现。\u003c/p>\u003cp>4、如果你所做的事情并没有给你带来想要的结果，那么赶快进行头脑风暴，找些能够替换的措施，开始做些改变。这可能只是一个很小的调整，也有可能是整个策略的彻底改变。比如，你可能发现你的体重只下降了一点点，因此你决定除每周徒步外，你还要对饮食进行控制，将小吃和甜点改为只吃一些水果。或者你可能决定试试聘请私人教练每周陪你锻炼两次。\u003c/p>\u003cp>5、重复步骤3和步骤4，直到实现你的目标。你的截止日期开始变为“直到实现我所设立的目标”。你所要做的承诺只不过是一直尝试做些不一样的事，直到找到有效的方法。有的目标可能很快实现，有的目标可能需要很长时间才能实现。用这种方法，你永远不会失败，这只是一个不断学习的过程。\u003c/p>","explains":"\u003cp>【I】今天我们阅读的片段是如何制定计划。\u003c/p>\u003cp>大家可能有疑问，设定计划这么简单的事情还用得着单独来讨论吗？其实这个方法看似普通，但是和我们常用的步骤关注点有本质不同。\u003c/p>\u003cp>我们常用的方法是：设定目标——设定方法——坚持、坚持再坚持。过程中我们的关注点是自己的毅力和行动能力，如果在坚持过程中失败了，我们会认为自己能力不足或没有毅力。举个例子：我有一个朋友想学成功人士“早起晨读和规划”的习惯。他设了闹钟，备了书籍纸本，结果呢？大家都很容易想到。开始起来了，困，又睡了，睡过了；后来天天摁闹钟，不胜其烦，直至有一天垂头丧气的说“我真没毅力”、“我不具备这种能力”。\u003c/p>\u003cp>看到了吧，他完全忽略了措施是否得当，其实睡前的情况、早起唤醒的方式、起床后规划这些措施比毅力更重要。常规的做法让\u003cstrong>我们把措施方法不当的问题，归结成了自己的能力或毅力不足的问题。\u003c/strong>\u003c/p>\u003cp>后来我用这个方式和他进行了讨论。他开始发现之所以起不来是因为晚上应酬太多，喝酒太多。于是他的措施从设闹钟改成了减少晚上应酬或少喝酒。过了几天，他又发现在家里还是老玩手机，刷朋友圈、微博影响睡眠，于是他决定十点半以后断网关机。之后他又发现，中午睡的过多也影响晚上入睡，于是把午睡时间缩短为半小时。包括叫起的方式也从闹钟变成了智能手环。\u003c/p>\u003cp>这个过程中他再也没有认为自己是能力不足或毅力不足，而是不断地在改善措施。\u003c/p>\u003cp>以前我们关注的重点是自己能不能坚持，而这个片段是让我们关注措施，即２至４行动、回顾、改变，直到我们的目标得以实现。\u003c/p>\u003cp>这样做的优势在于，永远有在进步的成就感，我们一直在思考更多的方式，不会因挫败感轻易放弃。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（备用）\u003c/strong>什么是目标：我要跑步，我要早起，这是不是目标，不是！是措施，为什么要跑步？为什么要早起？如果说我要使自己瘦十斤或要留出读书的时间，那还差不多。\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>\u003c/p>\u003cp>还有些小伙伴可能仍然有疑问，马上要考试了，复习没有截止时间怎么行？领导安排了完成时间，我不设截止时间怎么行？\u003c/p>\u003cp>其实我们面对的有四类事情，一是紧急但不重要的事情；二是重要但不紧急的事情；三是重要且紧急的事情；四是即不重要也不紧急的事情。\u003c/p>\u003cp>我们现在学习的技巧适用的范围是“自我提高”类，即是那些重要但不紧急的事情。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>大家思考一下，在未来一段时间里，在健身运动、阅读书籍、时间管理、自我学习（比如外语）这些方面，我们最有可能去做些什么样的计划呢，请说明。\u003c/p>\u003cp>案例：有的，最近一直想管理自己的时间、想早起。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>设想一下，现在你要下决心进行（外语学习、运动健身、晨起打卡……），你想起了今天的拆书片段，你决定用哪些方法把这件事进行下去呢？\u003c/p>\u003cp>案例：晨起\u003c/p>\u003cp>1、每天六点起，进行晨读。2、定时、选好书。3、回顾监控（预计肯定有起不来的情况，及时反思而不是内疚放弃。）4、完善自己的早起方案（针对起不来的原因进行分析，如晚睡原因、读不下去的原因等）。5、不断的对早起的情况进行分析回顾，以及完善方法，直到完成六点起晨读的目标。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":5634,"quote":"\u003cp>【R】下面我们来谈谈如果你确实想要实现目标，设定目标的过程应该怎样进展。\u003c/p>\u003cp>1、设定一个目标。在例子中，我们还是以实现目标体重为例。\u003c/p>\u003cp>2、开始做一切你订为可以帮你实现目标的事情。比如为了燃烧卡路里，你决定坚持每周徒步三次，每次一公里，目标是每周减轻一公斤的体重。\u003c/p>\u003cp>3、对运动过程效果进行监控。如果你所做的事情确实给你带来所希望的成效（比如，你发现自己每周都比设定的目标轻了一公斤），那么你就坚持做下去直到目标实现。\u003c/p>\u003cp>4、如果你所做的事情并没有给你带来想要的结果，那么赶快进行头脑风暴，找些能够替换的措施，开始做些改变。这可能只是一个很小的调整，也有可能是整个策略的彻底改变。比如，你可能发现你的体重只下降了一点点，因此你决定除每周徒步外，你还要对饮食进行控制，将小吃和甜点改为只吃一些水果。或者你可能决定试试聘请私人教练每周陪你锻炼两次。\u003c/p>\u003cp>5、重复步骤3和步骤4，直到实现你的目标。你的截止日期开始变为“直到实现我所设立的目标”。你所要做的承诺只不过是一直尝试做些不一样的事，直到找到有效的方法。有的目标可能很快实现，有的目标可能需要很长时间才能实现。用这种方法，你永远不会失败，这只是一个不断学习的过程。\u003c/p>","explains":"\u003cp>【I】今天我们阅读的片段是如何制定计划。\u003c/p>\u003cp>大家可能有疑问，设定计划这么简单的事情还用得着单独来讨论吗？其实这个方法看似普通，但是和我们常用的步骤关注点有本质不同。\u003c/p>\u003cp>我们常用的方法是：设定目标——设定方法——坚持、坚持再坚持。过程中我们的关注点是自己的毅力和行动能力，如果在坚持过程中失败了，我们会认为自己能力不足或没有毅力。举个例子：我有一个朋友想学成功人士“早起晨读和规划”的习惯。他设了闹钟，备了书籍纸本，结果呢？大家都很容易想到。开始起来了，困，又睡了，睡过了；后来天天摁闹钟，不胜其烦，直至有一天垂头丧气的说“我真没毅力”、“我不具备这种能力”。\u003c/p>\u003cp>看到了吧，他完全忽略了措施是否得当，其实睡前的情况、早起唤醒的方式、起床后规划这些措施比毅力更重要。常规的做法让\u003cstrong>我们把措施方法不当的问题，归结成了自己的能力或毅力不足的问题。\u003c/strong>\u003c/p>\u003cp>后来我用这个方式和他进行了讨论。他开始发现之所以起不来是因为晚上应酬太多，喝酒太多。于是他的措施从设闹钟改成了减少晚上应酬或少喝酒。过了几天，他又发现在家里还是老玩手机，刷朋友圈、微博影响睡眠，于是他决定十点半以后断网关机。之后他又发现，中午睡的过多也影响晚上入睡，于是把午睡时间缩短为半小时。包括叫起的方式也从闹钟变成了智能手环。\u003c/p>\u003cp>这个过程中他再也没有认为自己是能力不足或毅力不足，而是不断地在改善措施。\u003c/p>\u003cp>以前我们关注的重点是自己能不能坚持，而这个片段是让我们关注措施，即２至４行动、回顾、改变，直到我们的目标得以实现。\u003c/p>\u003cp>这样做的优势在于，永远有在进步的成就感，我们一直在思考更多的方式，不会因挫败感轻易放弃。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（备用）\u003c/strong>什么是目标：我要跑步，我要早起，这是不是目标，不是！是措施，为什么要跑步？为什么要早起？如果说我要使自己瘦十斤或要留出读书的时间，那还差不多。\u003c/p>\u003cp>\u003cstrong>适用边界\u003c/strong>\u003c/p>\u003cp>还有些小伙伴可能仍然有疑问，马上要考试了，复习没有截止时间怎么行？领导安排了完成时间，我不设截止时间怎么行？\u003c/p>\u003cp>其实我们面对的有四类事情，一是紧急但不重要的事情；二是重要但不紧急的事情；三是重要且紧急的事情；四是即不重要也不紧急的事情。\u003c/p>\u003cp>我们现在学习的技巧适用的范围是“自我提高”类，即是那些重要但不紧急的事情。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>大家思考一下，近期在健身运动、阅读书籍、时间管理、自我学习（比如外语）这些方面，我们最有可能在哪个情境下制定相关的提升计划，请具体说明。\u003c/p>\u003cp>注：如果有小伙伴说的是我要锻炼，我要跑步，我要减肥，那是一种没有明确目标的活动，不再范围之内。而我要英语过四语，我要瘦到100斤，这才是目标\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>最近一直想管理自己的时间，想要早起。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003cbr>\u003c/p>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>设想一下，现在你要下决心进行（外语学习、运动健身、晨起打卡……），你想起了今天的拆书片段，你决定用哪些方法把这件事进行下去呢？\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>1、每天六点起，进行晨读。2、定时、选好书。3、回顾监控（预计肯定有起不来的情况，及时反思而不是内疚放弃。）4、完善自己的早起方案（针对起不来的原因进行分析，如晚睡原因、读不下去的原因等）。5、不断的对早起的情况进行分析回顾，以及完善方法，直到完成六点起晨读的目标。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1474128349000,"updated_at":1496910491000,"ria":true},{"id":922,"topic":"  零容忍准则","learn_goal":"学会使用零容忍准则","remark":"","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"今天分享的片段来自于《专注力》，他的作者是一位剧作家、演讲家，这是一本教会我们如何在这个信息爆炸时代中保持信息专注的书。与其他同类型书不同的是，书中从专注这个角度出发，设计了各种能使我们更具创造力、更富成效的方法和技巧。通过这本书，我们将获得以下的能力：找到真正该做的事、战胜拖延症、进行有效的沟通以及保持信息的专注。具体到今天，我希望通过我的分享，大家能够在现场应用零容忍准则，反思加工一件曾经犹豫不绝、取舍两难的事情。","ratings_count":0,"texts":[{"id":2856,"quote":"\u003cp>有一个因素就是“无底洞现象”。决策研究表明，人们在某件事情上投入越多，（这种投入可以是金钱、时间或情感），就越难以舍弃这件事情。举个例子，一本300页的书，你已经看了200页，而你越看越觉得这本书没意思，但是你很有可能觉得还是应该把这本书看完，因为已经看了这么多页了。这一效果同样适用于其他方面，比如不应该再继续投资某个项目或以前所购习的那些不再适用于你的东西。（“我不能就这么放弃或者以这么低的价格出售，在当初购买的时候，我可是花了一大笔钱！”）\u003c/p>\u003cp>克服这种心理有个很好的策略，那就是运用“零容忍”准则。试问：如果当时我没有买这个（或在这上面花时间），现在还会这么做吗？如果答案是否定的，那么是时候停止、甩掉或者卖掉他了！\u003c/p>","explains":"\u003cp>◆一、这个片段讲到了两个知识点，一个是“无底洞现象”。进入这个怪圈的人会陷入难以取舍、犹豫不决的两难地步，一个是解决这个问题的方法：“零容忍”准则。\u003c/p>\u003cp>◆我们来举例说明一下“无底洞现象”。股票大家都不陌生吧，很多股民在手中股票价格下降后不愿抛出，心理上认为只要不卖出，就没有赔。而且是越赔越等，放上三年五年大有人在。实际上继续等待的结果通常是损失更大。我第一次炒股就是这样等了三年多惨败的。这就是典型“无底洞现象”。\u003c/p>\u003cp>之所以有这种情况，一是舍不得之前的投入（时间金钱或精力）；二是心理不愿意承认失败。\u003c/p>\u003cp>二、再说一下“零容忍”准则，它是应对无底洞现象，及时反思、评估防止损失扩大的方法。\u003c/p>\u003cp>包括三个关键点，一是反思一下这件事开始时忽略了什么？二是评估现在面临的困难是什么？三是想一想如果真的可以再来一次的话，自己会怎么选择，会不会开始这件事情。如果答案是否定的，那么就尽快结束它。 \u003c/p>\u003cp>◆如果我们不会应用“零容忍”准则，那么当面对“无底洞现象”时，我们就会陷入到明明损失越来越大，却总是犹犹豫豫无法下决心重新开始的怪圈中去。\u003c/p>\u003cp>◆\u003cstrong>适用边界：所有感觉没有收益或无意义的事情都可以这样终止吗？是的，但是必须要确认自己的感觉是客观的，确认自己的评判标准是合理的。比如：我们小时候经常感受到对上学的反感，但是我们能根据自己的感受就不上学了吗？工作创业也是一样，有人说胜利属于那些决定再坚持一下的人们，也有人说胜利是属于那些勇于舍弃的人们，哪种标准正确？只有自己根据实际情况决定。显然，在自己没有找到正确的评判标准时，有些事情不能这么办。\u003c/strong>\u003c/p>","interaction":"\u003cp>在我们工作、生活和学习的过程中，有没有经历过这样的一件事情：一件开始认为很对很有把握的事情，做了一段时间却发现困难远远超过自己的计划和能力，于是开始犹豫不决、进退两难，继续下去，很难有明显的收获；结束了它，心理上又不愿意承认失败，似乎只要维持下去失败就不会到来。请把这件事写下来。\u003c/p>\u003cp>案例：曾经想运营一个公众号，总想着一两个月见效，结果一直是粉丝无几，越做越觉得难，三个多月过去了，觉得很有挫败感，但是投入了这么多，总不想放弃，到现在一直是半死不活的。通过今天的学习，我发现，如果重来一次，我是不会干这件事的。放弃它是现在最好的选择。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474127995000,"updated_at":1474127995000,"ria":true},{"id":906,"topic":"穆穆穆穆到正无穷的1-2过级","learn_goal":"完成1-2过级目标","remark":"","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"穆穆穆穆到正无穷","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫穆洁玉，刚刚晋升成大三的学生，很高兴能在这里带拆今天的片段。在开始拆片段之前，先分一下小组吧。\r\n李朝晖老师与爱莲老师为一组，\r\n李小曼老师与文羊老师为一组。\r\n在带拆之前，我想先介绍一下片段的出处，片段出自一本名为《专注力》的书。这本书的作者于尔根•沃尔夫，是一位著名剧作家，本书从专注的角度讲了时间管理、战胜拖延等高效学习和工作的策略，相比同类经典书，这是一本充满了争议的准经典，在豆瓣的评论中也充满争议，有人认为是是模仿经典的复制品，但更多人认为书中真指内心、挖出了自己的血泪史。我的认识是只要认真实践书中的方法技巧，将使我们可以应付各种干扰，可以专注于最重要的事，并实现我们心中真正渴望的目标。","ratings_count":0,"texts":[{"id":2776,"quote":null,"explains":"\u003cp>1.首先，MAD大规模行动日是指在很短的时间内，完成原先相对很长时间能完成的事情。\u003c/p>\u003cp>2.其次，了解MAD大规模行动日是一个技巧，这个技巧应用的目的，最重要的是鼓舞士气，重振信心。\u003c/p>\u003cp>3.因为MAD大规模行动日的执行的确会带给体力脑力和心力极大的冲击，而且需要在一定的时间内一直持续着那种高效率的紧张状态，所以科学的部署至关重要。如何科学部署，需要做到以下几点，\u003c/p>\u003cp>其一在事前准备中，\u003c/p>\u003cp>1)为了保证行动中一鼓作气不分神，不受干扰，那你就需要做好完善的物资准备，在行动之前将一切可能用上的文件，资料，物品等等全部备齐，做好完善的后勤保障。\u003c/p>\u003cp>2)为了让我们行动地更有方向，我们需要有一定的目标准备，第一要明确最终目标，而且这个目标必须有挑战性，有压力才有动力嘛；第二点就是要分阶段细化目标，比如，第一个小时我要完成什么，第二个小时我要完成什么，这样有助于推进行动的进行；第三要让进度目标具有可视性，即通过小目标的完成，我们可以感受到奋斗的动力。\u003c/p>\u003cp>其二是事中执行，首先要保证我们行动的进度，每个环节都要紧密相连，其中一个环节断裂，整个计划就会泡汤，然后要注意休息，就像课间十分钟一样，给自己一点点时间去缓解疲劳，最后，记得要补充体力，适当吃点东西，喝些水，适当的食物不仅能补充能量，还可促进脑补循环，加快大脑运转。\u003c/p>\u003cp>其三就是事后庆祝了，在行动结束之后，给自己来一场庆祝大会吧，满足一下自己的成就感，这样下次干的会更有劲儿。如果今天我的TF1-1完成了，我就要好好犒劳犒劳自己，下午去逛逛街，给自己买件衣服奖励自己。\u003c/p>\u003cp>以上是我对于MAD大规模行动日的理解，下面，我再将我所说的内容中的重点做一次总结，第一，要知道MAD是什么，MAD的最终目的是什么，第二就是在MAD行动日里，我们要做好充分的事前准备，在事中要保证每个环节的紧密相连，时刻保持精力的充沛，事后要对自己进行奖励，以此鼓励自己。\u003c/p>","interaction":"\u003cp>【A1】一组讨论曾经做的某件事因为事前准备充足因此成功完成或者因为准备不足而失败的事例。\u003c/p>\u003cp>另一组讨论曾经做的某件事因为事中或事后计划详细而成功或计划不尽详细而失败的事例。\u003c/p>\u003cp>每组成员分别向大家展示。\u003c/p>\u003cp>【A2】通过对以上片段的了解，请大家在便签上写下近期要完成的一件事，要求，用到片段中的知识点。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1473833023000,"updated_at":1473833119000},{"id":893,"topic":"穆穆穆穆到正无穷的1-1过级","learn_goal":"完成1-1过级目标","remark":"穆穆穆穆到正无穷的1-1过级实录","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"穆穆穆穆到正无穷","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫穆洁玉，是一名在校大学生，土生土长的庄里人。我本人从小爱好一些文学性质较强的书籍，像张爱玲，三毛，她们的书都走的是文艺范，所以，我看的就比较多，从去年在拆书帮学习以来，看的书逐渐偏向于致用类了，例如《说话之道》《怪诞行为学》等等。现在在看《厚黑学》，刚开头，期待着看完后能给自己带来的一些处事方式上的改变。\r\n对于拆书呢，我的理解是能量转化，学以致用，与以往阅读方式相比，拆书是可以将我们看到的内容通过自己的思考转化成我们需要的知识，并通过我们的行动，付诸实践，从而得到能力的提升。这也就是我们常说的RIA便签读书法，用最简洁的语言来说，R代表阅读，I代表思考，A分为A1和A2两部分，分别代表曾经经历的和未来要做的。总的来说，拆书不是“拆散”，而是“转化”和“内化”，是将知识化为能力的一种方式。\r\n对于拆书帮，我认为拆书帮是一个大家庭，在这个大家庭中，我们不光以书会友，我们还用自己的思考和行动丰富着自身的阅历，不断强大着，成长着。但是这个家庭中，也有比较严格的家风，我们不接受懒惰的人，不接受颓靡的人，我们的家人都是积极的，都是有独立思考力的，因此，在拆书帮里，我们汲取着知识，锻炼","ratings_count":0,"texts":[{"id":2744,"quote":null,"explains":"\u003cp>1.首先，MAD大规模行动日是指在很短的时间内，完成原先相对很长时间能完成的事情。\u003c/p>\u003cp>2.其次，了解MAD大规模行动日是一个技巧，这个技巧应用的目的，最重要的是鼓舞士气，重振信心。\u003c/p>\u003cp>3.因为MAD大规模行动日的执行的确会带给体力脑力和心力极大的冲击，而且需要在一定的时间内一直持续着那种高效率的紧张状态，所以科学的部署至关重要。如何科学部署，需要做到以下几点，\u003c/p>\u003cp>其一在事前准备中，\u003c/p>\u003cp>1)为了保证行动中一鼓作气不分神，不受干扰，那你就需要做好完善的物资准备，在行动之前将一切可能用上的文件，资料，物品等等全部备齐，做好完善的后勤保障。\u003c/p>\u003cp>2)为了让我们行动地更有方向，我们需要有一定的目标准备，第一要明确最终目标，而且这个目标必须有挑战性，有压力才有动力嘛；第二点就是要分阶段细化目标，比如，第一个小时我要完成什么，第二个小时我要完成什么，这样有助于推进行动的进行；第三要让进度目标具有可视性，即通过小目标的完成，我们可以感受到奋斗的动力。\u003c/p>\u003cp>其二是事中执行，首先要保证我们行动的进度，每个环节都要紧密相连，其中一个环节断裂，整个计划就会泡汤，然后要注意休息，就像课间十分钟一样，给自己一点点时间去缓解疲劳，最后，记得要补充体力，适当吃点东西，喝些水，适当的食物不仅能补充能量，还可促进脑补循环，加快大脑运转。\u003c/p>\u003cp>其三就是事后庆祝了，在行动结束之后，给自己来一场庆祝大会吧，满足一下自己的成就感，这样下次干的会更有劲儿。如果今天我的TF1-1完成了，我就要好好犒劳犒劳自己，下午去逛逛街，给自己买件衣服奖励自己。\u003c/p>\u003cp>以上是我对于MAD大规模行动日的理解，下面，我再将我所说的内容中的重点做一次总结，第一，要知道MAD是什么，MAD的最终目的是什么，第二就是在MAD行动日里，我们要做好充分的事前准备，在事中要保证每个环节的紧密相连，时刻保持精力的充沛，事后要对自己进行奖励，以此鼓励自己。\u003c/p>","interaction":"\u003cp>[A1]通过对这个拆书片段的理解，我想到了自己高中的时候，会给自己定下好多好多目标和日程表，比如这周，我要把英语课本上的单词通通背一遍，今天，我要六点起床，然后十五分钟洗漱，三十分钟背单词，三十分钟背古文，一个小时做数学等等，经常把这些写在桌子上，刻在卧室的墙上，但是，没有一次顺顺利利完成，现在分析原因，无外乎没有给自己施加压力总是认为时间还多，不着急，要么就是定了计划因为各种各样的事儿耽误了，始终静不下心来。\u003c/p>\u003cp>不过，我在大学中的一个学长就很会安排自己的时间，一次他要起草一份策划书，但是，他又是一个痴迷于游戏的网络狂人，所以，静下心来去编写东西对他来说很困难，不过，他有他自己的一套独特办法，周五晚上，他采购了一大批零食，然后跟身边的朋友打了声招呼，说他要闭关了，就消失了。他的确是在闭关，周六一天，他都在着那份策划，累了就喝点饮料，吃口薯片，然后接着埋头苦干，在傍晚大概六点的时候，突然给我们打电话，说一起出去吃饭吧，我策划案完成了，去庆祝庆祝吧！\u003c/p>\u003cp>[A2]下周考会计证，这周正在做最后的冲刺，周二课最少，那就抽出周二的时间，将《财经法规》第二章的内容背过，提前准备好书本和练习册，从早上七点开始背书本内容，八点以后休息十分钟，然后做一个一小时的习题，再休息十分钟，最后再次翻开书本，看看哪里的知识没有记牢。如果周二一天能把第二章的内容背过，那晚上一定要跟舍友出去嗨皮，犒劳犒劳辛苦了一天自己嘛。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473671289000,"updated_at":1473671556000},{"id":883,"topic":"风之弈语的1-2过级","learn_goal":"完成1-2过级目标","remark":"风之弈语的1-2过级实录","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好我是李朝晖，很荣幸成为国际庄第一批参加拆书家训练营的一员，同时也预祝大家过级顺利。今天我选取的片段来自于《专注力》。在这本书会教给我们\r\n——如何真正该做的事？如何战胜拖延症？如何利用好右脑？如何进行的沟通？如何保持信息专注？\r\n有人说：读这本书书是一个积极的旅程，一段最终会实现我们想得到的、幸福的旅程。","ratings_count":0,"texts":[{"id":2733,"quote":"\u003cp>【R】专注于积极事件有哪些好处？\u003cbr> 你可以选择你要考虑的东西，将80%的注意力集中在你的优势上，集中在日常生活中做得比较好的事情上以及你的潜能上，这种做法会更加有效。\u003c/p>\u003cp>——如果你已经习惯于强调消极的事情，那么想要改变这个习惯就需要花些时间了，不过还是有些方法可以帮你转到更积极的方向上来。每天早上醒来的时候，花一两分钟想想生命中值得感激的事情。同时，想一想这一天你所期待的事情。\u003c/p>\u003cp>——在一天当中，当有事情进行得很好的时候，花点时间把它记下来。这些事情并不一定要是什么大的成就。可能只是你处理得非常得当的一通电话或者你回答同事的一个问题。这听起来也许很琐碎，但是想想，你一天中会注意到多少消极的小事？花些时间注意这些积极的东西，这可以帮你在思想上达到某种平衡。\u003c/p>\u003cp>——同样，注意其他人所做的积极而有价值的事情，花点时间去赞美他们所做的事。糟糕的项目经理只会记住下属犯错的时候，而优秀的项目经理则懂得培训员工的最好方式是强化他们的有效行为。\u003c/p>\u003cp>——夜晚时分，简要回顾一下当天发生的事情。积极和消极方面的事情都要想一想，想想从这些事情中你都学到些什么。如果这天确实有很不好的事情发生，那么下一次在遇到类似情况时你要怎么处理呢？那种有关个人发展的说法，什么“人生没有错误，有的只是不同的经历”，这种话听起来不免有些幼稚，但其中确实有一丝真理的成分。\u003c/p>\u003cp>你的这种思维方式上的改变可能实际上成为实施80/20法则最重要的方面，因为如果不首先改变消极的态度，你是很难改变那些消极行为的。\u003c/p>","explains":"\u003cp>1、培养积极的思维：每天早上想一些快乐的、幸福的、值得感激的事情。一日之计在于晨，带着积极的情绪开始一天，和一身疲倦的开始一天，差别不言自明。\u003c/p>\u003cp>2、记住积极的事情：随时记下一些顺利的工作和生活的点滴，用来抵消我们产生的消极情绪。因为我们经常会在无意中关注到消极的事情，比如工作中相互配合的问题，学习中遇到困难的内容，谈判中出现艰巨环节。但其实我们却忽略了其中更多积极的内容。\u003c/p>\u003cp>3、赞美积极的行为：无论是对朋友、对亲人、对领导、对下属，赞美别人的同时也会得到正面积极的回应。至少会是一个微笑，一句谢谢，象一面镜子一样，我们传递了积极的信息，就一定会反馈回同样的内容。\u003c/p>\u003cp>4、思考积极的方法：好的作法下一次不一定还会记得，但是错误的行为却经常会一次次的再现。因此延续成功的作法和把教训变成经验是思考和回顾的重点。如果我们一次失错后从此找到了解决问题的办法，心情一样会变得快乐，反之我们要是一次次被同一个问题所击倒，结果将是越来越沮丧，直至失去信心。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>我们刚才了解到四种专注于积极事情的作法，下面请每人回忆一个与专注积极事情有关的实例，在小组内分享。每人一分钟，总时间5分钟。然后每组出一人分享。\u003c/p>\u003cp>第一组、请回忆一下今天有哪些快乐的事情（睡了一个好觉，和朋友愉快的聊天，准备过级材料很有成就感）\u003c/p>\u003cp>第二组、请赞美一下你的组员，并记下他的回应\u003c/p>\u003cp>第三组、请写下关于积极心态的好处：至少三条\u003c/p>\u003cp>——专注积极的事情有哪些好处？更有进取心/更自信/更乐观/更有成就感/更易于沟通/更具备活动和动力/更有方向感/更健康/更幸福/更大气\u003c/p>\u003cp>A2\u003c/p>\u003cp>请大家参照今天的片段写下自己的下一步规划\u003c/p>\u003cp>1、培养积极的思维：如何带着积极的情绪开始新的一天\u003c/p>\u003cp>2、记住积极的事情：如何随时记下一些顺利的工作和某些生活的点滴。\u003c/p>\u003cp>3、赞美积极的行为：如何赞美别人。\u003c/p>\u003cp>4、思考积极的方法：如何总结或回顾。\u003c/p>\u003cp>请注意：不能仅是决心，要是具体的做法，要有明确的时限，要有可衡量或可观测的预期结果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473607561000,"updated_at":1473607561000,"ria":true},{"id":882,"topic":"风之弈语的1-1过级","learn_goal":"化繁为简的惊人力量","remark":"完成1-1过级目标","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是李朝晖，大家记住毛主席的诗七律•答友人就能记住我的名字，“芙蓉国里尽朝晖”，不仅有我的名，连姓都有了。读书、运动和聚会是我的三大爱好。关于读书，我喜欢拆书和共读两种方法；关于运动，足球围棋游泳都是我的最爱；关于聚会，每周我都会和朋友们组织两三次聚会，当然也包括今天。\r\n拆书帮介绍：刚才提到了拆书，下面说一下我对拆书的理解。第一，读不完记不住不是最大的问题，最大的问题是用不上。所以记住，只要用上一点点，我们的收获就能值回百倍的书价。第二，读任何一本30元的致用类图书，完全能达到3万元培训的效果。第三，凡是不联系经验的阅读都不配称为成人阅读，凡是不改变行为的学习是极大的浪费。第四，最好的学习方法就是教会别人。","ratings_count":0,"texts":[{"id":2732,"quote":"\u003cp>如何带有目的地消费信息\u003cbr> 当你对于信息的使用缺乏目的性时，你便无法掌控信息。如果一开始便带有目的性，你会自动对信息进行筛选过滤，这能帮助你分辨有关及无关的信息。多数人接收到的大量邮件就是个很好的例子。有些是需要你关注的私人邮件，有此进立即删除的垃圾邮件，问题是剩下的那些邮件。80/20法则再次适用：这些信息中可能只有20%适用于你最重要的目标，剩余的80%可能只是在一般意义上比较有趣，并没有直接的关系。我们将在第12章具体讨论如何处理邮件，目前还是来看看你所能够运用的四条策略，这些策略同样也可以运用于处理其他来源的信息。\u003cbr> ——在接触新信息之前，先快速提醒自己此时最具吸引力的话题，那些和你最要的目标相关的话题。\u003cbr> ——如果你知道这条信息并不相关，看都不要去看它一眼，直接丢弃这条信息或者先将这条信息搁置在一边，直到它所含的信息可能更加相关时再去看。\u003cbr> ——在可能的时候，分配其他人进行这份材料的查阅工作，告诉他们你正在寻找什么信息。他们可以复印或者扫描相关内容以供你查看。\u003cbr> ——对于你所面对的信息，扫视最要的信息点而不是全部通读。\u003c/p>","explains":"\u003cp>I:今天我们选的片段来自于《专注力》，书中有一个重要的原则叫二八法则。二八法则有很多种分法，比如我们接收到的信息，20%是紧急的80%是非紧急的；20%是有意义的80%是无意义的；20%是可以快速处理的80%则要费大量时间；20%有我们当前的工作有关80%是无关的。\u003c/p>\u003cp>而我们的思路经常被所看到的内容带偏，因为看到的内容会更加形象、更加生动，它们比我们思路中虚拟的想法更加吸引人。查询信息的四个关键步骤如下：\u003cbr> 1、明确目标：无论做什么事情前，都再次确认或多次确认一下自己的行动目标，确保它更加清晰化，最好是以一个形象出现在自己的脑海中。\u003cbr> 2、远离诱惑：用清晰、形象的目标去审视每一条出现的信息，去判别信息是否与我们的目标有关，只要确认无关，看都不要再看，第一时间离开它，防止被它的内容带偏。\u003cbr> 3、寻找协同：让我们的同事和下属都知道我们的目标是什么，这样不仅可以让大家协助我们来寻找更多的信息，更重要的是让大家都来帮助我们不断的深化和清晰目标。还有，就是他们不会来干扰我们的工作了。\u003cbr> 4、扫视重点：对于信息的判别，要迅速的浏览关键的信息，而不是全部读一遍，否则，又会被其中的不相关但是有吸引力的内容引偏。\u003c/p>","interaction":"\u003cp>A1:昨天我本打算上网准备一下拆书的作业，结果我先后打开了这些内容：1、360卫士2、欧洲杯：葡萄牙胜威尔士3、石家庄已成为华北第一堵4、万科股权之争：无规则、不情怀的土豪之战\u003c/p>\u003cp>结果，我大约过了二十分钟才想起自己正事。\u003c/p>\u003cp>同时，在单位时由于以前浏览器主页设置的是新浪之类网站，每当收邮件时，一打开浏览器时网站就弹出各种的新闻（而且很有针对性，象我这样的体育迷看到的都是热门体育类消息），结果……直到把主页换成了办公网站，这个问题才解决了。包括后来的微博、微信，经常是看了半天还没进入到主题。\u003c/p>\u003cp>早上走路上班，路上看了三回手机，一次看到了王宝强离婚案反转情节，第二次看到国球女团横扫德国，第三次看到南海报道。其次这三次我都是为了看几点了，但我一次也没记住到底几点了。\u003c/p>\u003cp>A2:从下周起落实三件事，一是用好便签，每次便签写下要完成的几项工作，时时提醒自己；二是用好彩笔，通过勾选涂描提醒自己重点进展；三是把这个便签贴在家里和单位的电脑上。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473607313000,"updated_at":1473607313000,"ria":true},{"id":739,"topic":"如何使用“零容忍策略”","learn_goal":"完成TF2－1及片段分享","remark":"如何使用“零容忍策略”，避名陷入不得不做的怪圈","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"国际庄筹备分舵拆书家过级第三场","ratings_count":0,"texts":[{"id":2371,"quote":"\u003cp>有一个因素就是“无底洞现象”。决策研究表明，人们在某件事情上投入越多，（这种投入可以是金钱、时间或情感），就越难以舍弃这件事情。举个例子，一本300页的书，你已经看了200页，而你越看越觉得这本书没意思，但是你很有可能觉得还是应该把这本书看完，因为已经看了这么多页了。这一效果同样适用于其他方面，比如不应该再继续投资某个项目或以前所购习的那些不再适用于你的东西。（“我不能就这么放弃或者以这么低的价格出售，在当初购买的时候，我可是花了一大笔钱！”）\u003c/p>\u003cp>克服这种心理有个很好的策略，那就是运用“零容忍”准则。试问：如果当时我没有买这个（或在这上面花时间），现在还会这么做吗？如果答案是否定的，那么是时候停止、甩掉或者卖掉他了！\u003c/p>","explains":"\u003cp>◆一、这个片段讲到了两个知识点，一个是“无底洞现象”。进入这个怪圈的人会陷入难以取舍、犹豫不决的两难地步，一个是解决这个问题的方法：“零容忍”准则。\u003c/p>\u003cp>◆我们来举例说明一下“无底洞现象”。股票大家都不陌生吧，很多股民在手中股票价格下降后不愿抛出，心理上认为只要不卖出，就没有赔。而且是越赔越等，放上三年五年大有人在。实际上继续等待的结果通常是损失更大。我第一次炒股就是这样等了三年多惨败的。这就是典型“无底洞现象”。\u003c/p>\u003cp>之所以有这种情况，一是舍不得之前的投入（时间金钱或精力）；二是心理不愿意承认失败。\u003c/p>\u003cp>二、再说一下“零容忍”准则，它是应对无底洞现象，及时反思、评估防止损失扩大的方法。\u003c/p>\u003cp>包括三个关键点，一是反思一下这件事开始时忽略了什么？二是评估现在面临的困难是什么？三是想一想如果真的可以再来一次的话，自己会怎么选择，会不会开始这件事情。如果答案是否定的，那么就尽快结束它。 \u003c/p>\u003cp>◆如果我们不会应用“零容忍”准则，那么当面对“无底洞现象”时，我们就会陷入到明明损失越来越大，却总是犹犹豫豫无法下决心重新开始的怪圈中去。\u003c/p>\u003cp>◆\u003cstrong>适用边界：所有感觉没有收益或无意义的事情都可以这样终止吗？是的，但是必须要确认自己的感觉是客观的，确认自己的评判标准是合理的。比如：我们小时候经常感受到对上学的反感，但是我们能根据自己的感受就不上学了吗？工作创业也是一样，有人说胜利属于那些决定再坚持一下的人们，也有人说胜利是属于那些勇于舍弃的人们，哪种标准正确？只有自己根据实际情况决定。显然，在自己没有找到正确的评判标准时，有些事情不能这么办。\u003c/strong>\u003c/p>","interaction":"\u003cp>在我们工作、生活和学习的过程中，有没有经历过这样的一件事情：一件开始认为很对很有把握的事情，做了一段时间却发现困难远远超过自己的计划和能力，于是开始犹豫不决、进退两难，继续下去，很难有明显的收获；结束了它，心理上又不愿意承认失败，似乎只要维持下去失败就不会到来。请把这件事写下来。\u003c/p>\u003cp>太郎：读了一本小强升职记，大家都说好，读了几天发现自己根本没有这方面经验，却又不愿意半途而费，于是又磨跳蹭了好几天，实在是食之无味、弃之可惜的感觉。\u003c/p>\u003cp>文羊：觉得练毛笔字这事不错，上个月开始练了，结果时间对不上水平也不行，时有时无的，但是看到新买的字贴和笔什么的，又觉得舍不得，一直心里放不下。\u003c/p>\u003cp>请大家结合今天的学习，想象一下刚才写下的这件事情正让自己处于进退两难、犹豫不决的地步中，你将如何应用零容忍原则来下决心？重复一下知识点\u003c/p>\u003cp>一是反思一下这件事开始时我们忽略了什么？\u003c/p>\u003cp>二是评估现在面临的困难是什么？\u003c/p>\u003cp>三是想一想如果真的可以再来一次的话，自己会怎么选择，会不会按照之前的方式处理这件事情？\u003c/p>\u003cp>下决心吧，告诉我你的答案是什么？\u003c/p>\u003cp>太郎：一、忽略了这本书并不适合我这样的实习中的大学生，只是听别人好就买了。其实没有认真看书评。二、现在是书本内容很不符合我的现状，我一时体会不了，看不下去。三、如果现在评估的话，肯定不看了。\u003c/p>\u003cp>所以，我下决心把书放到一边，以后再说。另外，以后看书一定先上豆瓣之类的看看书评之类再买。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1471342986000,"updated_at":1471342986000,"ria":true},{"id":714,"topic":"如何保持积极的心态","learn_goal":"完成拆书手册TF1-2及现场分享","remark":"如何保持积极的心态","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"欢迎大家参加国际庄梧桐筹备分舵的线下拆书活动，今天将有两位小伙伴进行TF1－2和TF1－2的过级。","ratings_count":0,"texts":[{"id":2276,"quote":"\u003cp>专注于积极事件有哪些好处？\u003cbr> 你可以选择你要考虑的东西，将80%的注意力集中在你的优势上，集中在日常生活中做得比较好的事情上以及你的潜能上，这种做法会更加有效。\u003c/p>\u003cp>——如果你已经习惯于强调消极的事情，那么想要改变这个习惯就需要花些时间了，不过还是有些方法可以帮你转到更积极的方向上来。每天早上醒来的时候，花一两分钟想想生命中值得感激的事情。同时，想一想这一天你所期待的事情。\u003c/p>\u003cp>——在一天当中，当有事情进行得很好的时候，花点时间把它记下来。这些事情并不一定要是什么大的成就。可能只是你处理得非常得当的一通电话或者你回答同事的一个问题。这听起来也许很琐碎，但是想想，你一天中会注意到多少消极的小事？花些时间注意这些积极的东西，这可以帮你在思想上达到某种平衡。\u003c/p>\u003cp>——同样，注意其他人所做的积极而有价值的事情，花点时间去赞美他们所做的事。糟糕的项目经理只会记住下属犯错的时候，而优秀的项目经理则懂得培训员工的最好方式是强化他们的有效行为。\u003c/p>\u003cp>——夜晚时分，简要回顾一下当天发生的事情。积极和消极方面的事情都要想一想，想想从这些事情中你都学到些什么。如果这天确实有很不好的事情发生，那么下一次在遇到类似情况时你要怎么处理呢？那种有关个人发展的说法，什么“人生没有错误，有的只是不同的经历”，这种话听起来不免有些幼稚，但其中确实有一丝真理的成分。\u003c/p>\u003cp>你的这种思维方式上的改变可能实际上成为实施80/20法则最重要的方面，因为如果不首先改变消极的态度，你是很难改变那些消极行为的。\u003c/p>","explains":"\u003cp>【I】\u003c/p>\u003cp>1、培养积极的思维：每天早上想一些快乐的、幸福的、值得感激的事情。一日之计在于晨，带着积极的情绪开始一天，和一身疲倦的开始一天，差别不言自明。\u003c/p>\u003cp>2、记住积极的事情：随时记下一些顺利的工作和生活的点滴，用来抵消我们产生的消极情绪。因为我们经常会在无意中关注到消极的事情，比如工作中相互配合的问题，学习中遇到困难的内容，谈判中出现艰巨环节。但其实我们却忽略了其中更多积极的内容。\u003c/p>\u003cp>3、赞美积极的行为：无论是对朋友、对亲人、对领导、对下属，赞美别人的同时也会得到正面积极的回应。至少会是一个微笑，一句谢谢，象一面镜子一样，我们传递了积极的信息，就一定会反馈回同样的内容。\u003c/p>\u003cp>4、思考积极的方法：好的作法下一次不一定还会记得，但是错误的行为却经常会一次次的再现。因此延续成功的作法和把教训变成经验是思考和回顾的重点。如果我们一次失错后从此找到了解决问题的办法，心情一样会变得快乐，反之我们要是一次次被同一个问题所击倒，结果将是越来越沮丧，直至失去信心。\u003c/p>\u003cp>发散一下：我们如何养成了专注消极事情的习惯？\u003c/p>\u003cp>有研究表明，80%的时间里我们都在关心哪些事情没有做好，哪些事情要改进。好象做的好是应该的，做不好是必须自责的。\u003c/p>\u003cp>我们怎么变成了这样呢？因为我们是被训练成这样的。在三四岁之前，不管我们做什么事情，大人们都会给我们掌声和称赞。但是等到我们上学以后，他们专注的焦点开始变成我们都做错了什么，这种状态在我们以后所接受的教育阶段一直存在。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>第一组、请回忆一下今天有哪些快乐的事情（睡了一个好觉，和朋友愉快的聊天，准备过级材料很有成就感）\u003c/p>\u003cp>第二组、请赞美一下你的组员，并记下他的回应\u003c/p>\u003cp>第三组、请写下关于积极心态的好处：至少三条\u003c/p>\u003cp>——专注积极的事情有哪些好处？更有进取心/更自信/更乐观/更有成就感/更易于沟通/更具备活动和动力/更有方向感/更健康/更幸福/更大气\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>请大家参照今天的片段写下自己的下一步规划\u003c/p>\u003cp>1、培养积极的思维：如何带着积极的情绪开始新的一天\u003c/p>\u003cp>2、记住积极的事情：如何随时记下一些顺利的工作和某些生活的点滴。\u003c/p>\u003cp>3、赞美积极的行为：如何赞美别人。\u003c/p>\u003cp>4、思考积极的方法：如何总结或回顾。\u003c/p>\u003cp>请注意：不能仅是决心，要是具体的做法，要有明确的时限，要有可衡量或可观测的预期结果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1470708269000,"updated_at":1470708269000,"ria":true},{"id":708,"topic":"拆书家过级训练及书籍分享","learn_goal":"过级TF1－1","remark":"如何实现信息专注","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"风之弈语","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"欢迎大家来参加拆书活动，今天我分享的书籍是专注力","ratings_count":0,"texts":[{"id":2260,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>如何带有目的地消费信息\u003cbr> &nbsp; 当你对于信息的使用缺乏目的性时，你便无法掌控信息。如果一开始便带有目的性，你会自动对信息进行筛选过滤，这能帮助你分辨有关及无关的信息。多数人接收到的大量邮件就是个很好的例子。有些是需要你关注的私人邮件，有此进立即删除的垃圾邮件，问题是剩下的那些邮件。80/20法则再次适用：这些信息中可能只有20%适用于你最重要的目标，剩余的80%可能只是在一般意义上比较有趣，并没有直接的关系。我们将在第12章具体讨论如何处理邮件，目前还是来看看你所能够运用的四条策略，这些策略同样也可以运用于处理其他来源的信息。\u003cbr> &nbsp; ——在接触新信息之前，先快速提醒自己此时最具吸引力的话题，那些和你最要的目标相关的话题。\u003cbr> &nbsp; ——如果你知道这条信息并不相关，看都不要去看它一眼，直接丢弃这条信息或者先将这条信息搁置在一边，直到它所含的信息可能更加相关时再去看。\u003cbr> &nbsp; ——在可能的时候，分配其他人进行这份材料的查阅工作，告诉他们你正在寻找什么信息。他们可以复印或者扫描相关内容以供你查看。\u003cbr> &nbsp; ——对于你所面对的信息，扫视最要的信息点而不是全部通读。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>I:今天我们选的片段来自于《专注力》，书中有一个重要的原则叫二八法则。二八法则有很多种分法，比如我们接收到的信息，20%是紧急的80%是非紧急的；20%是有意义的80%是无意义的；20%是可以快速处理的80%则要费大量时间；20%有我们当前的工作有关80%是无关的。\u003c/p>\u003cp>而我们的思路经常被所看到的内容带偏，因为看到的内容会更加形象、更加生动，它们比我们思路中虚拟的想法更加吸引人。查询信息的四个关键步骤如下：\u003cbr> 1、明确目标：无论做什么事情前，都再次确认或多次确认一下自己的行动目标，确保它更加清晰化，最好是以一个形象出现在自己的脑海中。\u003cbr> 2、远离诱惑：用清晰、形象的目标去审视每一条出现的信息，去判别信息是否与我们的目标有关，只要确认无关，看都不要再看，第一时间离开它，防止被它的内容带偏。\u003cbr> 3、寻找协同：让我们的同事和下属都知道我们的目标是什么，这样不仅可以让大家协助我们来寻找更多的信息，更重要的是让大家都来帮助我们不断的深化和清晰目标。还有，就是他们不会来干扰我们的工作了。\u003cbr> 4、扫视重点：对于信息的判别，要迅速的浏览关键的信息，而不是全部读一遍，否则，又会被其中的不相关但是有吸引力的内容引偏。\u003c/p>","interaction":"\u003cp>A1:昨天我本打算上网准备一下拆书的作业，结果我先后打开了这些内容：1、360卫士2、欧洲杯：葡萄牙胜威尔士3、石家庄已成为华北第一堵4、万科股权之争：无规则、不情怀的土豪之战\u003c/p>\u003cp>结果，我大约过了二十分钟才想起自己正事。\u003c/p>\u003cp>同时，在单位时由于以前浏览器主页设置的是新浪之类网站，每当收邮件时，一打开浏览器时网站就弹出各种的新闻（而且很有针对性，象我这样的体育迷看到的都是热门体育类消息），结果……直到把主页换成了办公网站，这个问题才解决了。包括后来的微博、微信，经常是看了半天还没进入到主题。\u003c/p>\u003cp>A2:从下周起落实三件事，一是用好便签，每次便签写下要完成的几项工作，时时提醒自己；二是用好彩笔，通过勾选涂描提醒自己重点进展；三是把这个便签贴在家里和单位的电脑上。 -grid-mode:char&#39;&gt;结果，我大约过了二十分钟才想起自己正事。\u003c/p>\u003cp>同时，在单位时由于以前浏览器主页设置的是新浪之类网站，每当收邮件时，一打开浏览器时网站就弹出各种的新闻（而且很有针对性，象我这样的体育迷看到的都是热门体育类消息），结果……直到把主页换成了办公网站，这个问题才解决了。包括后来的微博、微信，经常是看了半天还没进入到主题。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2271,"quote":"\u003cp>如何带有目的地消费信息\u003cbr> 当你对于信息的使用缺乏目的性时，你便无法掌控信息。如果一开始便带有目的性，你会自动对信息进行筛选过滤，这能帮助你分辨有关及无关的信息。多数人接收到的大量邮件就是个很好的例子。有些是需要你关注的私人邮件，有此进立即删除的垃圾邮件，问题是剩下的那些邮件。80/20法则再次适用：这些信息中可能只有20%适用于你最重要的目标，剩余的80%可能只是在一般意义上比较有趣，并没有直接的关系。我们将在第12章具体讨论如何处理邮件，目前还是来看看你所能够运用的四条策略，这些策略同样也可以运用于处理其他来源的信息。\u003cbr> ——在接触新信息之前，先快速提醒自己此时最具吸引力的话题，那些和你最要的目标相关的话题。\u003cbr> ——如果你知道这条信息并不相关，看都不要去看它一眼，直接丢弃这条信息或者先将这条信息搁置在一边，直到它所含的信息可能更加相关时再去看。\u003cbr> ——在可能的时候，分配其他人进行这份材料的查阅工作，告诉他们你正在寻找什么信息。他们可以复印或者扫描相关内容以供你查看。\u003cbr> ——对于你所面对的信息，扫视最要的信息点而不是全部通读。\u003c/p>","explains":"\u003cp>今天我们选的片段来自于《专注力》，书中有一个重要的原则叫二八法则。二八法则有很多种分法，比如我们接收到的信息，20%是紧急的80%是非紧急的；20%是有意义的80%是无意义的；20%是可以快速处理的80%则要费大量时间；20%有我们当前的工作有关80%是无关的。\u003c/p>\u003cp>而我们的思路经常被所看到的内容带偏，因为看到的内容会更加形象、更加生动，它们比我们思路中虚拟的想法更加吸引人。查询信息的四个关键步骤如下：\u003cbr> 1、明确目标：无论做什么事情前，都再次确认或多次确认一下自己的行动目标，确保它更加清晰化，最好是以一个形象出现在自己的脑海中。\u003cbr> 2、远离诱惑：用清晰、形象的目标去审视每一条出现的信息，去判别信息是否与我们的目标有关，只要确认无关，看都不要再看，第一时间离开它，防止被它的内容带偏。\u003cbr> 3、寻找协同：让我们的同事和下属都知道我们的目标是什么，这样不仅可以让大家协助我们来寻找更多的信息，更重要的是让大家都来帮助我们不断的深化和清晰目标。还有，就是他们不会来干扰我们的工作了。\u003cbr> 4、扫视重点：对于信息的判别，要迅速的浏览关键的信息，而不是全部读一遍，否则，又会被其中的不相关但是有吸引力的内容引偏。 在一边，直到它所含的信息可能更加相关时再去看。\u003cbr> ——在可能的时候，分配其他人进行这份材料的查阅工作，告诉他们你正在寻找什么信息。他们可以复印或者扫描相关内容以供你查看。\u003cbr> ——对于你所面对的信息，扫视最要的信息点而不是全部通读。\u003c/p>","interaction":"\u003cp>A1:昨天我本打算上网准备一下拆书的作业，结果我先后打开了这些内容：1、360卫士2、欧洲杯：葡萄牙胜威尔士3、石家庄已成为华北第一堵4、万科股权之争：无规则、不情怀的土豪之战\u003c/p>\u003cp>结果，我大约过了二十分钟才想起自己正事。\u003c/p>\u003cp>同时，在单位时由于以前浏览器主页设置的是新浪之类网站，每当收邮件时，一打开浏览器时网站就弹出各种的新闻（而且很有针对性，象我这样的体育迷看到的都是热门体育类消息），结果……直到把主页换成了办公网站，这个问题才解决了。包括后来的微博、微信，经常是看了半天还没进入到主题。\u003c/p>\u003cp>A2:从下周起落实三件事，一是用好便签，每次便签写下要完成的几项工作，时时提醒自己；二是用好彩笔，通过勾选涂描提醒自己重点进展；三是把这个便签贴在家里和单位的电脑上。 -grid-mode:char&#39;&gt;结果，我大约过了二十分钟才想起自己正事。\u003c/p>\u003cp>同时，在单位时由于以前浏览器主页设置的是新浪之类网站，每当收邮件时，一打开浏览器时网站就弹出各种的新闻（而且很有针对性，象我这样的体育迷看到的都是热门体育类消息），结果……直到把主页换成了办公网站，这个问题才解决了。包括后来的微博、微信，经常是看了半天还没进入到主题。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1470651736000,"updated_at":1504435527000,"ria":true},{"id":301,"topic":"学会使用二八法则找到工作中最为重要的20%","learn_goal":"顺利通过tf2-4","remark":"整个世界好像串通好了要一致阻碍你拥有专注力。每时每刻，你忙于应付外界的各种干扰。这种情况下，若你还能取得一星半点的成就，那简直是奇迹！要想改变这种手忙脚乱四处救火的情形，你必须拥有专注力！从现在开始，认清对你来说最重要的事，排除一切无关干扰，专注地投入其中。你的成功概率将以指数方式增长！实现你心中真正渴望的目标！","level":"TF2-3","duration":50,"status":0,"type":0,"chaishujia":{"username":"枫树","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003c专注力-化繁为简的力量> 本书作者:于尔根﹒沃尔夫 这里所讲的化繁为简包括两方面：1、学会使用二八法则，找到工作生活当中最为重要的20%，专注于做重要的事情，让自己的生活变得更简单；2、把复杂的事情简单化，越是复杂的事情越是可以用简单的方法解决，通过目标分解、第二自我等方法，看似越来越多，但却更加有利于行动。（A）本书不是关于“原因（why）和什么what” 而是关于“怎样（how）”你可能已经知道你想从生活工作当中得到什么，但在大脑中思考更多的是“怎样从这里到哪里”(B)本书将一步步跨越这个过程：先决定你想要的，找出失败的原因，弄清你时间利用的干扰因素，从而学会克服阻碍绝大数取得成功的障碍，最终到达成功的彼岸。接下来我将带你走进这本书，准备好给自己和别人一个惊喜，首先我们来看第一个片段：专注生活工作中最重要的的20%，让生活变得更加精彩！","ratings_count":0,"texts":[{"id":691,"quote":"《专注力化繁为简的惊人力量》P7-8","explains":"首先我们先看一下，这里所讲的二八法则，也就是众所周知“帕累托法则”有人知道了解没？ 其实它的核心思想是你的80%的收益或价值来源于你20%的努力。可能会有人会说他与我有什么关系，到底如何能运用到生活工作当中？在这个片段当中提到一个作者调查关于花费在真正做这件事上花费的时间，其中包括艺术家、教师、医生等，但是得到同样一个结论：他们只花费了10%—20%的时间做这些最有产出行结果的事情，话句话说：他们大多数的时间花费在一些产出性结果少的事情上，也就数说我们完全可以把我们更多的时间和精力花费在重要事情的20%上，提高我们的工作效率，从此让你摆脱整天忙的和狗一样，却收获甚少，得不到上级和同事的认可。我举个栗子：我作为一个学生，但是真正用在学习上的时间并不多，各位应该经历过，也比较了解，我就用我本周四的一天来看看，我到底有多长时间用在学习获得只是或技能;周四有两节课，共4个小时，能专心听课的也就2个小时把，其中一半的时间和其他人闲聊，玩手机。开两次班会，一次优秀团员竞选，一次导员安全教育大会，用了两个多小时。晚上自己去上自习，学了一个多小时的英语，这也就是我一天的忙碌的学习工作，其实真正用在学习上也就不到3个小时，这也就是我应该关注我20%事情：上课和自习，如果我能减少开会和闲聊，把更多的时间用在学习上，那我每天的收获就会多一点，通过日积月累，一定会有大的收获。 也就是说我们可以通过二八法则，找到自己最为重要20%的事情上，然后把更多的时间用在这20%上，注意：这里所说讲的把更多时间分配在20%事情上，并不代表其他80%就不用做了，其他80%可能对你没有直接的价值，但也可能是你这20%的基础。我们完全可以把一些对自己无价值上的你时间用在做20%上。","interaction":"A1\r\n激活经验\r\n今天正好是这周的最后一天，每个人也都已经工作了一周，或许每个对这一周有着不同的感触，不管是感觉充实还是失落，那我们也必要对自己一周做一个总结。那现在请各位想想从周一早上上班开始到现在你都做了那些工作，这些工作中最有价值的三件事情是，注意这里最有价值的事情是指直接帮助你取的更多金钱或者代表你所做出的最大贡献。你就可以清楚的看到你在即将过去一周中用在最有价值三件事上的时间比重。\r\n案例: \r\n小陈: 这周做的事情有上课（每天一到两节）、参加班会、整理自己的考研资料、抄作业以及实验报告、实验课、帮好哥们做室内设计、自习\r\n最有价值的事情：自习（考研复习） 上课 \r\n比例：也就20%左右\r\nA2\r\n催化应用\r\n设想一下，当你下周一早上到达办公室，倒了一杯茶准备开始一天的工作，你想到了今天做的二八评估，你要停下来问自己工作当中最为重要的20%是什么？ 然后把更多时间分配在重要的事情上面。让你新的一周更加充实。 现在小组内讨论分析？\r\n案例：\r\n小陈;自己最重要的是考研，今天有两节课，其他的时间一小时写作业，其他时间用来自习考研复习。为了保证将更多时间分配在考研复习上，有些没有必要的事情尽量不做，比如好朋友让帮忙做室内设计，找一些理由拒绝。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":692,"quote":"《专注力化繁为简的惊人力量》p22-23","explains":"上一个片段我们学到了获取巨大成果的诀窍是找到工作当中能带给你最大收益的20%，花更多的时间做这20%，少花点时间在给那些带来较少价值的80%的事情上。一旦找到自己工作当中最为重要的20%，我们便可以设定快速成功的目标。你如果以前曾经为自己设定过目标，你可会发现一些目标很难实现，而另自己沮丧，这是因为大多数目标设定的方法都有致命的错误。而这个片段提出的六问就可以帮你了解这些错误是什么，还会明白如何改正：\r\n接下来我们来看一下这六问：这里给出的目标是学习Photoshop软件，\r\n1、 明确了解现在的实际情况（越具体越好）--说事实\r\n例如：我的电脑已经安装这个软件，并且购买了该软件的课程，但是从来没学过。\r\n我已经为学习该软件做了一些准备，就是没有行动\r\n2、 过去你所做过（或没做过）的什么事造成了现在的局面？\r\n我没有安排时间学习这个程序\r\n3、 为获得想要的结果，你将做哪些不一样的事情？\r\n每周花四个小时学习这个软件\r\n4、 为了保证你可以做到上一步中明确的事情，你需要改变什么？\r\n我必须改变目前每周4小时所做的一些事情，用这四小时进行学习\r\n5、 你需要那些资源？你如何获取这些资源？为此需要放弃或付出什么？\r\n我需要的资源是时间，我将减少看韩剧和玩游戏的4小时。我用日事情软件提醒自己学习。\r\n6、 不断尝试不一样的做法，直到找到最适合自己的方法，直到成功。\r\n发现自己一个人不能坚持下去，可以找一个人和自己一块做或者找一个人监督自己。","interaction":"A3\r\n现场模拟\r\n在外企工作的小强，工作一直不顺利，得不到上级的重用，很多培训的机会也抓不住，于是他采用二八法则对自己的工作进行评估，结果发现：自己得不到重用的直接因素是：自己的英语水平太差了，特别是表达和写作。每次一些培训和升值机会都要求有一定的英语表达能力和写作能力，结果都因此失去，于是小强决定提高自己英语水平，现在请使用这六问对小强的目标进行梳理，帮助他实现目标。\r\n模拟\r\n枫树;你目前为你提高英语水平做了哪些准备，你目前的现状是？\r\n故：我已经买了相关的英语书籍，也报考了一个线上的课程。\r\n枫树:你之前也一直在学习，但是为啥没有大的提升？\r\n故：虽然报了课程，但用在上面学习没几次\r\n枫树：为了尽快提高英语水平，你需要做哪些改变？\r\n故：每周需要分配四小时学习英语\r\n枫树：那为了每周分配四小时学习英语，你需要做哪些改变？\r\n我必须把每周四小时看电视剧的时间用来学习英语\r\n枫树：那你现在需要哪些资源，如何获取这些资源\r\n故：资源：时间和与会用英语交流的机器人练习 时间可以把看电视剧的时间学习英语 \r\n枫树：就目前而言有这样的机器人虽然可以，但是用来学习，对我们现在并不现实\r\n故：那我可以找一个小伙伴和我一块学，同时多余公司里的外国人交流。\r\nA2\r\n催化应用\r\n我们在第一个片段里，已经使用二八法则对你过去的一周工作已经做了一个评估，你肯定发现了做哪些工作可以让你有更多的收获和机会，也因此设立了几个目标，决定下周开始实施，但是当你信心满满的进入工作中时，发现外界和自身许多因素在干扰你的目标，让你的目标很难实现，让你又一次陷入纠结当中，那不妨应用六问开始你的目标。\r\n总结：我们今天拆解了两个片段，第一个片段是：找到你工作当中最为重要的20%，然后多做这些工作，过程分为三步：找到目前占据工作时间的事情，接着找到最有价值的事情，然后将更多时间分配在20%上，最主要的目的是找到自己接下来的工作目标，第二片段是; 针对目标实现上的一些问题，学会用六问梳理目标，避开障碍，最终实现目标。 希望各位在接下来的工作生活当中能够学以致用，给自己也给他人一个不一样的自己！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1461852861000,"updated_at":1461853661000,"ria":true},{"id":115,"topic":"用MAD创造MAX生产力","learn_goal":"将生产力达到MAX","remark":"拖延症患者晚期？\r\ndeadline都到了，到底还有哪些待办事项都停滞不前？\r\n你的生产力到底是趋于旺盛还是濒临枯竭？\r\n如何将生产力达到MAX？\r\n还记得上周四晚上思考琦在#拆书帮翰林官方群#线上分享了“一颗胶囊拯救你一生”吗？\r\n本期活动，思考琦将继续借助《专注力》，带领大家探讨如何用大规模生产日来创造生产力的最大值，突破瓶颈，向前一步，豁然开朗。","level":"TF3-3","duration":50,"status":0,"type":0,"chaishujia":{"username":"思考琦","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"作者：于尔根•沃尔夫。\r\n书里有很多技巧，比如如何将80/20法则应用于工作和生活、如何赞美和认可他人、如何战胜拖延症、如何战胜堆积如山的文案工作、如何应对最后期限和多项任务、如何有条不紊的完成目标……一言以蔽之，技巧拿走，拆为己用，必将成为高效能专注人士。而我今晚拆解的拆页源自第14章，主题为用MAD创造MAX生产力！就是说当deadline来了，如何用MAD疯狂模式创造第一生产力，完成任务。","ratings_count":0,"texts":[{"id":118,"quote":"大多数项目都有进度减慢、延迟或其他不顺利的事情发生的时候，这不仅会减弱参与者的动力，也会消弱士气。这是使用高度专注技巧的好时机。我将这一技巧成为MAD：大规模行动日（MASSIVE ACTION DAY首字母的缩写）。这一天你抛开其他所有事，集中全部注意力，在8个、10个或12个小时内完成平时可能花一星期才能完成的事。当然你并不会想要一直保持这个速度；这和长跑运动员要超过对手时所进行的冲刺道理相同。他能够给项目注入新的能量，能量重振你和其他人的热情和信心。以下是如何进行MAD的方法：\r\n1. 提前一天准备好所有必须物品和文件。在大规模行动日，你不想为寻找文件、订书机、或任何其他东西而浪费一点时间。\r\n2.在大规模行动日开始时为这一天设定明确的目标。制定一份一小时为单位的行动计划。\r\n3.完成每项任务后再计划表上相应做出记号，保持享受任务完成所带来的成就感。\r\n4.每90分钟休息一次。研究表明，90分钟是注意力集中的循环周期，所以没过一个半小时休息10分钟将会比连续工作更具成效。\r\n5.在休息时做些体力活动：绕建筑物快走或上下楼梯，伸展运动甚至原地跑步都可以。你可以做任何能够加速血液流动的事。保证大量饮用水和健康零食的供给。如果你通过喝咖啡或者喝茶来保持清醒，要少量多饮，而不要多量饮水。\r\n6.在大规模行动日结束时，进行庆祝并给自己一定的奖励——一顿丰盛的晚餐，看场电影，或者任何其他你喜欢的事。","explains":"Deadline来了，如何利用MAD创造MAX生产力，方法如下：\r\n1.提前设定MAD的具体目标或任务一览表，且以小时或者你习惯的时间单位制定。即具体时间+具体任务表；\r\n2.提前准备好MAD里所有目标的相关物品和MAD里的吃喝拉撒用品，如书籍、电脑、文件、茶水、水果、零食、咖啡等；\r\n3完成目标或任务list中的任何一项，及时mark做标记，比如用对勾，OK, 2手势等，怎么开心你怎么来，但是切记要好操作。\r\n4. 每90分钟休息一次，用快走、跑步、上下楼梯、瑜伽等体力运动方式换脑；\r\n5.全部task或目标完成，庆祝，嗨起来，吃，喝，看电影，旅行都可以！\r\n当然，最后要强调的是，每90分是经过科学研究的人的专注力持续时间。其中目标以单位制定和这个90分钟休息一次，大家也可以根据自己的习惯更改，但是切记要时刻换脑，否则MAD一天下来，整个人会觉得累的不行不行的。","interaction":"年关将至，可是总还感觉年前还有几件事没完成，惴惴不安？比如：我，10月份新西兰游记，12月份韩国游记，都还没写，不写感觉是我心里永远的梗！小伙伴，你呢？你有哪些梗想在春节前完成或者想在未来一个内的某些时间完成？\r\n现在请大家根据自己的刚才的优劣势扬长避短，列自己近期deadline到了，还未完成的事情。但是一定要注意按照我们的MAD法来列哦！\r\n此处都为图片（显示不了）\r\n现场小伙伴们都认真的写了MAD，但是因为涉及隐私，只放一个小伙伴完善后给我的MAD\r\n【现场小伙伴写完MAD的感受】\r\n原来需要花这么多时间呢！\r\n之前没有想过物品的事情，以后得注意，可以提高效率！\r\nMAD很好用，年前正好有一些事需要做！\r\n【总结+祝福】\r\n感谢小伙伴这么认真的做自己的MAD！不过我要提醒大家：MAD虽然好用又高效，但是切记不要多用，不然真会MAD的！用MAD其实是让大家通过制定目标分解任务，养成做计划和坚决执行的习惯，而目标不是要MAD哦，\r\n以上就是我所有的分享，如果deadline来了，因为拖延或者突发事故而导致的众多任务没有做，那么请记住MAD法，如何利用MAD创造MAX生产力呢？总结20字：细化目标、备足物品、标记完成、运动换脑、奖励生产！\r\n最后，衷心希望大家在春节前把心中的梗用MAD法完成，一身轻松的进入到过年模式，好好陪家人度过一个个精心时刻！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1454661100000,"updated_at":1454661100000,"ria":true},{"id":109,"topic":"如何理智消费信息","learn_goal":"如何在信息爆炸的时代理智的甄别和消费信息","remark":"每天，信息排山倒海。\r\n什么信息是真实可靠的？什么是宣传或错误信息？什么消息刚刚发生？什么信息已经发生？什么信息在某一时刻和我们面临的挑战有关？\r\n本期活动，思考琦将借助《专注力》，带领大家一切探讨如何在信息爆炸的时代理智的甄别和消费信息，将信息拆为己用，迎接更加丰盈的自己！","level":"TF3-3","duration":45,"status":0,"type":0,"chaishujia":{"username":"思考琦","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"今天我拆解的图书是《专注力》，首先问下，当爸妈给你打电话抱怨说怎么这么久没给家里打电话了？当好朋友突然有一天也跟你说：你这个死人，我们什么时候能见上一面？大家都是如何答复的？哎呀，我忙的给忘记，我快忙疯了\r\n再有，自己总觉得自己事业和人生其实可以比现场更成功，但是无论如何努力，好像都没有实现这个更成功，反而觉得自己的潜力无法释放而沮丧？中枪的请举手？\r\n好，那么《专注力》一书主要就来解决这个没时间没精力忙成狗的问题的，通过如何分配时间和经历专注重要目标而实现高效率。比如，如何治疗拖延症、如何利用80/20法则处理工作和生活、如何赞美和认可他人、如何利用第二自我解决因心情不好而拖沓的重要事情、如何高效处理多项任务等等。总之，17章章章干货，拆为己用，让我们一起赶走没时间没精力，迎来高效率慢生活。","ratings_count":0,"texts":[{"id":112,"quote":"原文片段1：\r\n这个时代里，任何人都能在很短的时间内，创建一个网站、博客或者播客（通过互联网传输的音频或视频），吧一些不实的信息发布出来，或者把自己伪装成权威，实际上他们并没有受过相关教育或者拥有任何相关经验。也可能这些人确实木有某些资质，但他们发布信息的隐藏目的是向你兜售产品或者改变你对于某件事情的看法。当你准备采用某条信息时，对信息北京和可靠性进行考察是很有必要的。搜索引擎的好处之一就是相对于依赖于一条信息源，他们的出现使得不同信息源的横向对比变得容易。如果信息很重要,在基于信息采取任何行动前，需要反复对信息的真实进行考察。\r\n原文片段2：\r\n在接触新信息之前，先快速提醒自己此时最具吸引力的话题，那些和你最重要的目标相关的话题。\r\n如果你知道这条信息并不相关，看都不要去看他一眼，直接丢弃这条信息或者先将这跳信息搁置在一边，知道它所包含的信息可能更加相关时再去看。\r\n在可能的时候，分配其他人进行这份材料的查阅工作，告诉他们你正在寻找什么信息。他们可以复印或者扫描相关内容以供你查看。\r\n对于你所面对的信息，扫描最重要的信息点而不是全部通读。利用章节名称、标题以及副标题、主题句子、标注下划线或者粗体的文字，以及章节结尾关键点来引导你找到最相关的内容。","explains":"R1之I:\r\n信息泛滥，排山倒海，当工作和生活中你想使用这条信息时，最好做这样的事情：\r\n1、 拿出质疑或怀疑的精神，反问自己：这条信息可靠吗？事实吗？权威吗？时效吗？\r\n2、 利用搜索引擎或线下工具如维基百科、字典词典、文献资料、官方网站/微信公众号/微博等方式查找数据出处，顺藤摸瓜根据发布时间、地点和内容验证其真实性、权威性、时效性；\r\n3、 分析这条信息背后的真正的目的是什么？和我有什么关联？比如是想卖东西，还是纯碎的生活感悟，亦或是新产品、新思维问世？我需要买吗？我同意这个观点吗？我愿意尝试应用这种技巧和新思维吗？\r\nR2之I:\r\nI(重述原文)高效的找出对自己有用的信息需要如下步骤：\r\n1、提前设定自己的关注的主题或话题或目标\r\n2、只浏览标题、副标题、主题句子、标有重点符号的文字亦或是目录等，话题或主题相关的进去阅读，无关直接跳过\r\n3、情况允许，把你关注的话题或主题告诉别人，让别人帮你查找出相关信息邮件、复印或者扫描等方式给你","interaction":"分享1：每次听罗胖子的早晨语音分享或者书籍推荐，就冲动的不得了，又一次一下子买了200多块的书，后来买了又没看，其实就是在搞个人崇拜。\r\n分享2：我们工作主要是做媒体编辑策划的，出方案之前也会尽量多的插比较权威的文件，但是每次拿给别的部门或者领导看时，总是还会听到很多的反驳和质疑，于是乎我们就会返工。其实后来的A2就是每次要备注，文献出自哪儿，大家就不会质疑了。\r\n分享3：四个想减肥的小伙伴通过互帮互助和网络搜索找到KEEP app，并建立了家里蹲减肥小组。\r\n分享4：考法语三级，去除了之前在网上搜索的N多信息源，求助老师的推荐，提高了效率。锁定了学习的方式。\r\n想考潜水证，但是自己搜索没找到的时候，偶然的一次滑雪活动因为认识到了几个小伙伴而拓宽了推荐。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1454247886000,"updated_at":1454247886000,"ria":true}]};